window.TXB=window.TXB||{};TXB["alab/Jer"]={"1:1":"هذه نبوءة إرميا بن حلقيا أحد الكهنة المقيمين في عناثوث بأرض سبط بنيامين.","1:2":"وقد أعلن الرب له هذه النبوءة في عهد يوشيا بن آمون ملك يهوذا، في السنة الثالثة عشرة من ملكه.","1:3":"وذلك في أثناء حقبة حكم يهوياقيم بن يوشيا ملك يهوذا وحتى نهاية الشهر الخامس من السنة الحادية عشرة من ولاية صدقيا بن يوشيا ملك يهوذا، الذي فيه تم سبي أهل أورشليم.","1:4":"فأوحى الرب إلي قائلا:","1:5":"«قبلما شكلتك في أحشاء أمك عرفتك، وقبلما ولدت أفرزتك، وأقمتك نبيا للأمم».","1:6":"فقلت: «آه، أيها السيد الرب إني لا أعرف ماذا أقول، لأني مازلت ولدا»","1:7":"ولكن الرب أجابني: «لا تقل إني لست سوى ولد، لأنك ستذهب إلى كل من أبعث بك إليه، وتنطق بكل ما آمرك به.","1:8":"لا تخف من حضرتهم لأني أنا معك لأنقذك».","1:9":"ثم مد الرب يده ولمس فمي وقال: «ها أنا أضع كلماتي في فمك.","1:10":"انظر. ها أنا قد وليتك على أمم وشعوب لتستأصل وتهدم وتبدد وتقلب وتبني وتغرس».","1:11":"وسألني الرب: «ماذا ترى ياإرميا ؟» فأجبت: «أرى غصن لوز».","1:12":"فقال لي الرب: «قد أحسنت الرؤية، لأني ساهر على كلمتي لأتممها».","1:13":"وعاد الرب يسألني مرة أخرى: «ماذا ترى؟» فأجبت: «أرى قدرا تغلي، ووجهها متحول عن الشمال نحو الجنوب».","1:14":"فقال لي الرب: «من الشمال يكون تدفق الشر على جميع سكان الأرض.","1:15":"لأني ها أنا داع جميع عشائر الممالك الشمالية ليأتوا، فينصب كل واحد منهم عرشه عند مدخل بوابات مدينة أورشليم وعلى جميع أسوارها المحيطة بها وعلى جميع مدن يهوذا.","1:16":"وأصدر عليهم حكم قضائي من أجل كل شرهم لأنهم تركوني، وأحرقوا بخورا لآلهة أخرى وعبدوا صنعة أيديهم.","1:17":"أما أنت فتأهب، وقم وكلمهم بكل ما آمرك به. لا تخف من حضرتهم لئلا أفزعك أمامهم.","1:18":"انظر ها أنا قد جعلتك اليوم قويا كمدينة حصينة، وكعمود من حديد، وكأسوار من نحاس، لتجابه كل أهل الأرض، وملوك يهوذا وأمراءها وكهنتها وشعب البلاد،","1:19":"فيحاربونك ولكن لا يقهرونك، لأني أنا معك لأنقذك يقول الرب».","2:1":"وقال لي الرب:","2:2":"«امض وأعلن في مسامع أهل أورشليم هاتفا: هذا ما يقوله الرب: قد ذكرت لك ولاء صباك، ومحبتك كعروس لي، وكيف تبعتني في البرية في أرض لا زرع فيها.","2:3":"كان إسرائيل مقدسا للرب وباكورة غلته، وكل من يعتدي عليه، يرتكب إثما ويحل به شر.","2:4":"اسمعوا كلمة الرب ياذرية يعقوب، وياجميع عشائر إسرائيل:","2:5":"أي خطأ وجده في آباؤكم حتى نبذوني وضلوا وراء الباطل وصاروا باطلا؟","2:6":"لم يسألوا: أين الرب الذي أخرجنا من مصر وقادنا في البرية، في أرض متاهات وحفر، في أرض قفر جدباء، في أرض ظلال الموت، ما اجتازها أحد ولا أقام فيها بشر؟","2:7":"وأتيت بكم إلى أرض خيرات لتستمتعوا بأكل ثمارها وطيباتها. ولكنكم عندما دخلتموها نجستم أرضي وجعلتم ميراثي رجسا.","2:8":"إن الكهنة لم يسألوا: أين الرب؟ وأهل الشريعة لم يعرفوني، وحكام الشعب تمردوا علي، والأنبياء تنبأوا بتأثير بعل وضلوا وراء ما لا جدوى منه.","2:9":"لذلك أخاصمكم وأخاصم أحفادكم يقول الرب.","2:10":"فاعبروا إلى جزيرة قبرص والسواحل الغربية، وأرسلوا إلى قيدار، وتفحصوا جيدا، وانظروا: هل جرى مثل هذا؟","2:11":"هل استبدلت أمة آلهتها مع أنها ليست حقا آلهة؟ أما شعبي فاستبدل مجده بما لا جدوى منه.","2:12":"فاذهلي أيتها السماوات، وارتجفي وارتعدي جدا.","2:13":"قد ارتكب شعبي شرين: نبذوني أنا ينبوع الحياة، وحفروا لأنفسهم آبارا متصدعة لا تضبط ماء.","2:14":"هل إسرائيل عبد، أم وليد بيت العبودية؟ فما باله أضحى نهبا؟","2:15":"قد زأرت الأسود عليه زئيرا مدويا، وجعلت أرضه خربة. أحرقت مدنه فأصبحت مهجورة.","2:16":"كذلك رجال ممفيس وتحفنيس حطموا تاج رأسك.","2:17":"ألست أنت التي جلبت هذا الدمار على نفسك، لأنك تناسيت الرب إلهك حين قادك في الطريق؟","2:18":"والآن ما بالك تتوجهين صوب مصر لشرب مياه شيحور؟ وما بالك تقصدين إلى أشور لشرب مياه الفرات؟","2:19":"إن شرك يقرعك، وارتدادك يؤنبك. فتبيني واعلمي أن نبذك للرب إلهك شر ومرارة، وأنك تجردت من مهابتي.","2:20":"قد حطمت نيري من زمن بعيد، وقطعت قيودك وقلت: لن أتعبد لك، وصرت تضطجعين كزانية فوق كل أكمة مرتفعة وتحت كل شجرة خضراء (أي عبدت الأوثان).","2:21":"وأنا غرستك ككرمة مختارة، ومن بذور سليمة كاملة، فكيف تحولت إلى كرمة فاسدة غريبة؟","2:22":"وإن اغتسلت بالنطرون، وأكثرت من استعمال الإشنان (الصابون)، فإن لطخة إثمك تظل ماثلة أمامي.","2:23":"كيف تقولين: لم أتدنس ولم أذهب وراء البعل؟ تأملي في طريقك في وادي هنوم، واعرفي ما ارتكبت أيتها الناقة الجامحة الهائمة في طرقها بحثا عن جمل.","2:24":"أنت أتان فرا اعتادت حياة القفر، تتنسم في شهوتها الهواء لعلها تظفر برائحة حمار وحشي. ومن يردها؟ لا يعيا طالبوها لأنهم يجدونها حاضرة في موسم التزاوج.","2:25":"صوني قدمك من الحفاء، وحلقك من الظمأ، لكنك قلت: لا جدوى من الأمر، فقد أحببت آلهة غريبة، وسأسعى وراءها.","2:26":"وكما يعتري الخزي السارق حين يقبض عليه، كذلك اعترى الخزي بيت يعقوب: هم وملوكهم، ورؤساءهم، وكهنتهم وأنبياءهم.","2:27":"إذ قالوا لنصب الخشب: أنت أبي، وللحجر المنحوت صنما: أنت أنجبتني. وولوا أدبارهم وليس وجوههم نحوي، وفي وقت بليتهم استغاثوا بي قائلين: قم وأنقذنا.","2:28":"فأين إذا الآلهة التي صنعتموها لأنفسكم؟ لتقم إن كانت قادرة على إنقاذكم في وقت ضيقكم، لأن عدد آلهتكم ياأبناء يهوذا صار كعدد مدنكم.","2:29":"لماذا تخاصمونني وأنتم كلكم قد تمردتم علي؟","2:30":"عبثا عاقبت بنيكم، فهم أبوا التقويم وافترست سيوفكم أنبياءكم كأسد كاسر.","2:31":"وأنت أيها الجيل، اسمع قضاء الرب: أكنت صحراء لإسرائيل أو أرض ظلام دامس؟ إذا لماذا يقول شعبي: نحن طليقون نسعى حيث شئنا، ولن نقبل إليك بعد؟","2:32":"هل تنسى عذراء زينتها؟ أو عروس حلي زفافها؟ لكن شعبي نسيني أياما لا تحصى.","2:33":"لكم برعتم في تمهيد طرقكم طلبا للشهوات، فعلمتم أساليبكم حتى للشريرات.","2:34":"فوجد في أذيالكم أيضا دم المساكين الأبرياء الذين لم تقبضوا عليهم متلبسين بجريمة الاقتحام. ومع كل ذلك","2:35":"تقولون: نحن أبرياء، فلذلك قد تحول عنا غضب الرب. غير أني سأدينكم لقولكم إننا لم نخطيء.","2:36":"لماذا تتهافتون على تغيير اتجاهكم؟ ستلحق بكم مصر الخزي كما ألحقه بكم الأشوريون.","2:37":"من هناك تخرجون أيضا وأيديكم تغطي رؤوسكم خجلا، لأن الرب رفض الذين وثقتم بهم، ولن يصيبكم منهم نجاح.","3:1":"قيل: إن طلق رجل زوجته فانصرفت من عنده، وتزوجت بآخر، فهل يرجع إليها زوجها الأول؟ ألا تتدنس تلك الزوجة أشد تدنس؟ أما أنت ياشعب الله فقد زنيت مع عشاق كثيرين، فهلا ترجع إلي؟ يقول الرب.","3:2":"ارفعي عينيك إلى الهضاب وتأملي، أهناك مكان لم تضاجعي فيه؟ (أي لم تعبدي فيه الأوثان). قد جلست لهم على قارعة الطريق كالأعرابي في البادية ودنست الأرض بزناك وعهارتك.","3:3":"لذلك امتنع عنك الغيث، ولم تهطل أمطار الربيع، ومع ذلك صارت لك جبهة زانية تأبى أن تخجل.","3:4":"ألم تدعني الآن قائلة: ياأبي، أنت رفيق صباي؟","3:5":"أيظل غاضبا دائما؟ أيبقى ساخطا إلى الأبد؟ انظري، هذا ما نطقت به، ولكنك ارتكبت كل ما استطعت من شر».","3:6":"وقال لي الرب في أيام حكم الملك يوشيا: «هل شاهدت ما فعلت الخائنة إسرائيل؟ كيف صعدت إلى كل أكمة عالية، وتحت كل شجرة خضراء وزنت هناك (أي عبدت الأوثان)؟","3:7":"وقلت بعد أن ارتكبت كل هذه الموبقات، إنها سترجع إلي، ولكنها لم ترجع. وشهدت هذا أختها الغادرة يهوذا،","3:8":"ورأت أني أرسلت كتاب طلاق إلى الغادرة إسرائيل لعهرها فلم تفزع أختها الخائنة يهوذا بل مضت هي أيضا وزنت (أي عبدت الأوثان).","3:9":"ولأنها استهانت بالزنى، فقد نجست الأرض وارتكبت الفجور (أي عبدت الأوثان) مع الحجر ومع الشجر.","3:10":"ومع هذا كله لم ترجع إلي أختها الخائنة يهوذا من كل قلبها، إنما تظاهرت بذلك»، يقول الرب.","3:11":"وقال لي الرب: «إن إسرائيل الخائنة قد بررت نفسها أكثر من الخائنة يهوذا.","3:12":"فاذهب وأعلن هذه الكلمات نحو الشمال وقل: ارجعي أيتها الخائنة إسرائيل، فأكف غضبي عنكم لأني رحيم، ولن أسخط عليكم إلى الأبد.","3:13":"إنما اعترفي بإثمك وأقري أنك قد تمردت على الرب إلهك، وأغدقت غرامك على الغرباء تحت كل شجرة خضراء، وأنك أبيت طاعة صوتي.","3:14":"فارجعوا أيها الأبناء الغادرون، لأني أنا سيدكم، فآخذكم واحدا من المدينة واثنين من العشيرة وآتي بكم إلى صهيون،","3:15":"وأقيم عليكم رعاة يحظون برضى قلبي، فيرعونكم بالمعرفة والفطنة.","3:16":"وحين تكثرون وتملأون الأرض، فإنكم لن تسألوا بعد عن تابوت عهد الرب ولن يخطر ببالكم ولن تذكروه، ولن تفتقدوه أو تسعوا لصنعه ثانية.","3:17":"ويدعون في ذلك الحين مدينة أورشليم كرسي الرب، وتجتمع إليها كل الأمم للمثول في حضرة الرب، ولن يضلوا وراء عناد قلوبهم الشريرة.","3:18":"وتنضم في تلك الأيام ذرية يهوذا إلى ذرية إسرائيل ويأتون معا من أرض الشمال إلى الديار التي أورثتها لآبائهم.","3:19":"ولكني قلت في نفسي: لشد ما يسعدني أن أقيمك بين الأبناء وأورثك أرضا شهية هي أجمل ميراث بين الأمم. وفكرت أنك تدعينني ياأبي، ولن ترتدي عن اتباعي.","3:20":"حقا ياذرية يعقوب، قد كنتم غير أمناء لي، مثل زوجة غادرة تخلت عن زوجها».","3:21":"تردد صوت في المسامع من على الهضاب المرتفعة، هو بكاء وابتهال أبناء إسرائيل لأنهم حرفوا طريقهم، ونسوا الرب إلههم.","3:22":"«فارجعوا أيها الأبناء المرتدون فأشفي ارتدادكم». ويقولون: «ها نحن نقبل إليك لأنك أنت الرب إلهنا.","3:23":"حقا إن عبادة الأصنام على التلال وممارسة الطقوس الوثنية على الجبال لا جدوى منها. إنما بالرب إلهنا خلاص إسرائيل.","3:24":"لقد التهم خزي الأوثان تعب آبائنا منذ صبانا، وافترس غنمهم وبقرهم وأبناءهم وبناتهم.","3:25":"فلننطرح في خزينا، وليغمرنا عارنا لأننا أخطأنا في حق الرب إلهنا، نحن وآباؤنا منذ صبانا حتى هذا اليوم، ولم نطع صوت الرب إلهنا».","4:1":"ويقول الرب: «إن رجعت إلي ياشعب إسرائيل، وأزلت أصنامك المقيتة من أمامي، وكففت عن الضلال،","4:2":"وإن حلفت بالحق والعدل والبر قائلا: حي هو الرب، عندئذ تتبارك به الأمم، وتفتخر.","4:3":"لأن هذا ما يعلنه الرب لرجال يهوذا ولأهل أورشليم: احرثوا لكم حرثا، ولا تزرعوا بين الأشواك.","4:4":"اختتنوا للرب، وأزيلوا قلف قلوبكم (أي طهروا عقولكم وقلوبكم وليس أجسادكم فقط) لئلا يتفجر غضبي كنار فتحرق وليس من يخمدها، من جراء أعمالكم الشريرة.","4:5":"أذيعوا في يهوذا، وأعلنوا في أورشليم قائلين: انفخوا بالبوق في البلاد، ونادوا بصوت مرتفع، وقولوا: احتشدوا ولندخل المدن المحصنة،","4:6":"ارفعوا الراية داعين للجوء إلى صهيون. لوذوا بمأمن. لا تتقاعسوا، لأني جالب عليكم من الشمال دمارا وخرابا.","4:7":"قد برز أسد من أجمته، وزحف مدمر الشعوب. قد أقبل من خدره ليخرب أرضكم، فتصبح مدنكم أطلالا مهجورة من السكان.","4:8":"لذلك تمنطقوا بالمسوح، ونوحوا وولولوا، لأن غضب الرب المحتدم لم يرتد عنا»","4:9":"ويقول الرب: «في ذلك اليوم ينهار قلب الملك وقلوب رجال دولته خوفا. ويعتري الكهنة الفزع، ويستولي الذهول على الأنبياء».","4:10":"عندئذ قلت: «آه أيها السيد الرب، حقا إنك خدعت هذا الشعب، وأوهمت أهل أورشليم قائلا: سيكون لكم سلام، وها السيف قد بلغ حد النفس.","4:11":"ويقال في ذلك الحين لهذا الشعب ولأهل أورشليم: ستهب ريح لافحة من هضاب الصحر اء نحو بنت شعبي، لا تستهدف التذرية ولا التنقية،","4:12":"إنما هي ريح أشد عتوا منها، تهب بأمري، فأصدر أنا أيضا أحكامي عليهم».","4:13":"انظروا، ها هو مقبل كسحاب، ومركباته كزوبعة، وجياده أسرع من النسور. ويل لنا لأننا قد هلكنا.","4:14":"ياأورشليم، اغسلي من الشر قلبك فتخلصي. إلى متى تظل أفكارك الباطلة مترعرعة في وسطك؟","4:15":"ها صوت ينادي من أرض ذرية دان، يعلن عن وقوع كارثة من جبل أفرايم.","4:16":"خبروا الأمم وأعلنوه لأهل أورشليم: إن جيش المحاصرين مقبل من أرض بعيدة، وقد أطلق هتافات الحرب على مدن يهوذا.","4:17":"أحاطوا بها كحراس الحقول لأنها تمردت علي»، يقول الرب.","4:18":"«طرقك وأعمالك جرت عليك هذا العقاب، هذا قصاصك وما أمره من قصاص، لأنه يخترق ذات قلبك.","4:19":"لشد ما أتعذب! لشد ما أتعذب! قلبي يتلوى ألما. فؤادي يئن في داخلي فلا أستطيع الصمت، لأني سمعت دوي البوق وصيحات القتال.","4:20":"كارثة في أعقاب كارثة، والأرض قاطبة قد استحالت خرابا، فتهدمت في لحظة خيامي، وبيوتي تدمرت بغتة.","4:21":"إلى متى أظل أرى راية المعركة، وأسمع دوي البوق؟","4:22":"إن قومي حمقى لا يعرفونني. هم أبناء أغبياء مجردون من الفهم، حاذقون في ارتكاب الشر، وجهلاء في صنع الخير».","4:23":"تأملت الأرض فإذا هي خربة خاوية، وتطلعت إلى السماء فإذا هي مظلمة.","4:24":"نظرت إلى الجبال وإذا بها ترتجف، وإلى الآكام وإذا بها تتقلقل.","4:25":"تلفت حولي فلم أجد إنسانا، وإذا كل الطيور قد هربت.","4:26":"نظرت وإذا بالأرض الخصيبة قد تحولت إلى بر ية، وأصبحت جميع مدنها أطلالا أمام الرب وأمام غضبه المحتدم.","4:27":"وهذا ما يقوله الرب: «ستحيق الوحشة بكل الأرض، ولكني لن أفنيها.","4:28":"فمن أجل هذا تنوح الأرض وتظلم السماوات من فوق، لأني قد نطقت بقضائي. وهكذا قررت، لذلك لا أندم ولا أرجع عن عزمي.","4:29":"من جلبة الفارس ورامي السهام يهرب أهل المدن، ويوغلون في الغابات ويتسلقون الصخور. قد أصبحت المدن جميعها مهجورة لا يقيم فيها إنسان.","4:30":"وأنت أيتها المدينة الموحشة، ماذا تصنعين؟ مهما لبست الثيا ب القرمزية، وتحليت بزينة من ذهب، مهما كحلت عينيك بالأثمد، فباطلا تجملين ذاتك، فقد نبذك عشاقك وسعوا للقضاء عليك.","4:31":"لأني سمعت صرخة كصرخة امرأة في مخاض، وأنة عذاب كعذاب من تقاسي في ولادة بكرها. إنها صرخة ابنة صهيون التي تزفر لاهثة وتبسط يديها قائلة: «ويل لي! قد غشي علي أمام القتلة».","5:1":"اذرعوا شوارع أورشليم ذهابا وإيابا، وانظروا واعتبروا. ابحثوا في أرجاء ساحاتها لعلكم تجدون رجلا واحدا يجري العدل وينشد الحق، فأصفح عنها.","5:2":"فإنهم وإن قالوا: حي هو الرب فإنما يحلفون زورا.","5:3":"أيها الرب، أليست عيناك تطلبان الحق؟ لقد عاقبتهم ولكنهم لم يتوجعوا. أهلكتهم ولكنهم أبوا التقويم. صلبوا وجوههم أكثر من الصخر، ورفضوا التوبة.","5:4":"فقلت في نفسي: «إنما هم مساكين حمقى، يجهلون طريق الرب وقضاء إلههم.","5:5":"فلأقصدن العظماء وأكلمهم لأنهم يعرفون طريق الرب وقضاء إلههم». فإذا هؤلاء جميعا قد حطموا النير وقطعوا الربط.","5:6":"لذلك ينقض عليهم أسد من الغاب ويقتلهم، ويفترسهم ذئب من الصحراء، ويكمن النمر حول مدنهم، فيمزق إربا كل من يخرج منهم، لأن آثامهم كثيرة، وارتداداتهم متعاظمة.","5:7":"«كيف أعفو عن أعمالك؟ تخلى عني أبناؤك وأقسموا بأوثان. وعندما أشبعتهم ارتكبوا الفسق، وهرولوا طوائف إلى مواخير الزانيات.","5:8":"صاروا كحصن معلوفة سائبة يصهل كل واحد منهم على امرأة صاحبه.","5:9":"ألا أعاقبهم على هذه الأمور؟» يقول الرب، ألا أنتقم لنفسي من أمة مثل هذه؟","5:10":"اذهبوا إلى أتلام كرومها ودمروها ولكن لا تفنوها. انزعوا أغصانها لأنها ليست للرب.","5:11":"فذرية إسرائيل وذرية يهوذا قد غدرتا بي»، يقول الرب.","5:12":"قد جحدوا الرب وقالوا: «لن يعاقبنا ولن يصيبنا مكروه، ولن نرى سيفا ولن نتعرض لجوع،","5:13":"والأنبياء كالريح ووحي الرب ليس معهم. فليأت عليهم ما تنبأوا به».","5:14":"لذلك يعلن السيد الرب القدير: «لأنكم قلتم هذا الكلام، فها أنا أجعل كلماتي في فمك نارا، وهذا الشعب حطبا، فتلتهمهم النار.","5:15":"ها أنا أجلب عليكم ياذرية إسرائيل، أمة قديمة قوية من أرض نائية، تجهلون لغة أهلها ولا تفهمون ما يقولون.","5:16":"جعبتها كقبر مفتوح، وكل رجالها جبابرة،","5:17":"فيأكلون حصادكم وطعامكم، ويهلكون أبناءكم وبناتكم، ويلتهمون مواشيكم وقطعانكم، ويأكلون كرومكم وأشجار تينكم، ويدمرون بالسيف مدنكم الحصينة التي عليها تتوكلون.","5:18":"ولكن حتى في تلك الأيام لن أفنيكم»، يقول الرب.","5:19":"وعندما يسألون: لماذا صنع الرب إلهنا بنا هذه الأمور كلها؟ تقول لهم: «كما أنكم تخليتم عني وعبدتم الأوثان الغريبة في أرضكم، كذلك تستعبدون للغرباء في أرض ليست لكم.","5:20":"وأذيعوا أيضا هذا في ذرية يعقوب، وأعلنوه لبني يهوذا قائلين:","5:21":"اسمع هذا أيها الشعب الأحمق الغبي، يامن له عيون ولكنه لا يبصر، وله آذان ولكنه لا يسمع.","5:22":"ألا تخشونني؟» يقول الرب، ألا ترتعدون في حضرتي؟ قد جعلت الرمل حدا لمياه البحر، حاجزا أبديا لا يتخطاه. تتلاطم أمواجه ولكنها تعجز عن تعديه، وتهدر ولكنها لا تتجاوزه.","5:23":"أما هذا الشعب فذو قلب متمرد عاص، ثاروا علي ومضوا،","5:24":"ولم يتناجوا في قلوبهم قائلين: لنتق الرب إلهنا الذي يغدق المطر في مواعيده في موسمي الربيع والخريف، ويحفظ لنا أسابيع الحصاد حسب مواقيتها.","5:25":"غير أن آثامكم قد حولت عنكم هذه البركات، وخطاياكم حرمتكم من الخير.","5:26":"ففي وسط شعبي قوم أشرار يكمنون كما يكمن القناصون للطيور، وينصبون الفخ لاقتناص الناس.","5:27":"بيوتهم تكتظ بالخديعة كقفص مملوء طيورا، لذلك عظموا وأثروا.","5:28":"ازدادوا سمنا ونعومة، وارتكبوا الشر متجاوزين كل حد. لم يحكموا بعدل في دعوى اليتيم حتى تنجح، ولم يدافعوا عن حقوق المساكين.","5:29":"أفلا أعاقبهم على هذه الأمور؟» يقول الرب. ألا أنتقم لنفسي من أمة كهذه؟","5:30":"قد جرى في البلاد حدث مذهل فظيع.","5:31":"فالأنبياء يتنبأون زورا، والكهنة يتصرفون بمقتضى أحكامهم، وشعبي أحب مثل هذا. ولكن ماذا تصنعون في نهاية المطاف؟»","6:1":"«لوذوا بالنجاة ياذرية بنيامين، واهربوا من وسط أورشليم. انفخوا بالبوق في تقوع، وأشعلوا علم نار على بيت هكاريم، لأن الشر قد أقبل من الشمال ليعيث في الأرض خرابا.","6:2":"ها أنا أهلك أورشليم الجميلة المترفة ابنة صهيون،","6:3":"فيحل بها الرعاة مع قطعانهم، ويضربون حولها خيامهم، ويرعى كل منهم حيث نزل.","6:4":"أعدوا عليها حربا. قوموا نهاجمها عند الظهيرة. ويل لنا فقد مال النهار وانتشرت ظلال المساء.","6:5":"هبوا لنهجم في الليل ونهدم قصورها».","6:6":"لأن هذا ما يعلنه الرب القدير: «اقطعوا الشجر، وأقيموا مترسة حول أورشليم، إذ يجب أن تعاقب هذه المدينة، لأن داخلها مفعم بالظلم.","6:7":"وكما تنبع العين مياهها كذلك هي تنبع شرها. يتردد في أرجائها الظلم ويعمها السلب، وأمامي دائما مرض وبلايا.","6:8":"فاحذري ياأورشليم لئلا أجفوك وأجعلك موحشة وأرضا مهجورة».","6:9":"وهذا ما يعلنه الرب القدير: «ليجمعوا بدقة لقاط بقية إسرائيل كما يجمعون لقاط كرمة. رد يدك إلى الأغصان ثانية كلاقط العنب».","6:10":"لمن أتحدث وأنذر حتى يسمعوا؟ انظر! إن آذانهم صماء فلا يسمعون، وكلمة الرب مثار خزي لهم فلا يسرون بها».","6:11":"لذلك امتلأت من سخط الرب وأعياني كظمه. أسكبه على الأولاد في الطريق وعلى الشبان المجتمعين في مجالسهم، فيصيب الرجل وزوجته والشيخ والطاعن في السن.","6:12":"وتتحول بيوتهم وحقولهم لآخرين، وكذلك نساؤهم، لأني أبسط يدي ضد سكان الأرض»، يقول الرب","6:13":"لأنهم جميعا، صغارهم وكبارهم، مولعون بالربح الحرام. حتى النبي والكاهن يرتكبان الزور في أعمالهما.","6:14":"يعالجون جراح شعبي باستخفاف قائلين: سلام، سلام. في حين لا يوجد سلام.","6:15":"هل خجلوا لأنهم اقترفوا الرجس؟ كلا! لم يخزوا قط ولم يعرفوا الخجل، لذلك سيسقطون بين الساقطين، وحين أعاقبهم يطوح بهم».","6:16":"وهذا ما يعلنه الرب: «قفوا في الطرقات وانظروا، واسألوا عن المسالك الصالحة القديمة واطرقوها، فتجدوا راحة لنفوسكم. ولكنكم قلتم: لن نسير فيها.","6:17":"فأقمت عليكم رقباء قائلا: اسمعوا دوي البوق. ولكنكم قلتم: «لن نسمع!»","6:18":"لذلك اسمعوا أيها الأمم، واعلمي أيتها الجماعة ماذا يحل بهم.","6:19":"اسمعي أيتها الأرض وانظري، لأني جالب شرا على هذا الشعب عقابا لهم على أفكارهم الأثيمة، لأنهم لم يطيعوا كلماتي وتنكروا لشريعتي.","6:20":"لأي غرض يصعد إلي البخور من شبا، وقصب الذريرة من أرض نائية؟ محرقاتكم مرفوضة، وتقدماتكم لا تسرني».","6:21":"لذلك يعلن الرب: «ها أنا أقيم لهذا الشعب معاثر يتعثر بها الآباء والأبناء معا، ويهلك بها الجار وصديقه».","6:22":"«انظروا، ها شعب زاحف من الشمال، وأمة عظيمة تهب من أقاصي الأرض،","6:23":"تسلحت بالقوس والرمح، وهي قاسية لا ترحم. جلبتها كهدير البحر وهي مقبلة على صهوات الخيل. قد اصطفت كإنسان واحد لمحاربتك ياأورشليم».","6:24":"سمعنا أخبارهم المرعبة فدب الوهن في أيدينا، وتولانا كرب وألم كألم امرأة تعاني من المخاض.","6:25":"لا تخرجوا إلى الحقل ولا تمشوا في الطريق، فللعدو سيف، والهول محدق من كل جهة.","6:26":"فياأورشليم ارتدي المسوح وتمرغي في الرماد، ونوحي كمن ينوح على وحيده، وانتحبي نحيبا مرا، لأن المدمر ينقض علينا فجأة.","6:27":"«إني أقمتك ممتحنا للمعدن، وجعلت شعبي مادة خام لكي تعرف طرقهم وتفحصها.","6:28":"فكلهم عصاة متمردون ساعون في النميمة. هم نحاس وحديد وكلهم فاسدون.","6:29":"لشد ما تضرم ريح المنفاخ الشديدة النار فتلتهم الرصاص ولكن كما يتعذر تنقيته من الزغل كذلك يتعذر فصل الأشرار.","6:30":"وهم يدعون حثالة الفضة المرذولة، لأن الرب قد رفضهم».","7:1":"هذه هي النبوءة التي أوحى بها الرب لإرميا:","7:2":"«قف في باب هيكل الرب وأعلن هناك هذا الكلام: اسمعوا كلام الرب ياجميع رجال يهوذا المجتازين هذه الأبواب ليسجدوا للرب:","7:3":"هذ ما يعلنه الرب القدير إله إسرائيل: قوموا طرقكم وأعمالكم فأسكنكم في هذا الموضع.","7:4":"لا تتكلوا على أقوال الكذب قائلين: هذا هيكل الرب: هذا هيكل الرب","7:5":"لكن إن قومتم حقا طرقكم وأعمالكم، وأجريتم قضاء عادلا فيما بينكم،","7:6":"إن لم تجوروا على الغريب واليتيم والأرملة، ولم تسفكوا دما بريئا في هذا الموضع، وإن لم تضلوا وراء الأوثان مسيئين بذلك لأنفسكم،","7:7":"عندئذ أسكنكم في هذا الموضع في الأرض التي وهبتها لآبائكم إلى الأبد.","7:8":"ها أنتم قد اتكلتم على أقوال الكذب، ولكن من غير جدوى.","7:9":"أتسرقون وتقتلون وتزنون وتحلفون زورا وتبخرون للبعل، وتضلون وراء الأوثان التي لم تعرفوها،","7:10":"ثم تمثلون في حضرتي في هذا الهيكل الذي دعي باسمي قائلين: «قد نجونا»؛ ثم ترتكبون جميع هذه الرجاسات؟","7:11":"هل أصبح هذا الهيكل الذي دعي باسمي، مغارة لصوص في أعينكم؟ ها أنا قد رأيت كل هذا الشر، يقول الرب.","7:12":"لكن امضوا إلى موضعي في شيلوه، حيث جعلت فيه مقرا لاسمي أولا، وشاهدوا ما فعلت به من جراء شر شعبي إسرائيل.","7:13":"والآن لأنكم ارتكبتم هذه الشرور، يقول الرب، على الرغم من تحذيراتي المبكرة التي أبيتم الاستماع لها، ورفضتم الاستجابة لدعوتي،","7:14":"فإن ما أنزلته بشيلوه سأنزله بالهيكل الذي دعي باسمي والذي عليه تتكلون، وبالموضع الذي وهبته لكم ولآبائكم،","7:15":"وأطرحكم من أمامي كما طرحت جميع أقربائكم، جميع ذرية أفرايم.","7:16":"أما أنت فلا تصل من أجل هذا الشعب ولا ترفع لأجلهم دعاء ولا ابتهالا، ولا تتشفع لهم لأني لن أستجيب لك.","7:17":"ألا تشهد ما يفعلون في مدن يهوذا وفي شوارع أورشليم؟","7:18":"الأبناء يلتقطون الحطب والآباء يشعلون النار، والنساء يعجن الدقيق ليصنعن أقراصا منها لعشتاروث إلهة السماء، ويسكبوا سكائب لآلهة الأوثان ليغيظوني.","7:19":"هل أنا حقا الذي يغيظونه؟ يقول الرب. ألا يسيئون بذلك إلى ذواتهم عاملين على خزي أنفسهم؟","7:20":"لذلك يعلن السيد الرب: ها غضبي وسخطي ينصبان على هذا الموضع، وعلى البشر والبهائم والأشجار والحقول وأثمار الأرض، فيتقدان ولا يخمدان».","7:21":"وهذا ما يعلنه الرب القدير إله إسرائيل: «أضيفوا محرقاتكم إلى ذبائحكم وكلوا لحمها.","7:22":"فإني لم أكلم آباءكم ولم آمرهم يوم أخرجتهم من مصر بشأن محرقة أو ذبيحة","7:23":"إنما أوصيتهم أن يطيعوا صوتي فأكون لهم إلها، ويكونون لي شعبا وأن يسلكوا في كل الطريق الذي أوصيتهم به، فينالوا خيرا.","7:24":"إلا أنهم لم يطيعوا ولم يسمعوا، بل سلكوا بمقتضى مشورات قلوبهم الشريرة وعنادهم، وأداروا لي ظهورهم بدل وجوههم.","7:25":"فمنذ أن خرج آباؤكم من مصر إلى هذا اليوم، ثابرت على إرسال جميع عبيدي الأنبياء لينذروهم كل يوم.","7:26":"ومع ذلك لم يطيعوني أو يسمعوني، ولكنهم قسوا قلوبهم، فكانوا في تصرفهم أشر من آبائهم.","7:27":"ولكن عندما تكلمهم بهذه العبارات فإنهم لن يسمعوا، وتدعوهم فلا يجيبونك.","7:28":"فتقول لهم: هذه هي الأمة التي تعصى صوت الرب إلهها، ولا تقبل التأديب. لقد تلاشى الحق وانقطع عن أفواههم.","7:29":"جزي شعرك واطرحيه ياأورشليم، وانصبي مرثاة على المرتفعات الجرداء، لأن الرب رفض هذا الجيل الرازح تحت سخطه».","7:30":"«لأن ذرية يهوذا قد ارتكبت الشر في عيني، وأقامت أوثانها الرجسة في البيت الذي دعي باسمي، لتدنسه.","7:31":"وشيد الشعب معابد مرتفعات توفة القائمة في وادي ابن هنوم، ليحرقوا أبناءهم وبناتهم بالنار، مما لم آمر به ولم يخطر لي على بال.","7:32":"لذلك ها أيام مقبلة، يقول الرب، يمحى فيها اسم توفة، ويتلاشى اسم وادي ابن هنوم، ويدعى «وادي القتل» لأنهم سيدفنون الموتى في توفة حتى لا يبقى فيها متسع بعد،","7:33":"وتصبح جثث هذا الشعب طعاما لجوارح السماء ولوحوش الأرض وليس من يزجرها.","7:34":"وألاشي من مدن يهوذا ومن شوارع أورشليم أهازيج الطرب وأصداء الفرح، وأصوات بهجة العريس والعروس، لأن الأرض يعمها الخراب».","8:1":"ويقول الرب: «في ذلك الحين ينبشون من القبور عظام ملوك يهوذا وعظام رؤسائهم وكهنتهم وأنبيائهم، وعظام سكان أورشليم.","8:2":"ويعرضونها أمام الشمس والقمر وكواكب السماء التي أحبوها وعبدوها وضلوا وراءها، واستشاروها وسجدوا لها، فلا تجمع ولا تدفن، بل تصير نفاية فوق وجه الأرض،","8:3":"وجميع البقية الباقية من هذه العشيرة الشريرة المشتتة في جميع البقاع التي نفيتهم إليها، يؤثرون الموت على الحياة».","8:4":"وتقول لهم: «هذا ما يعلنه الرب: عندما يسقط الرجال، ألا يقومون ثانية؟ وعندما يرتدون مخطئين ألا يرجعون؟","8:5":"فما بال شعب أورشليم قد ارتدوا ارتدادا دائما متشبثين بالخديعة ورافضين الرجوع؟","8:6":"قد أصغيت وسمعت، وإذا بهم ينطقون بما ينافي الحق، وما من أحد يتوب عن شره قائلا: ما هذا الذي أرتكب؟ بل كل واحد مضى في طريقه كفرس مندفع لخوض معركة.","8:7":"إن اللقلق في السماء يعرف ميعاد هجرته، وكذلك اليمامة والسنونة المغردة تحفظان أوان عودتهما من هجرتهما. أما شعبي فلا يعرف قضاء الرب!","8:8":"كيف تدعون أنكم حكماء ولديكم شريعة الرب بينما حولها قلم الكتبة المخادع إلى أكذوبة؟","8:9":"سيلحق الخزي بالحكماء ويعتريهم الفزع والذهول، لأنهم رفضوا كلمة الرب. إذا أية حكمة فيهم؟","8:10":"لذلك أعطي نساءهم لآخرين وحقولهم للوارثين القاهرين، لأنهم جميعا من صغيرهم إلى كبيرهم مولعون بالربح. حتى النبي والكاهن يرتكبان الزور في أعمالهما،","8:11":"ويعالجون جراح شعبي باستخفاف قائلين: سلام، سلام في حين لا يوجد سلام.","8:12":"هل خجلوا عندما اقترفوا الرجس؟ كلا! لم يخزوا قط ولم يعرفوا الخجل. لذلك سيسقطون بين الساقطين، وحين أعاقبهم يطوح بهم»، يقول الرب.","8:13":"«وسأبيدهم حقا، إذ لا يكون في الكرمة عنب ولا في التينة تين. حتى أوراق الأشجار تذوي وتتساقط، وما أغدقته عليهم من نعم يسلب منهم.","8:14":"فما لنا قابعون هنا؟ اجتمعوا معا ولنلجأ إلى المدن الحصينة ونهلك هناك، لأن الرب إلهنا قد قضى علينا بالهلاك، وأعطانا ماء مسموما لنشربه، لأننا أخطأنا في حقه.","8:15":"طلبنا السلام فلم يسفر عن خير. نشدنا وقتا للمداواة فابتلينا بالأهوال.","8:16":"قد ترددت حمحمة خيلهم من أرض دان، وارتعدت الأرض من صهيل جيادهم. قد أقبلوا واكتسحوا الأرض وكل ما فيها، والمدينة وأهلها.","8:17":"انظروا، ها أنا أرسل عليكم أفاعي مميتة لا تنجع معها رقى فتلدغكم»، يقول الرب.","8:18":"قد غلب علي الحزن وقلبي في سقيم.","8:19":"هوذا صرخة استغاثة أورشليم تتجاوب من أرض نائية قائلة: «أليس الرب في صهيون؟ أليس ملكها فيها؟ لماذا أثاروا غيظي بمنحوتاتهم وأوثانهم الغريبة الباطلة؟","8:20":"قد انقضى موسم الحصاد، وانتهى الصيف، ونحن لم نخلص».","8:21":"لأن سحق أورشليم هو سحقي، لذلك أنوح وقد اشتد بي الرعب.","8:22":"ألا يوجد بلسان في جلعاد؟ أليس هناك طبيب؟ فلماذا إذن لم تشف جروح شعبي.","9:1":"ياليت رأسي فيض مياه، وعيني ينبوع دموع، فأبكي نهارا وليلا قتلى بنت شعبي","9:2":"ياليت لي في الصحراء مبيت عابر سبيل، فأهجر شعبي وأنطلق بعيدا عنهم، لأنهم جميعا زناة وجماعة خونة.","9:3":"«قد وتروا ألسنتهم كقسي جاهزة ليطلقوا الأكاذيب التي تقولوا بها في الأرض من دون الحق، إذ أنهم انتهوا من شر إلى شر، وإياي لم يعرفوا» يقول الرب.","9:4":"«ليحترس كل واحد من جاره، ولا يثق بأحد من أقربائه، لأن كل قريب مخادع، وكل صاحب واش.","9:5":"كل واحد منهم يخدع جاره ولا ينطقون بالصدق. دربوا ألسنتهم على قول الكذب، وأرهقوا أنفسهم في ارتكاب الإثم.","9:6":"يجمعون ظلما فوق ظلم، وخداعا على خداع، وأبوا أن يعرفوني».","9:7":"لذلك يعلن الرب القدير: «ها أنا أمحصهم وأمتحنهم، إذ أي شيء آخر يمكن أن أفعله عقابا لخطايا أورشليم؟","9:8":"لسانهم كسهم قاتل يتفوه بالكذب. وبفمه يخاطب جاره بحديث السلام، أما في قلبه فينصب له كمينا.","9:9":"ألا أعاقبهم على هذه الأمور؟» يقول الرب. «ألا أنتقم لنفسي من أمة كهذه؟»","9:10":"سأنتحب وأنوح على الجبال وأندب على مراعي البرية لأنها احترقت وأوحشت، فلا يجتاز بها عابر ولا يتردد فيها صوت القطعان، وقد هجرتها طيور السماء والوحوش.","9:11":"«سأجعل أورشليم رجمة خراب، ومأوى لبنات آوى، وأحول مدن يهوذا إلى قفر مهجور».","9:12":"من هو الإنسان الحكيم حتى يفهم هذا؟ ومن خاطبه فم الرب حتى يعلنها؟ لماذا خربت الأرض، وأوحشت كالبرية فلا يقطعها عابر؟","9:13":"ويقول الرب: «لأنهم نبذوا شريعتي التي وضعتها أمامهم، ولم يطيعوا صوتي أو يسلكوا بمقتضاها،","9:14":"بل ضلوا وراء عناد قلوبهم، وانساقوا خلف آلهة البعليم التي لقنهم آباؤهم عبادتها.","9:15":"لذلك ها أنا أطعم هذا الشعب أفسنتينا، وأسقيهم ماء مسموما،","9:16":"وأشتتهم بين الأمم التي لم يعرفوها هم ولا آباؤهم، وأجعل سيف الدمار يتعقبهم حتى أفنيهم».","9:17":"وهذا ما يعلنه الرب القدير: «تأملوا واستدعوا النادبات ليأتين، وأرسلوا إلى الحكيمات فيقبلن.","9:18":"ليسرعن حتى يطلقن أصواتهن علينا بالندب فتذرف عيوننا دموعا، وتفيض أجفاننا ماء.","9:19":"ها صوت رثاء قد تجاوب في صهيون: ما أشد دمارنا، وما أعظم عارنا، لأننا قد فارقنا أرضنا، ولأنهم قد هدموا مساكننا!»","9:20":"فاسمعن أيتها النساء قضاء الرب، ولتفهم آذانكن كلمة فمه: لقن بناتكن الر ثاء، ولتعلم كل منهن صاحبتها الندب،","9:21":"فإن الموت قد تسلق إلى كوانا وتسلل إلى قصورنا، فاستأصل الأطفال من الشوارع والشبان من الساحات.","9:22":"وهذا ما يعلنه الرب: «ستتهاوى جثث الناس مثل نفاية على وجه الحقل، وتتساقط كقبضات وراء الحاصد، وليس من يجمعها».","9:23":"«فلا يفتخرن الحكيم بحكمته، ولا يزهون الجبار بجبروته، ولا الغني بثروته.","9:24":"بل ليفتخر المفتخر بأنه يدرك ويعرفني أني أنا الرب الذي يمارس الرحمة والعدل والبر في الأرض لأني أسر بها».","9:25":"«ها أيام مقبلة»، يقول الرب، «أعاقب فيها كل مختون وأغلف","9:26":"أهل مصر ويهوذا وأدوم وبني عمون وموآب، وسائر المقيمين في الصحراء ممن يقصون شعر أصداغهم، لأن جميع الشعوب غلف، أما كل بيت إسرائيل فإنهم ذوو قلوب غلفاء».","10:1":"أنصتوا إلى القضاء الذي تكلم به الرب عليكم ياذرية إسرائيل.","10:2":"هكذا قال الرب: «لا تتعلموا طريق الأمم، ولا ترتعبوا من آيات السماء التي ترتعب منها الشعوب.","10:3":"لأن عادات الأمم باطلة، إذ تقطع الشجرة من الغابة ثم تشذبها وتنحتها يدا صانع بفأس.","10:4":"ثم يزينونها بالفضة والذهب وتثبت بالمسامير والمطارق لئلا تتحرك.","10:5":"فتكون كفزاعة في حقل قثاء لا تنطق، بل تحمل لأنها عاجزة عن المشي. فلا تخافوها لأنها لا تضر ولا تنفع».","10:6":"أنت لا نظير لك يارب. عظيم أنت، واسمك عظيم في الجبروت.","10:7":"من لا يتقيك ياملك الأمم؟ فالخوف منك يليق بك، إذ لا يوجد بين حكماء الشعوب وفي جميع ممالكهم من هو نظيرك.","10:8":"جميعهم بلداء وحمقى، يتلقفون العلم من أصنام خشبية.","10:9":"يحضرون لصنعها الفضة المطرقة من ترشيش، والذهب من أوفاز، فهي عمل صانع ماهر وصوغ يدي صائغ، وتكسى بثياب زرقاء وأرجوانية. كلها صنعة صناع مهرة.","10:10":"أما الرب فهو الإله الحق، الإله الحي والملك السرمدي. ترتعد الأرض أمام غضبه ولا تتحمل الأمم فرط سخطه.","10:11":"«وهذا ما تقولونه لهم: إن الآلهة التي لم تصنع السماوات والأرض يجب أن تستأصل من الأرض ومن تحت السماء».","10:12":"فالرب هو الذي صنع السماوات والأرض بقدرته، وأسس الدنيا بحكمته ومد السماوات بفطنته.","10:13":"ما إن ينطق بصوته حتى تتجمع غمار المياه في السماوات، وتصعد السحب من أقاصي الأرض. يجعل للمطر بروقا، ويطلق الريح من خزائنه.","10:14":"كل امريء خامل وعديم المعرفة، وكل صائغ أخزاه تمثاله لأن صنمه المسبوك كاذب ولا حياة فيه.","10:15":"جميع الأصنام باطلة، صنعة ضلال، وفي زمن عقابها تبيد.","10:16":"أما (الله ) نصيب يعقوب فليس مثل هذه الأوثان، بل هو جابل كل الأشياء، وشعب إسرائيل هو شعب ميراثه، واسمه الرب القدير.","10:17":"اجمعي من الأرض حزمك أيتها المقيمة تحت الحصار.","10:18":"لأن هذا ما يعلنه الرب: «ها أنا أقذف بمقلاع سكان الأرض في هذه المرة، وأعرضهم للضيق حتى يعرفوا معاناته».","10:19":"ويل لي من أجل انسحاقي، فجرحي لا شفاء منه، ولكني قلت: «حقا هذه بلية وعلي أن أتحملها».","10:20":"قد تهدم خبائي وتقطعت أطنابي، وهجرني أبنائي ولم يعد لهم وجود. ليس من يقيم خبائي ثانية ويبسط سجوفي.","10:21":"فرعاة شعبي بلداء لم يلتمسوا الرب، لذلك لم يفلحوا وتشتتت جميع رعيتهم.","10:22":"اسمعوا، ها أخبار تتواتر عن جيش عظيم مقبل من الشمال ليحول مدن يهوذا إلى خرائب ومأوى لبنات آوى.","10:23":"أدركت يارب أن الإنسان لا يملك زمام طريقه، وليس في وسع الإنسان أن يوجه خطى نفسه.","10:24":"قومني يارب بحقك لا بغضبك، لئلا تلاشيني.","10:25":"لينصب سخطك على الأمم التي لم تعرفك، وعلى الشعوب التي لا تدعو باسمك، لأنهم قد افترسوا ذرية يعقوب والتهموها وخربوا مسكنها.","11:1":"هذه هي النبوءة التي أوحى بها الرب لإرميا:","11:2":"«استمع كلام هذا العهد وخاطب رجال يهوذا وأهل أورشليم،","11:3":"وقل لهم: هذا ما يعلنه الرب إله إسرائيل: ملعون الذي لا يسمع كلمات هذا العهد،","11:4":"الذي أوصيت به آباءكم حين أخرجتهم من مصر من كور الحديد قائلا: استمعوا إلى صوتي واعملوا بمقتضى ما أمرتكم به، فتكونوا لي شعبا وأنا أكون لكم إلها،","11:5":"فأفي بالقسم الذي أقسمت به لآبائكم أن أهبهم أرضا تفيض لبنا وعسلا، كما في هذا اليوم». فأجبت قائلا: «آمين يارب».","11:6":"ثم قال لي الرب: «أذع كل هذا الكلام في مدن يهوذا وفي شوارع أورشليم: اسمعوا كلمات هذا العهد واعملوا بها.","11:7":"فإني منذ أن أخرجت آباءكم من مصر حتى هذا اليوم، أشهدت عليهم المرة تلو الأخرى قائلا: أطيعوا صوتي.","11:8":"لكنهم لم يطيعوا ولم يسمعوا، إنما سلك كل واحد بموجب عناد قلبه الشرير. فأجريت عليهم كل كلام هذا العهد الذي أمرتهم به ولم ينفذوه».","11:9":"ثم خاطبني الرب: «قد شاعت فتنة بين رجال يهوذا وأهل أورشليم.","11:10":"فقد ارتدوا إلى آثام أسلافهم الذين أبوا الاستماع إلى كلماتي، ضلوا وراء الأصنام ليعبدوها، وقد نكث شعب إسرائيل وشعب يهوذا عهدي الذي أبرمته مع آبائهم.","11:11":"لذلك ها أنا أنزل بهم شرا لن يفلتوا منه، فيستغيثون بي فَلا أستجيب لهم.","11:12":"فيلجأ سكان مدن يهوذا وأهل أورشليم إلى الأصنام التي أحرقوا لها البخور ليستغيثوا بها، ولكنها لن تغيثهم في ساعة المحنة.","11:13":"صار عدد آلهتك يايهوذا كعدد مدنك، وأضحت مذابحك التي نصبتها للخزي ولإصعاد البخور لبعل بعدد شوارع أورشليم.","11:14":"فلا تبتهلن من أجل هذا الشعب، ولا ترفعن لأجلهم دعاء ولا صلاة، فإني لن أسمع لهم وقت استغاثتهم بي من محنتهم.","11:15":"أي حق لحبيبتي في بيتي بعد أن ارتكبت الموبقات الكثيرة؟ أيمكن للحم الذبائح المقدس أن يصرف عنك عقابك؟ عندما تنغمسين في شرك آنئذ تبتهجين».","11:16":"قد دعاك الرب مرة زيتونة خضراء ذات ثمر بهيج المنظر. أما الآن فبزمجرة عاصفة رهيبة يضرم فيها نارا تلتهم أغصانها.","11:17":"إن الرب القدير الذي غرسك قد قضى بالشر عليك عقابا لما ارتكبه شعب إسرائيل وشعب يهوذا من إثم، فأثاروا غيظي بإحراق البخور للبعل.","11:18":"وقد أطلعني الرب على ذلك فعرفت؛ ثم أريتني أعمالهم المنكرة.","11:19":"ولكني كنت كحمل أليف يساق إلى الذبح، لم أدرك أنهم يتآمرون علي قائلين: «لنتلف الشجرة وثمارها، ولنستأصله من أرض الأحياء فيندثر اسمه إلى الأبد.","11:20":"ولكن أيها الرب القدير، القاضي بالإنصاف، الفاحص القلوب والنوايا، دعني أشهد انتقامك منهم لأني إليك رفعت دعواي.","11:21":"«لذلك، هكذا يقول الرب عن رجال عناثوث الذين يلتمسون نفسك قائلين: لا تتنبأ باسم الرب لئلا تموت بأيدينا.","11:22":"لهذا يعلن الرب القدير: ها أنا أعاقبهم فيموت شبابهم بحد السيف، ويهلك أبناؤهم وبناتهم جوعا.","11:23":"ولا تفلت منهم بقية، لأني في سنة عقابهم أجلب شرا على رجال عناثوث».","12:1":"أنت دائما عادل حين أعرض عليك دعواي، ولكن دعني أحدثك بشأن أحكامك: لماذا تفلح طريق الأشرار؟ ولماذا يتمتع الغادرون بالعيش الرغيد؟","12:2":"أنت غرستهم فتأصلوا ونموا وأثمروا. اسمك يتردد على أفواههم، ولكنه بعيد عن قلوبهم.","12:3":"أنت قد عرفتني ورأيتني وامتحنت قلبي من نحوك. افرزهم كغنم للذبح واعزلهم ليوم النحر.","12:4":"إلى متى تظل الأرض نائحة وعشب كل حقل ذاويا؟ هلكت البهائم والطيور من شر الساكنين فيها القائلين: «إنه لن يرى خاتمة مصيرنا».","12:5":"«إن كنت قد باريت المشاة فأعيوك، فكيف إذا تباري الخيل؟ وإن كنت تتعثر في أرض مطمئنة، فكيف تفعل في أجمات نهر الأردن؟","12:6":"حتى إخوتك وأفراد أسرتك قد تنكروا لك، ودعوا عليك وراءك بملء أفواههم. لا تأتمنهم، وإن خاطبوك بألفاظ معسولة.","12:7":"قد نبذت هيكلي وهجرت ميراثي، وسلمت حبيبة نفسي إلى أيدي أعدائها.","12:8":"قد زمجر علي شعبي كأسد في غابة. رفع علي صوته، لهذا مقته.","12:9":"هل صار شعبي لي كطير جارح منقض؟ وهل تألبت عليه الجوارح من كل جهة؟ هلم احشد جميع وحوش البر، وادعها للأكل.","12:10":"قد أتلف رعاة كثيرون كرمي، وداسوا نصيبي الشهي وجعلوه برية جرداء.","12:11":"جعلوه خرابا، وفي خرابه ينوح علي. أصبحت الأرض كلها قفرا، لأنه لا يوجد إنسان واحد يحفل بها.","12:12":"قد أقبل المدمرون وانتشروا على جميع المرتفعات في البرية، لأن سيف الرب يلتهم من أقصى الأرض إلى أقصاها، فلا ينعم أحد من البشر بالسلام.","12:13":"زرع شعبي حنطة وحصد شوكا. أعيوا أنفسهم ولكن من غير جدوى، لذلك يعتريهم الخزي من قلة غلات محصولهم لفرط احتدام غضب الرب».","12:14":"وهذا ما يعلنه الرب عن جميع جيراني الأشرار الذين يمسون الميراث الذي ورثته لشعبي إسرائيل: «ها أنا أقتلعهم من أرضهم كما أقتلع أيضا شعب يهوذا من وسطهم.","12:15":"ولكن بعد أن أستأصلهم، أترَأف عليهم، وأعيدهم كل واحد إلى ميراثه وإلى أرضه.","12:16":"فإن تلقنت الأمم طرق شعبي باسمي، قائلين: «حي هو الرب»، كما علموا شعبي أن يحلفوا بالبعل، فإنهم ينمون وسط شعبي.","12:17":"ولكن إن رفضت أية أمة الاستماع، فإني أستأصلها وأقتلعها وأدمرها»، يقول الرب.","13:1":"ثم قال الرب لي: «امض واشتر لنفسك منطقة من كتان ولفها حول حقويك، ولا تضعها في الماء».","13:2":"فاشتريت منطقة كأمر الرب ولففتها حول حقوي،","13:3":"ثم كلمني الرب ثانية","13:4":"«خذ المنطقة التي اشتريتها، الملفوفة حول حقويك، واذهب إلى نهر الفرات، واطمرها في شق صخر».","13:5":"فانطلقت وطمرتها عند الفرات كأمر الرب.","13:6":"وبعد عدة أيام قال لي الرب: «اذهب إلى الفرات وخذ المنطقة التي أمرتك أن تطمرها هناك».","13:7":"فقصدت إلى الفرات وحفرت الموضع وأخذت المنطقة من حيث طمرتها، وإذا بها قد تلفت ولم تعد تصلح لشيء.","13:8":"فأوحى إلي الرب بكلمته.","13:9":"«هكذا سأحطم كبرياء يهوذا وكبرياء أورشليم العظيمة.","13:10":"إن هذا الشعب الشرير الذي أبى أن يستمع إلى كلمتي، وانساق بعناد خلف أهواء قلبه، وضل وراء الأصنام ليسجد لها ويعبدها، سيصبح مثل هذه المنطقة.","13:11":"وكما أن المنطقة تلتف حول حقوي الإنسان، هكذا جعلت كل ذرية يهوذا تلتف حولي، ليكونوا لي شعبا ومثار شهرة وفخر ومجد. ولكنهم لم يسمعوا».","13:12":"لذلك قل لهم: «هذا ما يعلنه الرب إله إسرائيل: كل زق يمتليء خمرا، فيجيبونك: ألسنا نعرف أن كل زق يمتليء خمرا؟»","13:13":"فتقول لهم، «هذا ما يعلنه الرب: ها أنا أملأ بالسكر جميع سكان هذه الأرض والملوك من ذرية داود الجالسين على عرشه، والكهنة، والأنبياء وكل أهل أورشليم.","13:14":"وأهشمهم الواحد فوق الآخر، الآباء والأبناء معا، يقول الرب. لا أشفق ولا أترَأف ولا أرحم، بل أهلكهم».","13:15":"فاسمعوا واصغوا ولا تستكبروا، لأن الرب قد تكلم.","13:16":"مجدوا الرب إلهكم قبل أن يجعل الظلام يخيم عليكم، وقبل أن تتعثر أقدامكم على الجبال المعتمة. أنتم ترتقبون النور ولكنه يحوله إلى ظلام الموت ويجعله ليلا دامسا.","13:17":"وإن لم تنصتوا فإن نفسي تبكي في الخفاء من أجل كبريائكم، وتذرف عيناي الدموع المريرة، فتسيل العبرات لأن الرب قد سبى شعبه.","13:18":"قل للملك وللملكة: «تواضعا، وتنازلا عن موضعكما لأن تاج مجدكما قد سقط عن رأسيكما».","13:19":"قد أغلقت مدن النقب وليس من يفتحها. سبي أهل يهوذا بجملتهم. سبوا جميعا ولم يبق منهم أحد.","13:20":"ارفعوا عيونكم وشاهدوا المقبلين من الشمال. أين القطيع الذي عهد به إليك ياأورشليم؟ أين قطيع افتخارك؟","13:21":"ماذا تقولين حين يقيم الرب عليك رؤساء أولئك الذين علمتهم أن يكونوا لك أحلافا؟ أفلا تنتابك الأوجاع كامرأة ماخض؟","13:22":"وإن تساءلت في نفسك: «لماذا ابتليت بهذه الأمور؟» إنها عاقبة كثرة آثامك. قد هتكت أذيالك، واغتصب جسدك.","13:23":"هل يمكن للإثيوبي أن يغير جلده، أو للنمر رقطه؟ كذلك أنتم لا تقدرون أن تصنعوا خيرا بعد أن ألفتم ارتكاب الشر.","13:24":"«سأبددكم كالعصافة التي تذريها ريح البرية.","13:25":"هذه قرعتك، النصيب الذي كلته لك»، يقول الرب، «لأنك نسيتني واتكلت على الكذب.","13:26":"فأنا أيضا أرفع أذيالك على وجهك لينكشف عارك.","13:27":"قد شهدت على التلال في الحقول فسقك وحمحمة فجورك وعهر زناك. ويل لك ياأورشليم. إلى متى تظلين غير طاهرة؟»","14:1":"هذه كلمة الرب التي أوحى بها إلى إرميا بشأن القحط:","14:2":"«أرض يهوذا تنوح وأبوابها واهية. أهلها يندبون مطروحين إلى الأرض، وعويل أورشليم قد صعد إلى العلى.","14:3":"أرسل أشرافهم خدامهم ليحملوا إليهم الماء، فأقبلوا إلى الجباب وإذا بها فارغة من الماء، فرجعوا بجرار خاوية وقد اعتراهم الخزي والخجل وغطوا رؤوسهم.","14:4":"خزي الفلاحون وغطوا رؤوسهم لأن الأرض قد تشققت لانقطاع المطر عنها.","14:5":"حتى الإيل في الصحراء قد هجرت وليدها لتعذر وجود الكَلإ.","14:6":"وقفت الفراء على الروابي وتنسمت الريح كبنات آوى فكلت عيونها لعدم وجود العشب».","14:7":"وإن تكن آثامنا تشهد علينا يارب، فلأجل اسمك خلصنا، لأن معاصينا كثرت وقد أخطأنا إليك.","14:8":"يارجاء إسرائيل ومخلصه في وقت الضيق، لماذا تكون كغريب في الأرض، وكعابر سبيل يميل ليبيت ثم يمضي؟","14:9":"لماذا تكون كالرجل المتحير وكجبار يعجز عن الخلاص؟ وأنت يارب قائم في وسطنا، وباسمك دعينا، فلا تتركنا.","14:10":"وهذا ما يعلنه الرب لهذا الشعب: «لشد ما أحبوا التجول ولم يمتنعوا عن الشر، لذلك لا يقبلهم الله . والآن يذكر إثمهم ويعاقب خطاياهم».","14:11":"وقال لي الرب: «لا تصل لخير الشعب.","14:12":"وإن صاموا فلن أستجيب إلى صراخهم، وإن قربوا محرقات وتقدمات دقيق فلن أتقبلها، ولكني أفنيهم بالسيف والمجاعة والوباء».","14:13":"ثم قلت: «آه أيها السيد الرب، ها الأنبياء الكذبة يقولون لهم: لن تتعرضوا للسيف ولا للجوع، بل أنعم عليكم بسلام محقق في هذا الموضع».","14:14":"وقال لي الرب: «إن الأنبياء يتنبأون زورا باسمي وأنا لم أرسلهم ولم آمرهم، ولم أكلمهم، إنما هم يتنبأون لكم برؤيا كاذبة وعرافة باطلة مستوحاة من ضلال قلوبهم.","14:15":"لذلك هكذا يقول الرب عن هؤلاء الأنبياء المتنبئين باسمي: مع أني لم أرسلهم فإنهم يقولون: لن تبتلى هذه الأرض بسيف ولا مجاعة، لهذا فإن هولاء الأنبياء يفنون بالسيف والمجاعة.","14:16":"ويغدو الشعب الذي يتنبأون له، مطروحا صريعا في شوارع أورشليم فريسة الجوع والسيف، وليس من يدفنهم هم ونساءهم وأبناءهم وبناتهم، وأصب شرهم عليهم».","14:17":"وقل لهم هذا الكلام: «لتذرف عيناي دموعا ليلا ونهارا، ولا تكفا أبدا لأن أورشليم سحقت سحقا عظيما بضربة أليمة جدا.","14:18":"إن خرجت إلى الحقول أشهد قتلى السيف، وإن دخلت المدينة أرى ضحايا المجاعة. وها النبي والكاهن كلاهما يذهبان إلى أرض لا يعرفانها».","14:19":"هل تنكرت ليهوذا كل التنكر؟ وهل كرهت نفسك صهيون؟ ما بالك قد ابتليتنا بضربة لا شفاء منها؟ وقد طلبنا السلام فلم نحظ بالخير. رجونا وقت الشفاء وإذا بنا نلقى الرعب.","14:20":"نحن نقر بشرنا يارب وبآثام آبائنا، لأننا قد أخطأنا إليك.","14:21":"لا ترفضنا من أجل اسمك ولا تهن عرشك المجيد. اذكر عهدك معنا ولا تنقضه.","14:22":"هل بين أصنام الأمم الباطلة من يمطر؟ أو هل تسكب السموات بنفسها وابل الغيث؟ ألست أنت الرب إلهنا؟ إننا إياك نرجو لأنك أنت صنعت هذه جميعها.","15:1":"ثم قال لي الرب: «وحتى لو مثل موسى وصموئيل أمامي، من أجل الشعب فإن قلبي لن يلتفت إلى هذا الشعب. اطرحهم من محضري فيخرجوا.","15:2":"وعندما يسألونك: إلى أين نذهب؟ أجبهم: هذا ما يعلنه الرب: من هو للوبأ فبالوبأ يموت، ومن هو للسيف فبالسيف يقتل، ومن هو للمجاعة فبالمجاعة يفنى، ومن هو للسبي فإلى السبي يذهب.","15:3":"وأعهد بهم إلى أربعة أصناف من الخراب يقول الرب: السيف للذبح، والكلاب للتمزيق، وطيور السماء ووحوش الأرض للافتراس والإهلاك.","15:4":"وأجعلهم مثار رعب أمم الأرض نتيجة لما ارتكبه منسى بن حزقيا في أورشليم.","15:5":"فمن يعطف عليك ياأورشليم، ومن يرثي لك؟ من يتوقف ليسأل عن سلامتك؟","15:6":"قد رفضتني» يقول الرب، «وواظبت على الارتداد، لذلك مددت يدي ضدك ودمرتك، إذ سئمت من كثرة الصفح عنك.","15:7":"وأذريهم بالمذراة في أبواب مدن الأرض؛ وأثكل وأهلك شعبي لأنهم لم يرجعوا عن طرقهم الأثيمة.","15:8":"وأجعل عدد أراملهم أكثر من عدد رمل البحر، وأجلب في رابعة النهار مهلكا على أمهات الشبان، وأوقع عليهم الرعب والهول بغتة.","15:9":"ذبلت والدة السبعة الأبناء. أسلمت روحها وغربت شمس حياتها والنهار لم يغب بعد. لحق بها الخزي والعار. أما بقيتهم فأدفعهم إلى حد السيف أمام أعدائهم»، يقول الرب.","15:10":"ويل لي ياأمي لأنك أنجبتني لأكون إنسان خصام ورجل نزاع لكل الأرض. لم أقرض ولم أقترض. ومع ذلك كل واحد يلعنني.","15:11":"دعهم يشتموا يارب. ألم أتضرع إليك من أجل خيرهم؟ إني أبتهل إليك الآن من أجل أعدائي في وقت الضيق والمحنة.","15:12":"«أيمكن للمرء أن يكسر حديدا ونحاسا من الشمال؟","15:13":"سأجعل ثروتك وكنوزك نهبا بلا ثمن بسبب كل خطاياك في جميع أرضك.","15:14":"وأصيرك عبدا لأعدائك في أرض لا تعرفها، لأن نارا قد اضطرمت في احتدام غضبي، سوف تحرقكم».","15:15":"يارب، أنت عرفت. اذكرني وارعني وانتقم لي من مضطهدي. لا تتمهل طويلا في الانتقام لي، فأنت تعلم أني من أجلك احتملت التعيير.","15:16":"حالما بلغتني كلماتك أكلتها فأصبحت لي بهجة ومسرة لقلبي، لأني دعيت باسمك أيها الرب الإله القدير.","15:17":"لم أجلس في مجالس العابثين، ولم أشترك في لهوهم. اعتزلت وحدي لأن يدك كانت علي، وقد ملأتني سخطا.","15:18":"لماذا لا ينقطع ألمي، وجرحي لا يشفى، ويأبى الالتئام؟ أتكون لي كجدول كاذب أو مياه سريعة النضوب؟","15:19":"لذلك، هكذا قال الرب: «إن رجعت أستردك فتمثل أمامي. إن نطقت بالقول السديد ونبذت الكلام الغث، أجعلك المتحدث بفمي، فيقبلون إليك مسترشدين، وأنت لا تلجأ إليهم طالبا نصيحة.","15:20":"وأجعلك سورا نحاسيا منيعا لهذا الشعب، فيحاربونك ولكنهم يخفقون، لأني أنا معك لأنقذك وأخلصك.","15:21":"أنقذك من قبضة الأشرار، وأفديك من أكف العتاة».","16:1":"وأوحى الرب إلي بهذا الكلام:","16:2":"«لا تتزوج في هذا الموضع ولا تنجب فيه أبناء ولا بنات».","16:3":"لأن هذا ما يقوله الرب عن الأبناء والبنات المولودين في هذا الموضع، وعن الأمهات والآباء الذين أنجبوهم في هذه البلاد:","16:4":"«سيموتون بالأمراض، فلا يندبون، ولا يدفنون بل يصبحون نفاية مطروحة على وجه الأرض، ويفنون بالسيف والجوع، وتكون جثثهم طعاما لجوارح السماء ولوحوش الأرض.","16:5":"لا تدخل إلى بيت فيه مأتم، ولا تذهب لتندب أحدا أو للتعزية، لأني قد نزعت سلامي وإحساني ومراحمي من هذا الشعب،","16:6":"فيموت الصغير والكبير في هذه الأرض فلا يدفنون ولا يندبون أو يخدش أحد نفسه أو يحلق شعره حدادا عليهم.","16:7":"ولا يقدم أحد طعاما في مأتم عزاء لهم عن الميت، ولا يسقونهم كأس المواساة عن فقد أب أو أم.","16:8":"ولا تذهب إلى بيت فيه مأدبة لتجلس معهم وتأكل وتشرب،","16:9":"لأني أقطع من هذا الموضع، أمام أعينكم وفي أيامكم، صوت أهازيج البهجة والطرب، وأغاني الاحتفال بالعروس والعريس.","16:10":"وعندما تبلغ هذا الشعب هذا الكلام، ويسألونك: لماذا قضى الرب علينا بكل هذا الشر العظيم؟ ما هي آثامنا؟ وأية خطيئة ارتكبناها في حق الرب إلهنا؟","16:11":"عندئذ تجيبهم: يقول الرب: لأن أباءكم نبذوني وضلوا وراء الأوثان وعبدوها وسجدوا لها، وتركوني ولم يطبقوا شريعتي.","16:12":"ولأنكم أنتم أيضا قد أسأتم أكثر من آبائكم، وغوى كل واحد منكم وراء قلبه الشرير العنيد ورفض طاعتي.","16:13":"لذلك ها أنا أقذفكم خارج هذه الأرض إلى أرض لم تعرفوها أنتم ولا آباؤكم، فتعبدون هناك أصناما باطلة نهارا وليلا، لأني لن أبدي لهم رحمتي».","16:14":"لهذا يقول الرب: «ها أيام مقبلة لا يقال فيها بعد: حي هو الرب الذي أخرج شعب إسرائيل من مصر،","16:15":"إنما يقال: حي هو الرب الذي أخرج شعب إسرائيل من بلاد الشمال ومن سائر الأراضي التي سباهم إليها. لأني سأرجعهم ثانية إلى أرضهم التي وهبتها لآبائهم.","16:16":"ها أنا أرسل صيادين كثيرين، ليصطادوهم، ثم أبعث بقناصين كثيرين ليقتنصوهم من كل جبل ومن كل رابية ومن شقوق الصخور.","16:17":"لأن عيني تراقبان طرقهم التي لم تحتجب عني وإثمهم الذي لم يستتر عن عيني.","16:18":"فأعاقبهم عقابا مضاعفا على إثمهم، لأنهم دنسوا أرضي بجثث أصنامهم، وملأوا ميراثي بنجاساتهم».","16:19":"يارب أنت عزي وحصني وملاذي في يوم الضيق، إليك تقبل الأمم من أقاصي الأرض قائلة: «لم يرث آباؤنا سوى الباطل والأكاذيب وما لا جدوى منه.","16:20":"هل في وسع المرء أن يصنع لنفسه إلها؟ إن هذه ليست آلهة.","16:21":"فلذلك ها أنا أعرفهم هذه المرة قوتي وجبروتي، فيدركون أن اسمي يهوه (أي الرب)».","17:1":"»قد دونت خطيئة يهوذا بقلم من حديد، ونقشت برأس من الماس على ألواح قلوبهم وعلى قرون المذابح،","17:2":"بينما أبناؤهم يذكرون مذابحهم وأنصاب عشتاروث إلى جوار كل شجرة خضراء وعلى الآكام المرتفعة،","17:3":"وعلى الجبال المنتشرة في البرية الشاسعة. لذلك أجعل ثروتك وكنوزك نهبا، ثمنا لخطيئتك التي ارتكبت في جميع تخومك،","17:4":"وتفقد بنفسك ميراثك الذي وهبته لك، وأجعلك مستعبدا لأعدائك في أرض لا تعرفها لأنك أضرمت نارا في غضبي لا يخمد لها أوار».","17:5":"وهذا ما يقوله الرب: «ليكن ملعونا كل من يتوكل على بشر، ويتخذ من الناس ذراع قوة له، ويحول قلبه عن الرب.","17:6":"فيكون كالأثل في البادية، لا يرى الفلاح عندما يقبل. يقيم في حر الصحراء الشديد، في الأرض المهجورة من الناس لملوحتها.","17:7":"ولكن مبارك الرجل الذي يتكل على الرب، ويتخذه معتمدا له،","17:8":"فيكون كشجرة مغروسة عند الميا ه، تمد جذورها إلى الجدول، ولا تخشى اشتداد الحر المقبل، إذ تظل أوراقها خضراء، ولا يفزعها القحط لأنها لا تكف عن الإثمار.","17:9":"القلب أخدع من كل شيء وهو نجيس، فمن يقدر أن يفهمه؟","17:10":"أنا الرب أفحص القلوب وأمتحن الأفكار، لأجازي كل واحد حسب طرقه، وبمقتضى أفعاله».","17:11":"مكتنز الغنى من غير حق كحجلة تحتضن وتفقس ما لم تبض، لأنه سرعان ما يفقده في منتصف حياته، ويضحى آخر أيامه أحمق.","17:12":"العرش المجيد المرتفع منذ البدء هو مقر مقدسنا.","17:13":"أيها الرب رجاء إسرائيل: إن جميع الذين يتخلون عنك يلحق بهم الخزي، والذين ينصرفون عنك (يزولون) كمن كتبت أسماؤهم على التراب لأنهم نبذوا الرب ينبوع المياه الحية.","17:14":"أبرئني يارب فأبرأ. خلصني فأخلص، فإنك أنت تسبحتي.","17:15":"ها هم يقولون لي: «أين قضاء الرب؟ ليأت».","17:16":"أما أنا فلم أتهرب من أن أكون راعيا لديك، وأنت تعرف أني لم أتمن مجيء يوم المحنة، وتعلم ما نطقت به شفتاي، لأن كل ما صدر عنهما كان في محضرك.","17:17":"لا تكن مثار رعب لي، فأنت ملاذي في يوم الشر.","17:18":"ليلحق الخزي بمضطهدي، ولكن احفظني من العار. ليرتعبوا هم، أما أنا فلا تدعني أرتعب. اجعل يوم الشر يحل بهم، واسحقهم سحقا مضاعفا.","17:19":"وهذا ما قاله الرب لي: «امض وقف عند بوابة أبناء الشعب التي يدخل منها ملوك يهوذا ويخرجون، وكذلك عند سائر بوابات أورشليم،","17:20":"وقل لهم: اسمعوا كلمة الرب ياملوك يهوذا وشعبها، وياجميع أهل أورشليم المجتازين في هذه البوابات.","17:21":"هذا ما يقوله الرب: احترسوا لأنفسكم ولا تحملوا أحمالا في يوم السبت ولا تدخلوها في بوابات أورشليم،","17:22":"ولا تنقلوا حملا إلى خارج بيوتكم في يوم السبت ولا تقوموا بأي عمل. إنما قدسوا يوم السبت كما أوصيت آباءكم.","17:23":"مع ذلك لم يطيعوا ولم يصغوا، بل قسوا قلوبهم لئلا يسمعوا ولئلا يقبلوا التأديب","17:24":"ولكن إن استمعتم أنتم، يقول الرب، ولم تدخلوا أحمالا في بوابات أورشليم في يوم السبت، بل قدستموه ولم تقوموا بأي عمل فيه،","17:25":"عندئذ يدخل من بوابات هذه المدينة ملوك ورؤساء ممن يجلسون على عرش داود، راكبين في عربات وعلى صهوات الجياد مع رؤسائهم، يواكبهم سكان يهوذا وأهل أورشليم، وتعمر هذه المدينة إلى الأبد بالسكان.","17:26":"ويقبل الناس من مدن يهوذا ومن حول أورشليم، ومن أرض بنيامين ومن السهل والجبل، ومن النقب، حاملين محرقات وذبائح وتقدمات وبخورا معطرا، وقرابين شكر إلى هيكل الرب.","17:27":"ولكن إن لم تستمعوا لي لتقدسوا يوم السبت، وثابرتم على حمل أثقال فيه لتدخلوها من بوابات أورشليم، فإني أضرم بواباتها بالنار فتلتهم قصور أورشليم، ولا تنطفيء».","18:1":"هذا ما أوحى الرب به إلى إرميا قائلا:","18:2":"«قم وامض إلى بيت الفخاري، وهناك أسمعك كلامي».","18:3":"فانطلقت إلى بيت الفخاري، فإذا به يعمل على دولابه.","18:4":"غير أن الإناء الذي كان يصنعه فسد بين يديه، فعاد يشكله إناء آخر كما طاب للفخاري أن يصوغه.","18:5":"عندئذ قال لي الرب:","18:6":"«ياذرية إسرائيل: ألا أستطيع أن أصنع بكم كما صنع الفخاري؟ إنكم في يدي كالطين في يد الفخاري.","18:7":"تارة أقضي على أمة وعلى مملكة بالاستئصال والهدم والدمار،","18:8":"فترتد تلك الأمة التي قضيت عليها بالعقاب عن شرها، فأكف عن الشر الذي نويت معاقبتها به.","18:9":"وتارة أقضي بمكافأة أمة أو مملكة ببناء قوتها وإنمائها.","18:10":"ثم لا تلبث أن ترتكب الشر أمامي ولا تسمع لصوتي، فأكف عن الخير الذي نويت أن أنعم به عليها.","18:11":"لذلك قل لرجال يهوذا وأهل أورشليم، هذا ما يعلنه الرب: ها أنا أدبر لكم شرا، وأعد لكم مؤامرة، فليرجع كل واحد منكم عن طريقه الشرير وقوموا سبلكم وأعمالكم.","18:12":"ولكنهم يجيبون: لا جدوى من هذا، بل نسعى وراء أهواء أفكارنا، وكل واحد منا يفعل ما يروق لعناد قلبه الأثيم».","18:13":"لذلك هكذا يقول الرب: «اسألوا بين الشعوب من سمع بمثل هذا؟ قد ارتكبت العذراء إسرائيل أمرا شديد الهول.","18:14":"هل يختفي ثلج لبنان عن منحدرات جباله الصخرية؟ وهل تتوقف مياهه الباردة المنحدرة من ينابيع بعيدة عن التدفق؟","18:15":"لكن شعبي قد نسيني وأحرق بخورا لأوثان باطلة، جعلته يتعثر في طرقه، في السبل القديمة، فسلك في ممرات وطرق غير معبدة.","18:16":"فتصبح أرضه خرابا، مثار صفير دهشة، وكل من يعبر بها يعتريه رعب ويهز رأسه.","18:17":"فأشتتهم أمام أعدائهم كريح شرقية، ولا ألتفت إليهم بل أدير لهم القفا في يوم محنتهم».","18:18":"ثم قالوا: «تعالوا نتآمر على إرميا، لأن الشريعة لا تبيد عن الكاهن، ولا المشورة عن الحكيم، ولا الوحي عن النبي. تعالوا نلذعه بوخزات اللسان ونصم آذاننا عن كلامه».","18:19":"أصغ لي يارب، واستمع إلى اتهامات خصومي.","18:20":"هل يجازى عن خير بشر؟ قد نقروا حفرة لنفسي. اذكر كيف وقفت أمامك أثني عليهم خيرا لأصرف غضبك عنهم.","18:21":"لذلك أسلم بنيهم لأنياب الجوع، واعهد بهم إلى قبضة السيف فتصبح نساؤهم ثكالى وأرامل، وليمت رجالهم، وليلق شبانهم حتفهم في المعارك بحد السيف.","18:22":"ليتردد صراخ في بيوتهم عندما ترسل عليهم جيش الغزاة بغتة، لأنهم حفروا هوة ليقتنصوني، ونصبوا فخاخا لرجلي.","18:23":"أما أنت يارب فقد عرفت جميع ما تآمروا به علي، فلا تصفح عن إثمهم، ولا تمح خطيئتهم من أمامك، بل ليعثروا منطرحين في حضرتك، وعاقبهم في أوان غضبك.","19:1":"وقال لي الرب: «امض واشتر جرة خزف، واصطحب معك بعض شيوخ الشعب وشيوخ الكهنة،","19:2":"وانطلق إلى وادي ابن هنوم القائم عند مدخل باب الفخار، وناد هناك بالكلمات التي أمليها عليك،","19:3":"وقل: اسمعوا ياملوك يهوذا، وياأهل أورشليم كلمة الرب. هذا ما يعلنه الرب القدير إله إسرائيل: انظروا، ها أنا أجلب على هذا الموضع شرا تطن له أذنا كل من يسمع به،","19:4":"لأنهم تركوني، وتنكروا لهذا الموضع ودنسوه بإحراق بخور لآلهة أوثان لم يعرفوها لا هم ولا آباؤهم ولا ملوك يهوذا أيضا، ولأنهم ملأوا هذا الموضع من دم الأبرياء.","19:5":"وبنوا مرتفعات لعبادة البعل ليحرقوا بنيهم بالنار كقرابين محرقات للبعل مما لم أوص به ولم أتحدث عنه ولم يخطر ببالي.","19:6":"لذلك، ها أيام مقبلة، يقول الرب، لا يدعى فيها هذا المكان توفة من بعد أو وادي ابن هنوم، بل وادي القتل.","19:7":"وأبطل في هذا الموضع مشورات أهل يهوذا وأورشليم، فيتساقطون بحد السيف أمام أعدائهم وبأيدي طالبي نفوسهم، وأجعل جثثهم طعاما لجوارح السماء ووحوش الأرض.","19:8":"وأدمر هذه المدينة وأجعلها مثار صفير. كل من يمر بها تعتريه الدهشة ويصفر لما حل بها من نكبات.","19:9":"وأطعمهم لحوم أبنائهم وبناتهم، ويأكل كل واحد لحم جاره في أثناء الحصار والضيقة التي يضايقهم بها أعداؤهم وطالبو نفوسهم.","19:10":"ثم حطم الجرة على مرأى الرجال الذاهبين معك،","19:11":"وقل لهم: هذا ما يعلنه الرب القدير: سأحطم هذا الشعب وأدمر هذه المدينة كما يحطم المرء إناء الخزاف، بحيث لا يمكن إصلاحه، ويدفن الرجال في توفة إذ لن يتوافر موضع آخر للدفن.","19:12":"هذا ما سأجريه على هذا المكان وعلى سكانه، يقول الرب، سأجعل هذه المدينة مثل توفة،","19:13":"وأحيل بيوت أورشليم وبيوت ملوك يهوذا إلى موضع نجاسة، وكذلك كل البيوت التي أحرقوا على سطوحها بخورا لكواكب السماء، وسكبوا سكائب خمر لآلهة أخرى».","19:14":"وجاء إرميا من توفة، التي كان الرب قد أرسله إليها ليتنبأ، ووقف في ساحة هيكل الرب، وخاطب جميع الشعب:","19:15":"هذا ما يقوله الرب القدير إله إسرائيل: «ها أنا جالب على هذه المدينة وعلى جميع قراها كل الشر الذي قضيت به عليها، لأنهم قسوا قلوبهم فلم يسمعوا كلامي».","20:1":"وسمع الكاهن فشحور بن إمير الذي كان الناظر الأول على بيت الرب إرميا يتنبأ بهذه الأمور،","20:2":"فضرب فشحور إرميا النبي وزجه في المقطرة التي بباب بنيامين الأعلى الذي عند هيكل الرب.","20:3":"وفي اليوم الثاني عندما أخرج فشحور إرميا من المقطرة، قال له إرميا: إن الرب لم يدع اسمك فشحور، بل مجور مسا بيب (أي: رعبا من كل ناحية).","20:4":"هذا ما يقوله الرب: ها أنا أجعلك أنت وجميع أحبائك عرضة للرعب فيتساقطون بحد سيوف أعدائهم على مرأى منك، وأسلم كل أهل يهوذا ليد ملك بابل فيجليهم إلى بابل ويذبحهم بالسيف.","20:5":"وأدفع كل ثروة هذه المدينة، وكل نتاجها ونفائسها، وكل كنوز ملوك يهوذا إلى يد أعدائها، فيغنمونها ويستولون عليها وينقلونها معهم إلى بابل.","20:6":"أما أنت يافشحور وجميع المقيمين معك في بيتك فتذهبون إلى الأسر في بابل حيث تموت وتدفن هناك أنت وسائر أحبائك الذين تنبأت لهم بالأكاذيب».","20:7":"يارب قد أقنعتني فاقتنعت، أنت أقوى مني فغلبت، فأصبحت مثار سخرية طوال النهار. كل واحد يستهزيء بي.","20:8":"لأني كلما تكلمت أصرخ منددا، وأنادي: «ظلم واغتصاب» فجلبت علي كلمة الرب الاحتقار والعار طوال النهار.","20:9":"إن قلت: «سأكف عن ذكره ولا أتكلم باسمه بعد» صار كلامه في قلبي كنار محرقة محصورة في عظامي، فأعياني كتمانه وعجزت عن كبته.","20:10":"لأني سمعت نفثات تهديد من كثيرين، وأحاط بي رعب من كل جانب. يقولون: «اشتكوا عليه فنشتكي عليه»، حتى جميع أصدقائي الحميمين يرقبون كبوتي قائلين: «لعله يتعثر فنتغلب عليه وننتقم منه».","20:11":"لكن الرب معي كمحارب جبار، لهذا يعثر كل مضطهدي ولا يظفرون بي. يلحق بهم عار عظيم لأنهم لا يفلحون، ويظل خزيهم مذكورا إلى الأبد.","20:12":"أيها الرب القدير مختبر الصديق والمطلع على سرائر النفوس، دعني أشهد انتقامك منهم لأني إليك فوضت قضيتي.","20:13":"اشدوا للرب وسبحوه، لأنه أنقذ نفس المسكين من قبضة فاعلي الإثم.","20:14":"ليكن ملعونا ذلك اليوم الذي ولدت فيه، وليخل اليوم الذي أنجبتني فيه أمي من كل بركة.","20:15":"ليكن ملعونا ذلك الرجل الذي بشر أبي قائلا: قد ولد لك ابن فجعل قلبه يفيض بالفرح.","20:16":"ليصبح ذلك الرجل كالمدن التي قلبها الرب من غير رفق، وليسمع صراخ المعارك في الصباح، وضجيج جلبتها عند الظهيرة.","20:17":"ليكن ذلك الرجل ملعونا لأنه لم يقتلني من الرحم، فتضحى أمي قبرا لي، وتظل حبلى بي إلى الأبد.","20:18":"لماذا خرجت من الرحم لأقاسي التعب والأوجاع، وأفني أيامي بالخزي؟","21:1":"الكلام الذي أوحى به الرب إلى إرميا النبي، عندما أرسل إليه الملك صدقيا فشحور بن ملكيا وصفنيا بن معسيا الكاهن، قائلا:","21:2":"«اسأل الرب عنا، لأن نبوخذناصر ملك بابل قد أعلن علينا حربا، لعل الرب يجري لنا معجزة كسابق معجزاته، ويصرفه عنا».","21:3":"فقال لهما إرميا: «هذا ما تقولان لصدقيا:","21:4":"هذا ما يعلنه الرب إله إسرائيل: ها أنا أرد أسلحتكم التي بأيديكم التي تحاربون بها ملك بابل والكلدانيين الذين يحاصرونكم من خارج السور، وأجمعهم في وسط هذه المدينة.","21:5":"وأحاربكم بنفسي بيد ممدودة وذراع شديدة، بغضب وحنق وسخط عظيم.","21:6":"وأبيد أهل هذه المدينة رجالا وبهائم، فيموتون بوبأ رهيب،","21:7":"وأسلم صدقيا ملك يهوذا وخدامه ومن بقي من أهل هذه المدينة، الناجين من الوبأ والسيف والجوع، إلى يد نبوخذناصر ملك بابل، وإلى أيدي أعدائهم وطالبي نفوسهم، فيقتلهم بحد السيف، ولا يرثي لهم ولا يشفق أو يرحم.","21:8":"وتقول لهذا الشعب: هذا ما يعلنه الرب: ها أنا أعرض أمامكم طريق الحياة وطريق الموت.","21:9":"فمن يمكث في هذه المدينة يموت بالسيف والجوع والوباء، ومن يلجأ إلى الكلدانيين الذين يحاصرونكم ويستسلم لهم يحيا ويغنم نفسه.","21:10":"فإني قد قضيت على هذه المدينة بالشر لا بالخير يقول الرب، لهذا يستولي عليها ملك بابل فيحرقها بالنار».","21:11":"«وتقول لبيت ملك يهوذا: اسمعوا قضاء الرب:","21:12":"ياذرية داود، هذا ما يعلنه الرب: أجروا العدل في الصباح، وأنقذوا المغتصب من يد المغتصب لئلا ينصب غضبي كنار، فيحرق وليس من يخمده لفرط ما ارتكبتم من أعمال شريرة.","21:13":"ياأورشليم ياساكنة الوادي، ياصخرة السهل، ها أنا أقف ضدك يقول الرب، وأنتم يامن تقولون: «من يهاجمنا؟ ومن يقتحم منازلنا؟»","21:14":"ها أنا أعاقبكم بحسب ثمار أعمالكم، وأوقد نارا في غابة مدينتكم فتلتهم كل ما حولها».","22:1":"هذا ما يعلنه الرب: «انحدر إلى قصر ملك يهوذا وأعلن هناك هذا القضاء:","22:2":"اسمع كلمة الرب ياملك يهوذا المتربع على عرش داود، أنت وخدامك وشعبك المجتازين من هذه البوابات:","22:3":"أجروا العدل وأنقذوا المغتصب من يد المغتصب، ولا تجوروا على الغريب واليتيم والأرملة، ولا تتعسفوا عليهم، ولا تسفكوا دما بريئا في هذا الموضع.","22:4":"لأنكم إن أطعتم هذا الكلام فإن ملوكا يتربعون على عرش داود، راكبين مركبات وخيولا يجتازون هم وخدامهم وشعبهم بوابات هذا القصر.","22:5":"ولكن إن عصيتم هذه الوصايا، فقد أقسمت بنفسي يقول الرب، أن يتحول هذا القصر إلى أطلال».","22:6":"لأنه هذا ما يقوله الرب عن قصر ملك يهوذا: «أنت عزيز علي كجلعاد وكرأس لبنان، ومع ذلك فإني سأجعلك قفرا ومدنا مهجورة.","22:7":"سأجند عليك مهلكين مدججين بسلاحهم فيقطعون نخبة أرزك ويطرحونها إلى النار.","22:8":"وتعبر في هذه المدينة أمم كثيرة، فيقول كل واحد لرفيقه: لماذا صنع الرب هكذا بهذه المدينة العظيمة؟","22:9":"فيجيبون: لأنهم نبذوا عهد الرب إلههم وسجدوا للأوثان وعبدوها».","22:10":"لا تنوحوا على الميت ولا تندبوه، إنما ابكوا على المنفي الذي لن يرجع ولن يرى أرض موطنه","22:11":"لأنه هذا ما يعلنه الرب عن شلوم بن يوشيا ملك يهوذا، الذي تولى العرش عوض أبيه، والذي خرج منفيا من هذا المكان: «إنه لن يرجع إلى هنا بعد.","22:12":"بل يموت في منفاه الذي سبوه إليه ولن يرجع ليرى هذه الأرض ثانية».","22:13":"«ويل لمن يبني بيته على الظلم ومخادعه العالية على الجور، الذي يستخدم جاره مجانا ولا يوفيه أجرة عمله،","22:14":"الذي يقول: «سأبني لنفسي بيتا رحبا وغرفا عالية فسيحة. وأفتح له كوى وأغشيه بألواح الأرز وأدهنه بألوان حمراء.","22:15":"أتظن أنك صرت ملكا لأنك بنيت بيتك من الأرز؟ أما أكل أبوك وشرب وأجرى عدلا وحقا، فتمتع بالخيرات؟","22:16":"قد قضى بالعدل للبائس والمسكين فأحرز خيرا. أليست هذه هي معرفتي؟» يقول الرب","22:17":"«أما أنت فعيناك وقلبك متهافتة على الربح الحرام، وعلى سفك الدم البريء، وعلى الظلم والابتزاز».","22:18":"لذلك هذا ما يقوله الرب عن يهوياقيم بن يوشيا، ملك يهوذا: «لن يندبك أحد قائلا: آه ياأخي أو آه ياأختي، أو يندبون عليه قائلين: آواه ياسيدي، أو آه على جلاله.","22:19":"بل يدفن دفن حمار، مجرورا ومطروحا خارج بوابات أورشليم».","22:20":"«اصعدي ياأورشليم إلى لبنان واصرخي. أطلقي صوتك في باشان وأعولي من عباريم لأن جميع محبيك قد سحقوا.","22:21":"حذرتك في أثناء عزك فقلت: لن أصغي. أنت متمردة منذ صباك لا تسمعين لصوتي.","22:22":"ستعصف الريح بكل رعاتك، ويذهب محبوك إلى السبي. عندئذ يعتريك الخزي والعار لشرك.","22:23":"ياساكنة لبنان المعششة في الأرز، لشد ما تئنين عندما تفاجئك الأوجاع، فتكونين كامرأة تقاسي من المخاض».","22:24":"«حي أنا» يقول الرب، «لو كان كنياهو بن يهوياقيم ملك يهوذا خاتما في يدي اليمنى لنزعته منها.","22:25":"وأسلمته لطالبي نفسه، إلى أيدي من يفزع منهم، وإلى قبضة نبوخذناصر ملك بابل، وإلى أيدي الكلدانيين.","22:26":"سأطوح به وبأمه التي حملته إلى أرض أخرى، لم يولدا فيها، وهناك يموتان.","22:27":"ولن يعودا قط إلى الأرض التي يتوقان إلى الرجوع إليها».","22:28":"هذا الرجل كنياهو وعاء منبوذ محطم، وإناء لا يحفل به أحد. لماذا طوح به وبأبنائه إلى أرض لا يعرفونها؟","22:29":"ياأرض! ياأرض! ياأرض! اسمعي كلمة الرب:","22:30":"«سجلوا أن هذا الإنسان عقيم، رجل لن يفلح في حياته، ولن ينجح أحد من ذريته في الجلوس على عرش داود وتولي ملك يهوذا».","23:1":"يقول الرب: «ويل للرعاة الذين يبيدون ويبددون غنم رعيتي (أي شعبي)».","23:2":"لذلك هذا ما يقوله الرب إله إسرائيل عن الرعاة الذين يرعون شعبي: «لقد بددتم غنمي (أي شعبي) وطردتموها، ولم تتعهدوها. فها أنا أعاقبكم على شر أعمالكم.","23:3":"وأجمع شتات غنمي من جميع الأراضي التي أجليتها إليها، وأردها إلى مراعيها فتنمو وتتكاثر،","23:4":"وأقيم عليها رعاة يتعهدونها فلا يعتريها خوف من بعد ولا ترتعد ولا تضل.","23:5":"ها أيام مقبلة أقيم فيها لداود ذرية بر، ملكا يسود بحكمة، ويجري في الأرض عدلا وحقا.","23:6":"في عهده يتم خلاص شعب يهوذا، ويسكن شعب إسرائيل آمنا. أما الاسم الذي سيدعى به فهو: الرب برنا.","23:7":"لذلك ها أيام مقبلة لا يردد فيها الناس من بعد: حي هو الرب الذي أخرج بني إسرائيل من ديار مصر.","23:8":"بل يقولون: حي هو الرب الذي أخرج ذرية شعب إسرائيل، وأتى بهم من أرض الشمال ومن كافة الديار التي أجلاهم إليها، فيسكنون في أرضهم».","23:9":"ثم تكلم إرميا عن الأنبياء الكذبة فقال: «إن قلبي منكسر في داخلي، وجميع عظامي ترتجف، فأنا بتأثير الرب وبفعل كلامه المقدس كرجل سكران غلبت عليه الخمر","23:10":"لأن الأرض قد اكتظت بالفاسقين، وناحت من عاقبة لعنة الله، فجفت مراعي الحقول لأن مساعيهم باتت شريرة، وجبروتهم مسخر للباطل».","23:11":"ويقول الرب: «النبي والكاهن كافران، وفي بيتي وجدت شرهما.","23:12":"لذلك يضحي طريقهما مزالق لهما، تفضي بهما إلى الظلمات التي يطردون إليها، ويهويان فيها لأني أجلب عليهما شرا في سنة عقابهما».","23:13":"في أوساط أنبيا ء السامرة شهدت أمورا كريهة، إذ تنبأوا باسم البعل، وأضلوا شعبي إسرائيل.","23:14":"وفي أوساط أنبياء أورشليم رأيت أمورا مهولة: يرتكبون الفسق، ويسلكون في الأكاذيب، يشددون أيدي فاعلي الإثم لئلا يتوب أحد عن شره. صاروا جميعا كسكان سدوم وأصبح أهلها كأهل عمورة.","23:15":"لذلك هذا ما يقوله الرب القدير عن الأنبياء: «ها أنا أطعمهم أفسنتينا وأسقيهم ماء مسموما، لأنه من أنبياء أورشليم شاع الكفر في كل أرجاء الأرض».","23:16":"«لا تسمعوا لأقوال الأنبياء الذين يتنبأون لكم ويخدعونكم بالأوهام، لأنهم ينطقون برؤى مخيلاتهم، ولا يتكلمون بما أوحى به فمي.","23:17":"قائلين بإصرار لمن يحتقرونني: قد أعلن الرب أن السلام يسودكم ويرددون لكل من يجري وراء أهواء قلبه: لن يصيبكم ضر.","23:18":"مع أنه ليس بينهم من مثل في مجلس الرب ورأى وأنصت لكلمته، ولا من أصغى لقوله وأطاعه.","23:19":"ها عاصفة سخط الرب قد انطلقت، وزوبعة هوجاء قد ثارت لتجتاح رؤوس الأشرار.","23:20":"فغضب الرب لن يرتد حتى ينجز مقاصد قلبه التي ستدركونها بوضوح في آخر الأيام.","23:21":"إني لم أرسل هؤلاء الأنبياء، ومع ذلك انطلقوا راكضين، ولم أوح لهم ومع ذلك يتنبأون.","23:22":"لو مثلوا حقا في مجلسي لبلغوا كلامي لشعبي، ولكانوا ردوهم عن مساوئهم وعن شر أعمالهم.","23:23":"ألعلي أرى فقط ما يجري عن قرب، ولست إلها يرقب ما يجري عن بعد؟","23:24":"أيمكن لأحد أن يتوارى في أماكن خفية فلا أراه؟ أما أملأ السماوات والأرض؟","23:25":"قد سمعت ما نطق به المتنبئون باسمي زورا قائلين: قد حلمت، قد حلمت.","23:26":"إلى متى يظل هذا الخداع مكنونا في قلوب المتنبئين زورا؟ إنهم حقا أنبياء خداع، يتنبأون بأوهام قلوبهم.","23:27":"فينسون شعبي اسمي بما يقصه كل واحد منهم على صاحبه من أحلامه، كما نسي آباؤهم اسمي لأجل وثن البعل.","23:28":"فليقص النبي الحالم حلمه. ولكن من لديه كلمتي فليعلنها بالحق، إذ ماذا يجمع بين التبن والحنطة؟","23:29":"أليست كلمتي كالنار، وكالمطرقة التي تحطم الصخور؟","23:30":"لذلك ها أنا أقاوم هؤلاء الأنبياء الذين ينتحل كل منهم كلام الآخر،","23:31":"وأقاوم الأنبياء الذين يسخرون ألسنتهم قائلين: الرب يقول هذا.","23:32":"ها أنا أقاوم المتنبئين بأحلام كاذبة ويقصونها مضلين شعبي بأكاذيبهم واستخفافهم، مع أني لم أرسلهم ولم أكلفهم بشيء. ولا جدوى منهم لهذا الشعب.","23:33":"إذا سألك أحد من هذا الشعب أو نبي أو كاهن: ما هو وحي قضاء الرب؟ فأجبهم: أنتم وحي قضائه. وسأطرحكم، يقول الرب.","23:34":"أما النبي أو الكاهن أو أي واحد من الشعب يدعي قائلا: هذا وحي الرب، فإني سأعاقبه مع أهل بيته.","23:35":"لذلك هكذا يواظب كل واحد على القول لصاحبه، وكل جار لجاره: ما هو جواب الرب؟ أو بماذا تكلم الرب؟","23:36":"أما ادعاء وحي الرب فلا تذكروه من بعد، فإن كلمة المرء تغدو وحي قضائه، إذ قد حرفتم كلام الإله الحي، الرب القدير، إلهنا.","23:37":"لذلك هذا ما تسأل به النبي: بماذا أجاب الرب، وبماذا تكلم؟»","23:38":"فإن ادعيتم وحي قضاء الرب، فهذا ما يعلنه الرب: لأنكم ادعيتم وحي قضائه بعد أن حظرته عليكم قائلا: لا تقولوا هذا وحي قضائه»","23:39":"لذلك ها أنا أنساكم تماما، وأطردكم من محضري أنتم والمدينة التي وهبتها لكم ولآبائكم.","23:40":"وألحق بكم عارا أبديا وخزيا لا ينسى».","24:1":"وبعدما سبى نبوخذناصر ملك بابل، يكنيا بن يهوياقيم ملك يهوذا مع سائر رؤساء يهوذا، والنجارين والحدادين، من أورشليم، وأتى بهم إلى بابل، أراني الرب في رؤيا سلتي تين موضوعتين أمام هيكل الرب.","24:2":"وكان في إحدى السلتين تين جيد كالتين الباكوري، وفي الأخرى تين رديء تعاف النفس أكله من فرط رداءته.","24:3":"فقال لي الرب: «ماذا ترى ياإرميا؟» فأجبت: «تينا: الجيد منه يمتاز بجودته، والرديء منه تعافه النفس لفرط رداءته».","24:4":"فقال الرب لي:","24:5":"هذا ما يعلنه الرب إله إسرائيل: سأعتني بالمسبيين من يهوذا الذين أجليتهم لخيرهم عن هذا الموضع إلى أرض الكلدانيين، كمثل هذا التين الجيد.","24:6":"وسأرعاهم بعيني لخيرهم، وأردهم إلى هذه الأرض، وأبنيهم ولا أهدمهم، وأغرسهم ولا أستأصلهم.","24:7":"وأهبهم قلبا ليعرفوا أني أنا الرب، فيكونوا لي شعبا وأكون لهم إلها، لأنهم يرجعون إلي من كل قلوبهم.","24:8":"أما صدقيا ملك يهوذا وعظماؤه وسائر أهل أورشليم الذين مكثوا في هذه الأرض والذين نزحوا إلى ديار مصر، فإني أجعلهم مثل هذا التين الرديء الذي تعاف النفس أكله لفرط رداءته.","24:9":"وأوقعهم في الضيق والشر في جميع ممالك الأرض، وأجعلهم عارا وعبرة وأحدوثة ولعنة في جميع الأماكن التي أجليهم إليها.","24:10":"وأعرضهم للسيف والجوع والوباء حتى يفنوا في الأرض التي وهبتها لهم ولآبائهم».","25:1":"النبوءة التي أوحى بها الرب إلى إرميا عن جميع شعب يهوذا، في السنة الرابعة من حكم يهوياقيم بن يوشيا ملك يهوذا، الموافقة للسنة الأولى من ملك نبوخذناصر ملك بابل،","25:2":"والتي خاطب بها إرميا النبي كل شعب يهوذا وجميع سكان أورشليم قائلا:","25:3":"«على مدى ثلاث وعشرين سنة، أي مند السنة الثالثة عشرة من حكم يوشيا بن آمون ملك يهوذا، وحتى هذا اليوم، والرب يوحي إلي بكلمته، فخاطبتكم بها تكرارا منذ البدء ولكنكم لم تسمعوا.","25:4":"ومع أن الرب قد واظب على إرسال عبيده الأنبياء إليكم، فإنكم لم تصغوا ولم تستمعوا لإنذاراته.","25:5":"وقد قالوا لكم: توبوا الآن. ليرجع كل واحد منكم عن طرقه الشريرة وممارساته الأثيمة فتقيموا في الأرض التي وهبها لكم الرب على مدى الدهور،","25:6":"ولا تضلوا وراء آلهة أخرى لتعبدوها وتسجدوا لها، ولا تثيروا غيظي بما تصنعه أيديكم من أوثان. عندئذ لا أنزل بكم أذى.","25:7":"غير أنكم لم تسمعوا لي، بل أثرتم غيظي بما جنته أيديكم، فاستجلبتم على أنفسكم الشر».","25:8":"لذلك هكذا يقول الرب القدير: «لأنكم عصيتم كلامي،","25:9":"فها أنا أجند جميع قبائل الشمال بقيادة نبوخذناصر عبدي، وآتي بها إلى هذه الأرض فيجتاحونها ويهلكون جميع سكانها مع سائر الأمم المحيطة بها، وأجعلهم مثار دهشة وصفير، وخرائب أبدية.","25:10":"وأبيد من بينهم أهازيج الفرح والطرب وصوت غناء العريس والعروس، وضجيج الرحى ونور السراج.","25:11":"فتصبح هذه الأرض بأسرها قفرا خرابا، وتستعبد جميع هذه الأمم لملك بابل طوال سبعين سنة.","25:12":"وفي ختام السبعين سنة أعاقب ملك بابل وأمته، وأرض الكلدانيين على إثمهم، وأحولها إلى خراب أبدي»، يقول الرب.","25:13":"«وأنفذ في تلك الأرض كل القضاء الذي نطقت به عليها، كل ما دون في هذا الكتاب وتنبأ به إرميا على جميع الأمم.","25:14":"إذ أن أمما كثيرة وملوكا عظماء يستعبدونهم أيضا، وهكذا أجازيهم بمقتضى أفعالهم وما جنته أيديهم من أعمال أثيمة».","25:15":"وهذا ما أعلنه لي الرب إله إسرائيل: «خذ كأس خمر غضبي من يدي، واسق منها جميع الأمم التي أرسلك إليها،","25:16":"فتشرب وتترنح، وتجن بفعل السيف الذي أرسله بينها».","25:17":"فتناولت الكأس من يد الرب وسقيت منها جميع الأمم التي بعثني إليها الرب:","25:18":"أورشليم ومدن يهوذا وملوكها وعظماءها، لأجعلها قفرا خرابا ومثار صفير ولعنة إلى هذا اليوم.","25:19":"وسقيت منها كذلك فرعون ملك مصر وخدامه وعظماءه وكل شعبه،","25:20":"وكل الغرباء المقيمين في وسطهم، وجميع ملوك أرض عوص، وسائر ملوك الفلسطينيين: ملوك أشقلون، وغزة، وعقرون وبقية أشدود،","25:21":"وآدوم، وموآب، وبني عمون،","25:22":"وكل ملوك صور وصيدون وملوك الجزائر عبر البحر،","25:23":"وددان وتيماء وبوز، وكل ذوي الشعر المقصوص الزوايا،","25:24":"وكل ملوك العرب، وسائر ملوك القبائل المنضمة إليهم المقيمين في الصحراء،","25:25":"وكل ملوك زمري، وعيلام، وجميع ملوك مادي.","25:26":"وكل ملوك الشمال، القريبين والبعيدين، الواحد تلو الآخر، وكل الممالك المنتشرة على وجه الأرض. ثم بعد ذلك يشرب منها ملك بابل.","25:27":"ثم قل لهم، هذا ما يعلنه الرب القدير إله إسر ائيل: اشربوا واثملوا وتقيأوا واسقطوا صرعى، ولا تقوموا من جراء السيف الذي أرسله في وسطكم.","25:28":"وإن أبوا أن يتناولوا الكأس من يدك ليشربوا منها، فقل لهم: هذا ما يعلنه الرب القدير: لابد لكم من شربها،","25:29":"لأني شرعت أعاقب المدينة التي دعي اسمي عليها، فهل تفلتون أنتم من العقاب؟ فها أنا قد سلطت السيف على جميع سكان الأرض، يقول الرب القدير.","25:30":"أما أنت فتنبأ عليهم بكل هذا القضاء، وقل لهم: «الرب يزأر من العلاء، ومن مسكن قدسه يدوي صوته. يزأر زئيرا على مسكنه، ويجهر هاتفا على جميع سكان الأرض كما يجهر الدائسون على العنب».","25:31":"قد بلغت الجلبة جميع أقاصي الأرض، لأن للرب دعوى على الأمم، فيدخل في محاكمة مع البشر، ويلقي بالأشرار إلى السيف.","25:32":"ها الشر يندفع من أمة إلى أمة، وها زوبعة رهيبة تثور من أقصى أطراف الأرض.","25:33":"وينتشر قتلى غضب الرب في ذلك اليوم من أقصى الأرض إلى أقصاها. لا ينوح عليهم أحد، ولا يجمعون ولا يدفنون، بل يصيرون نفاية فوق سطح الأرض.","25:34":"أعولوا أيها الرعاة وابكوا، تمرغوا في الرماد ياقادة الشعب، لأن أوان ذبحكم قد حان، فأشتتكم فتسقطون (وتتناثرون) كإناء فاخر.","25:35":"لن يبقى للرعاة ملجأ يلوذون به، ولا مهرب لقادة الشعب.","25:36":"اسمعوا صوت الرعاة وولولة قادة الشعب، لأن الرب يتلف مراعيهم.","25:37":"عم الخراب المواقع التي يسودها السلام من فرط غضب الله العنيف.","25:38":"قد هجر كالشبل عرينه، لأن الأرض قد صارت خرابا من سيف العاتي، من شدة احتدام غضبه.","26:1":"وفي بداية حكم يهوياقيم بن يوشيا ملك يهوذا، أوحى الرب بهذا الكلام قائلا:","26:2":"هذا ما يعلنه الرب: «قف في ساحة هيكل الرب، وبلغ كل أهل مدن يهوذا القادمين للعبادة في هيكل الرب بجميع الكلام الذي أمرتك أن تخاطبهم به. وإياك أن تحذف كلمة.","26:3":"لعلهم يسمعون ويرجع كل واحد منهم عن طريقه الأثيم، فأمتنع عن الشر الذي نويت أن أوقعه بهم لسوء أعمالهم».","26:4":"خاطبهم قائلا: «هذا ما يعلنه الرهب: إن لم تطيعوني فتسلكوا في شريعتي التي جعلتها أمامكم،","26:5":"وإن لم تسمعوا لتحذيرات عبيدي الأنبياء الذين أرسلتهم منذ البداية إليكم، ولم تصغوا إليهم،","26:6":"فإني أجعل هذا الهيكل نظير شيلوه، وهذه المدينة لعنة لجميع أمم الأرض».","26:7":"فسمع الكهنة والأنبياء وسائر الشعب إرميا يردد هذا الكلام في هيكل الرب.","26:8":"فلما فرغ إرميا من الإدلاء بكل ما أمره الرب أن يخاطب به الشعب، قبض الكهنة والأنبياء وسائر الشعب عليه قائلين: «لابد أن تموت.","26:9":"لماذا تنبأت باسم الرب قائلا: إن مصير هذا الهيكل سيكون كمصير شيلوه، وهذه المدينة تصير خربا مهجورة؟». وأحاط الشعب كله بإرميا في بيت الرب.","26:10":"وعندما سمع بذلك رؤساء يهوذا أقبلوا من قصر الملك إلى هيكل الرب وجلسوا في مدخل بوابة هيكل الرب الجديدة،","26:11":"ثم خاطب الكهنة والأنبياء رؤساء يهوذا وسائر الشعب: «هذا الرجل يستحق حكم الموت. لأنه تنبأ على هذه المدينة بالدمار كما سمعتم بآذانكم».","26:12":"فقال إرميا لجميع الرؤساء وكل الشعب: «الرب قد بعثني لأتنبأ على هذا الهيكل وعلى هذه المدينة بكل القضاء الذي سمعتموه.","26:13":"فالآن قوموا طرقكم وأعمالكم، وأطيعوا صوت الرب إلهكم، فيمتنع عن الشر الذي قضى به عليكم.","26:14":"أما أنا فإني في أيديكم. اصنعوا بي ما يحلو لكم.","26:15":"ولكن تيقنوا أنكم إن قتلتموني فإنكم تجلبون دما بريئا على أنفسكم وعلى هذه المدينة وعلى أهلها، لأن الرب قد بعثني حقا لأعلن قضاءه في مسامعكم».","26:16":"عندئذ قال الرؤساء وكل الشعب للكهنة والأنبياء: «هذا الرجل لا يستحق حكم الموت لأنه خاطبنا باسم الرب إلهنا».","26:17":"ثم قام رجال من شيوخ البلاد وقالوا لجماعة الشعب:","26:18":"«إن ميخا المورشتي تنبأ في عهد حزقيا ملك يهوذا، وخاطب كل شعب يهوذا قائلا هذا ما يعلنه الرب القدير: إن صهيون ستحرث كحقل وتصير أورشليم كومة من الخرائب، وجبل الهيكل مرتفعا تنمو عليه أشجار الغاب.","26:19":"فهل قتله حزقيا ملك يهوذا وكل شعب يهوذا؟ أما اتقى الرب واستعطفه، فامتنع الرب عن الشر الذي قضى به عليهم؟ إننا نكاد نجلب بلاء عظيما على أنفسنا».","26:20":"وكان هناك أيضا رجل آخر يدعى أوريا بن شمعيا من قرية يعاريم يتنبأ باسم الرب، فتنبأ على هذه المدينة وعلى هذه الأرض بمثل نبؤة إرميا.","26:21":"فبلغ كلامه مسامع الملك يهوياقيم وجميع محاربيه الأشداء وسائر الرؤساء، فطلب الملك قتله، فلما سمع أوريا بذلك خاف وهرب إلى مصر.","26:22":"فبعث الملك يهوياقيم رجالا إلى مصر، منهم ألناثان بن عكبور يصحبه نفر من المرافقين،","26:23":"فأخرجوا أوريا من مصر وأتوا به إلى الملك يهوياقيم فقتله بالسيف، وطرح جثته في مقابر عامة الناس.","26:24":"أما إرميا فقد حظي بحماية أخيقام بن شافان فلم يسلم لأيدي الشعب ليقتلوه.","27:1":"وفي مستهل حكم يهوياقيم بن يوشيا ملك يهوذا أوحى الرب بهذه النبوءة إلى إرميا:","27:2":"«هذا ما أعلنه الرب: اصنع لنفسك ربطا وأنيارا وضعها على عنقك،","27:3":"وابعث برسالة إلى ملوك أدوم وموآب وبني عمون وصور وصيدون مع الرسل الموفدين إلى أورشليم إلى صدقيا ملك يهوذا،","27:4":"وأوصهم أن ينقلوا هذه الرسالة إلى سادتهم قائلا: هذا ما يعلنه الرب القدير إله إسرائيل:","27:5":"أنا بقوتي العظيمة وبذراعي الممدودة صنعت الأرض بما عليها من بشر وبهائم، ووهبتها لمن طاب لي أن أهبها له.","27:6":"والآن قد عهدت بجميع هذه الأراضي إلى نبوخذناصر ملك بابل عبدي، وأعطيته أيضا حيوان الحقل ليكون في خدمته.","27:7":"فتستعبد له وَلابنه ولحفيده جميع أمم الأرض، إلى أن يحين موعد استعباد أرضه، عندئذ تستعبده أمم كثيرة وملوك عظماء.","27:8":"ولكن إن أبت أية أمة أو مملكة الاستعباد لنبوخذناصر ملك بابل، ورفضت أن تضع عنقها تحت نيره، فإني أعاقبها بالسيف والجوع والوباء إلى أن أبيدهم بيده، يقول الرب.","27:9":"فلا تصغوا إلى أنبيائكم الكذبة وعرافيكم وحالميكم وعائفيكم وسحرتكم القائلين لكم: لن تستعبدوا لملك بابل،","27:10":"لأنهم إنما يتنبأون لكم بالباطل ليبعدوكم عن أرضكم ولأجليكم عنها فتهلكوا","27:11":"ولكن كل أمة تستسلم لملك بابل وتستعبد له أبقيها في أرضها، يقول الرب، فتحرثها وتقيم فيها».","27:12":"فبلغت صدقيا ملك يهوذا جميع هذا الكلام وقلت: «اخضعوا لملك بابل واخدموه وشعبه فتحيوا.","27:13":"فلماذا تموت أنت وشعبك بحد السيف والجوع والوباء كما قضى الرب على الأمة التي لا تستعبد لملك بابل؟","27:14":"لا تستمعوا لكلام الأنبياء الكذبة الذين يقولون لكم: لا تستعبدوا لملك بابل لأنهم يتنبأون لكم كذبا،","27:15":"فأنا لم أرسلهم، يقول الرب، إنما هم يتنبأون باسمي كذبا لأجلكم فتطردون أنتم وأنبياؤكم المتنبئون لكم».","27:16":"وقلت للكهنة وكل الشعب: «هذا ما يعلنه الرب: لا تسمعوا لكلام أنبيائكم الكذبة الذين يتنبأون لكم قائلين إن آنية هيكل الرب سترد سريعا من بابل، فإنهم يتنبأون لكم كذبا.","27:17":"لا تصغوا لهم، بل اخدموا ملك بابل واحيوا، فلماذا تتحول هذه المدينة إلى أطلال؟","27:18":"وإن كانوا حقا أنبياء، وإن كان حقا وحي الرب لديهم فليبتهلوا إلى الرب القدير لكي لا يحمل ما تبقى من آنية هيكل الرب، وقصر ملك يهوذا، وأورشليم إلى بابل.","27:19":"فإن الرب القدير يقول عن الأعمدة، وبركة الماء والقواعد وسائر الآنية المتبقية في هذه المدينة","27:20":"مما لم يستول عليها نبوخذناصر ملك بابل عندما سبى يكنيا بن يهوياقيم ملك يهوذا من أورشليم مع جميع أشراف يهوذا وأورشليم،","27:21":"فبقيت في هيكل الرب وفي قصر الملك وفي أورشليم:","27:22":"إنها ستحمل إلى بابل وتبقى هناك إلى يوم افتقادي، يقول الرب، فأسترجعها وأردها إلى هذا الموضع».","28:1":"وفي الشهر الخامس من السنة الرابعة في مستهل حكم صدقيا ملك يهوذا، قال لي حننيا بن عزور النبي الكاذب، الذي من جبعون، في حضور الكهنة وكل الشعب المجتمعين في هيكل الرب:","28:2":"«هذا ما يعلنه الرب القدير إله إسرائيل: إني قد حطمت نير ملك بابل.","28:3":"وبعد عامين أرد إلى هذا الموضع كل آنية هيكل الرب التي استولى عليها نبوخذناصر ملك بابل من هذا المكان وحملها إلى بابل.","28:4":"وأرد إلى هذا الموضع يكنيا بن يهوياقيم ملك يهوذا، وكل سبي يهوذا الذين نفوا إلى بابل، لأني سأحطم نير ملك بابل».","28:5":"عندئذ قال إرميا النبي لحننيا المتنبيء أمام الكهنة وسائر الشعب الماثل في هيكل الرب:","28:6":"«آمين. ليحقق الرب هذا، وليتمم الرب كلامك الذي تنبأت به، ويرد آنية هيكله وكل المسبيين من بابل إلى هذا الموضع.","28:7":"لكن أصغ إلى هذه الكلمة التي أنطق بها على مسمعك وعلى مسامع الشعب كله:","28:8":"إن الأنبياء الذين كانوا قبلي وقبلك في الأزمان السالفة، تنبأوا على بلدان كثيرة وممالك عظيمة بالحروب والجوع والوباء،","28:9":"أما النبي الذي تنبأ بالسلام، فعند تحقق نبوءته يعرف أن الرب قد أرسله حقا».","28:10":"فأخذ حننيا المتنبيء الكاذب النير عن عنق إرميا النبي وحطمه،","28:11":"وقال أمام كل الشعب: «هذا ما يعلنه الرب: هكذا أحطم نير نبوخذناصر ملك بابل بعد عامين عن أعناق جميع الأمم». ثم مضى إرميا النبي في سبيله.","28:12":"وبعد أن حطم حننيا المتنبيء الكاذب النير عن عنق إرميا قال الرب لإرميا النبي:","28:13":"«اذهب وقل لحننيا: هذا ما يعلنه الرب: أنت حطمت أنيار خشب، ولكني أعددت مكانها أنيارا من حديد.","28:14":"لأن هذا ما يعلنه الرب القدير إله إسرائيل: إني قد وضعت نيرا من حديد على أعناق جميع الأمم لتستعبد لنبوخذناصر ملك بابل، فيكونون له عبيدا وقد عهدت إليه أيضا بحيوان الحقل».","28:15":"وأضاف إرميا النبي مخاطبا حننيا المتنبيء: «اسمع ياحننيا، هذا ما يعلنه الرب: إن الرب لم يبعثك، وأنت جعلت هذا الشعب يصدق كذبك.","28:16":"لذلك هكذا يعلن الرب: ها أنا أبيدك عن وجه الأرض فتموت في هذه السنة لأنك نطقت بالتمرد على الرب».","28:17":"وفي الشهر السابع من تلك السنة عينها مات حننيا.","29:1":"هذا هو نص الرسالة التي بعث بها إرميا النبي من أورشليم إلى بقية شيوخ المسبيين، وإلى الكهنة، والمتنبئين الكذبة، وسائر الشعب، ممن سباهم نبوخذناصر من أورشليم إلى بابل،","29:2":"وذلك بعد خروج يكنيا الملك والملكة والخصيان ورؤساء يهوذا والنجارين والحدادين من أورشليم.","29:3":"وحمل هذه الرسالة ألعاسة بن شافان وجمريا بن حلقيا اللذان أرسلهما صدقيا ملك يهوذا إلى نبوخذناصر ملك بابل، وقد ورد فيها:","29:4":"هذا ما يعلنه الرب القدير إله إسرائيل لكل المسبيين الذين أجليتهم من أورشليم إلى بابل.","29:5":"ابنوا بيوتا وأقيموا فيها. اغرسوا بساتين وكلوا من نتاجها.","29:6":"تزوجوا وأنجبوا بنين وبنات، واتخذوا نساء لأبنائكم وزوجوا بناتكم، وليلدن أبناء وبنات. وتكاثروا هناك، ولا تتناقصوا،","29:7":"والتمسوا سلام المدينة التي سبيتكم إليها، وصلوا من أجلها إلى الرب لأن سلامكم يتوقف على سلامها.","29:8":"لأن هذا ما يعلنه الرب القدير إله إسرائيل: لا يخدعنكم أنبياؤكم الكذبة المقيمون في وسطكم، والعرافون. لا تستمعوا إلى أحلامهم التي توهمكم بالأمل،","29:9":"لأنهم يتنبأون لكم باسمي كذبا، وأنا لم أبعثهم»، يقول الرب.","29:10":"ولكن بعد انقضاء سبعين سنة عليكم في بابل، ألتفت إليكم وأفي لكم بوعودي الصالحة بردكم إلى هذا الموضع.","29:11":"لأني عرفت ما رسمته لكم. إنها خطط سلام لا شر لأمنحكم مستقبلا ورجاء.","29:12":"فتدعونني وتقبلون، وتصلون إلي فأستجيب لكم،","29:13":"وتلتمسونني فتجدونني إذ تطلبونني بكل قلوبكم.","29:14":"وحين تجدونني أرد سبيكم، وأجمعكم من بين جميع الأمم ومن جميع الأماكن التي شتتكم إليها.","29:15":"ولأنكم قلتم: قد بعث الرب فينا أنبياء في بابل.","29:16":"يقول الرب عن الملك الجالس على عرش داود، وعن سائر الشعب المقيم في المدينة من أقربائكم الذين لم يذهبوا إلى السبي:","29:17":"ها أنا أقضي عليهم بالسيف والجوع والوباء، وأجعلهم كتين رديء تعاف النفس أكله لفرط رداءته.","29:18":"وأتعقبهم بالسيف والجوع والوباء، وأعرضهم للرعب في كل ممالك الأرض، فيصبحون لعنة ومثار دهشة وصفير وعار في جميع الأمم التي شتتهم إليها،","29:19":"لأنهم لم يطيعوا كلامي الذي أنذرتهم به منذ البدء على لسان عبيدي الأنبياء ولم يسمعوا».","29:20":"أما أنتم فاسمعوا كلمة الرب ياجميع المسبيين الذين أجليتهم عن أورشليم إلى بابل.","29:21":"يقول الرب القدير إله إسرائيل عن أخآب بن قولايا وعن صدقيا بن معسيا اللذين يتنبآن لكم باسمي زورا: «ها أنا أسلمهما ليد نبوخذناصر ملك بابل فيقتلهما على مرأى منكم،","29:22":"فيصبحان مثل لعنة بين جميع المسبيين من يهوذا في بابل، فيقال: ليجعلك الله نظير صدقيا وأخآب اللذين قلاهما ملك بابل بالنار،","29:23":"لأنهما ارتكبا الفواحش في إسرائيل وزنيا مع نساء أصحابهما وتنبآ باسمي نبوءات كاذبة لم آمرهما بها. فأنا العارف والشاهد» يقول الرب.","29:24":"وأيضا قل لشمعيا النحلامي:","29:25":"«هذا ما يعلنه الرب القدير إله إسرائيل: لقد بعثت برسائل باسمك إلى جميع الشعب المقيم في أورشليم، وإلى صفنيا بن معسيا الكاهن وإلى سائر الكهنة قائلا:","29:26":"إن الرب قد أقامك كاهنا عوض يهوياداع الكاهن لتكونوا جميعا ولاة في هيكل الرب، فتضعوا حدا لكل رجل مجنون ومتنبيء فتزج به في المقطرة والقيود.","29:27":"فما بالكم لا تزجرون إرميا العناثوثي الذي تنبأ لكم؟","29:28":"إنه قد بعث إلينا في بابل قائلا: إن حقبة السبي طويلة، فابنوا لأنفسكم بيوتا وأقيموا فيها، واغرسوا بساتين وكلوا من ثمارها».","29:29":"فقرأ صفنيا الكاهن هذه الرسالة على مسمع إرميا النبي.","29:30":"فأوحى الرب إلى إرميا بهذه الكلمة:","29:31":"«ابعث إلى جميع المسبيين قائلا: هذا ما يعلنه الرب عن شمعيا النحلامي: بما أن شمعيا قد تنبأ لكم مع أني لم أرسله وجعلكم تصدقون الكذب،","29:32":"فلذلك يقول الرب: ها أنا أعاقب شمعيا وذريته فلا يمتد العمر بأحد منهم بين هذا الشعب ليشهد الخير الذي سأجريه على شعبي، لأنه نطق بالتمرد علي».","30:1":"ثم أوحى الرب بهذه النبوءة إلى إرميا قائلا:","30:2":"هذا ما يعلنه الرب إله إسرائيل: «دون في كتاب كل ما أمليته عليك،","30:3":"ها أيام مقبلة أرد فيها سبي شعبي إسرائيل ويهوذا، وأعيدهم إلى الأرض التي أعطيتها لآبائهم فيرثونها».","30:4":"ثم خاطب الرب إسرائيل ويهوذا: بهذا الكلام:","30:5":"«هذا ما يعلنه الرب: سمعنا صراخ رعب. عم الفزع وانقرض السلام.","30:6":"اسألوا وتأملوا: أيمكن للرجل أن يحمل؟ إذا ما لي أرى كل رجل يضع يديه على حقويه كامرأة تقاسي من المخاض، وقد اكتسى كل وجه بالشحوب؟","30:7":"ما أرهب ذلك اليوم إذ لا مثيل له! هو زمن ضيق على ذرية يعقوب، ولكنها ستنجو منه.","30:8":"في ذلك اليوم، يقول الرب القدير، أحطم أنيار أعناقهم، وأقطع ربطهم، فلا يستعبدهم غريب فيما بعد.","30:9":"بل يعبدون الرب إلههم، وداود (أي المسيا) ملكهم الذي أقيمه لهم.","30:10":"فلا تفزع يا(نسل) عبدي يعقوب، ولا تجزع ياإسرائيل، فإني أخلصك من الغربة، وأنقذ ذريتك من أرض سبيهم، فيرجع نسل إسرائيل ويطمئن ويستريح من غير أن يضايقه أحد.","30:11":"لأني معك لأخلصك، يقول الرب، فأبيد جميع الأمم التي شتتك بينها. أما أنت فلن أفنيك بل أؤدبك بالحق ولا أبرئك تبرئة كاملة».","30:12":"لأن هذا ما يعلنه الرب: «إن جرحك لا شفاء له وضربتك لا علاج لها.","30:13":"إذ لا يوجد من يدافع عن دعواك، ولا عقار لجرحك، ولا دواء لك.","30:14":"قد نسيك محبوك، وأهملوك إهمالا، لأني ضربتك كما يضرب عدو، وعاقبتك عقاب مبغض قاس، لأن إثمك عظيم وخطاياك متكاثرة.","30:15":"لماذا تنوحين من ضربتك؟ إن جرحك مستعص من جراء إثمك العظيم وخطاياك المتكاثرة، لهذا أوقعت بك المحن.","30:16":"ولكن سيأتي يوم يفترس فيه جميع مفترسيك ويذهب جميع مضايقيك إلى السبي، ويصبح ناهبوك منهوبين،","30:17":"لأني أرد لك عافيتك وأبريء جراحك، يقول الرب، لأنك دعيت منبوذة، صهيون التي لا يعبأ بها أحد».","30:18":"وهذا ما يعلنه الرب: «ها أنا أرد سبي ذرية يعقوب إلى منازلهم، وأرحم مساكنهم، فتبنى المدينة على رابيتها، وينتصب القصر كالعهد به.","30:19":"وتصدر عنهم ترانيم الشكر مع أهازيج أصوات المطربين، وأكثرهم فلا يكونون قلة، وأكرمهم فلا يستذلون.","30:20":"ويكون أبناؤهم مفلحين كما في العهد الغابر، ويثبت جمهورهم أمامي، وأعاقب جميع مضايقيهم.","30:21":"ويكون قائدهم منهم، ويخرج حاكمهم من وسطهم فأستدنيه فيدنو مني، إذ من يجرؤ على الاقتراب مني من نفسه؟","30:22":"وتكونون لي شعبا وأكون لكم إلها».","30:23":"انظروا، ها عاصفة غضب الرب قد تفجرت، زوبعة هائجة تثور فوق رؤوس الأشرار.","30:24":"لن يرتد غضب الرب المحتدم حتى ينجز وينفذ مقاصد فكره. وهذا ما ستفهمونه في آخر الأيام.","31:1":"ويقول الرب: «في ذلك الوقت أكون إلها لجميع عشائر إسرائيل، وهم يكونون لي شعبا.","31:2":"قد نال الناجون من السيف نعمة في الصحراء (أي في أثناء السبي) عندما ذهبت لأريح إسرائيل».","31:3":"ظهر لي الرب قائلا: «أحببتكم حبا أبديا، لذلك اجتذبتكم إلي برحمة.","31:4":"لهذا أبنيك ياعذراء إسرائيل (أي أورشليم) فتبنين، وتتزينين ثانية بدفوفك، وتبرزين في مراقص الطربين.","31:5":"تغرسين كروما ثانية فوق جبال السامرة. يغرس الفلاحون ويجنون الثمار.","31:6":"لأنه سيأتي يوم ينادي فيه المراقبون في جبل أفرايم قائلين: هلموا فنصعد إلى صهيون إلى الرب إلهنا».","31:7":"فإن هذا ما يعلنه الرب: «رنموا بهتاف ليعقوب، اهتفوا لرأس الأمم، أعلنوا وسبحوا وقولوا: أنقذ يارب شعبك، بقية إسرائيل».","31:8":"ها أنا آتي بهم من بلاد الشمال، وأجمعهم من أقصى أطراف الأرض، وفيهم الأعمى والأعرج، الحبلى والماخض، فيرجع حشد عظيم إلى هنا.","31:9":"سيرجعون بنوح، وبتضرعات أهديهم. إلى جوار جداول المياه أسيرهم فيمشون في طريق مستقيمة لا يعثرون فيها، لأني أب لإسرائيل، وأفرايم بكري».","31:10":"«فاسمعوا كلام الرب أيها الأمم، وأذيعوا في الجزائر البعيدة، وقولوا: «الذي بدد شعب إسرائيل هو الذي يجمعه ويحافظ عليه كما يحافظ الراعي على قطيعه.","31:11":"لأن الرب افتدى إسرائيل وفكه من يد من هو أقوى منه.","31:12":"فيقبلون مرنمين بهتاف على مرتفعات صهيون، ويبتهجون بخيرات الرب من حنطة وخمر جديد وزيت وحملان وعجول، وتكون نفوسهم كجنة مروية، ولا يعتريهم حزن بعد.","31:13":"حينئذ تبتهج العذارى بالرقص، ويطر ب الشيوخ والشبان على حد سواء. أحول نوحهم إلى سرور وأستبدل حزنهم بالفرح والطمأنينة.","31:14":"وأشبع نفوس الكهنة من الخيرات، ويمتليء شعبي من نعمتي».","31:15":"وهذا ما يعلنه الرب: «قد تردد في الرامة صوت ندب وبكاء مر. راحيل تنوح على أبنائها وتأبى أن تتعزى عنهم لأنهم غير موجودين».","31:16":"وهذا ما يعلنه الرب: «كفي صوتك عن البكاء وعينيك عن العبرات لأن لعملك ثوابا»، يقول الرب، «إذ لابد أن يرجع أولادك من أرض العدو.","31:17":"فلغدك رجاء»، يقول الرب، «إذ سيرجع أولادك إلى موطنهم.","31:18":"قد سمعت أفرايم ينتحب قائلا: أدبتني فتأدبت كعجل غير مروض. أرجعني فأرجع لأنك أنت الرب إلهي.","31:19":"فقد تبت بعد أن غويت، وبعد أن تعلمت صفقت على فخذي ندما. خجلت وخزيت لأني حملت عار حداثتي.","31:20":"هل أفرايم ابن أثير لدي؟ أليس هو ابنا مسرا؟ لأني مع كثرة تنديدي به فإني مازلت أذكره، لذلك يشتاق قلبي إليه، وأكن له الرحمة»، يقول الرب.","31:21":"«انصبي لنفسك معالم. أقيمي لنفسك أنصابا. تأملي في الطريق الرئيسية، في السبيل الذي سلكته. ارجعي ياعذراء صهيون. ارجعي إلى مدنك هذه.","31:22":"إلى متى تظلين هائمة على وجهك أيتها الابنة الغادرة؟ قد خلق الرب شيئا جديدا في الأرض: أنثى تحمي رجلا».","31:23":"وهذا ما يعلنه الرب القدير إله إسرائيل: «سيرددون هذه العبارة مرة أخرى في أرض يهوذا وفي أرجاء مدنها، عندما أردهم من سبيهم: ليباركك الرب يامسكن البر، ياأيها الجبل المقدس.","31:24":"فيقيم هناك يهوذا وكل أهل مدنه والفلاحون والسارحون بقطعانهم.","31:25":"لأني سأنعش النفس المعيية، وأشبع النفوس الواهنة».","31:26":"وآنئذ استيقظت وتأملت، وطاب لي نومي.","31:27":"«ها أيام مقبلة»، يقول الرب، «أكثر فيها ذرية إسرائيل ويهوذا، وأضاعف نتاج بهائمهم أضعافا.","31:28":"وكما تربصت بهم لأستأصل وأهدم وأنقض وأهلك وأسيء، كذلك أسهر عليكم لأبنيكم وأغرسكم»، يقول الرب.","31:29":"«وفي تلك الأيام لن يقول أحد: قد أكل الآباء الحصرم فضرست أسنان الأبناء».","31:30":"بل كل واحد يموت بإثمه، ومن يأكل حصرما تضرس أسنانه.","31:31":"«ها أيام مقبلة»، يقول الرب أقطع فيها عهدا جديدا مع ذرية إسرائيل ويهوذا،","31:32":"لا كالعهد الذي أبرمته مع آبائهم، يوم أخذتهم بيدهم لأخرجهم من ديار مصر، فنقضوا عهدي، لذلك أهملتهم.","31:33":"ولكن هذا هو العهد الذي أبرمه مع ذرية إسرائيل بعد تلك الأيام»، يقول الرب: «سأجعل شريعتي في دواخلهم، وأدونها على قلوبهم وأكون لهم إلها وهم يكونون لي شعبا.","31:34":"ولا يحض في ما بعد كل واحد قريبه قائلا: اعرف الرب إلهك لأنهم جميعا سيعرفونني، من صغيرهم إلى كبيرهم، لأني سأصفح عن إثمهم ولن أذكر خطاياهم من بعد».","31:35":"وهذا ما يعلنه الرب الذي جعل الشمس للإضاءة في النهار، وحكم على القمر والكواكب للإنارة ليلا، الذي يثير البحر فتصخب أمواجه، واسمه الرب القدير.","31:36":"«إن كانت هذه الأحكام تزول من أمامي فإن ذرية إسرائيل تكف عن أن تكون لي أمة».","31:37":"وهذا ما يعلنه الرب: «إن أمكن قياس السماوات من فوق، والتنقيب عن أسس الأرض من تحت، عندئذ أنبذ ذرية إسرائيل بسبب كل ما ارتكبوه».","31:38":"«ها أيام مقبلة يعاد فيها بناء هذه المدينة للرب من برج حننئيل إلى باب الزاوية.","31:39":"ويمتد خط القياس من هناك إلى أكمة جارب ويلتف إلى جوعة.","31:40":"ويصبح كل وادي الجثث والرماد، وسائر الحقول إلى وادي قدرون حتى زاوية باب الخيل شرقا قدسا للرب، ولن تستأصل أو تهدم إلى الأبد».","32:1":"هذه هي النبوءة التي أوحى بها الرب إلى إرميا في السنة العاشرة من حكم صدقيا ملك يهوذا، الموافقة للسنة الثامنة عشرة لملك نبوخذناصر.","32:2":"وكان جيش ملك بابل آنئذ يحاصر أورشليم، وإرميا النبي معتقلا في دار السجن في قصر ملك يهوذا،","32:3":"لأن صدقيا الملك اعتقله قائلا: «لماذا تتنبأ مناديا أن هذا ما يعلنه الرب: ها أنا أسلم هذه المدينة إلى يد ملك بابل فيستولي عليها؟","32:4":"وكذلك لن يفلت صدقيا ملك يهوذا من يد الكلدانيين، بل يقبض عليه ويمثل أمام ملك بابل فيخاطبه وجها لوجه وعيناه تنظر ان عينيه","32:5":"ويسبى صدقيا إلى بابل ويمكث هناك إلى أن يموت، يقول الرب. وإن حاربتم الكلدانيين فإنكم لا تنجحون».","32:6":"فأجاب إرميا: «قد أعلن لي الرب قضاءه قائلا:","32:7":"ها حنمئيل ابن عمك شلوم قادم إليك قائلا: اشتر حقلي الذي في عناثوث لأن لك حق الفكاك عن طريق الشراء.","32:8":"وما لبث أن جاء حنمئيل ابن عمي إلي في دار السجن بمقتضى كلمة الرب وقال لي: اشتر حقلي الذي في عناثوث في أرض بنيامين، لأن لك حق الإرث والفكاك. حينئذ أدركت أن تلك كانت كلمة الله.","32:9":"فاشتريت الحقل الذي في عناثوث من حنمئيل ابن عمي، ووزنت له سبعة عشر شاقلا (حوالي مئتي جرام) من الفضة.","32:10":"ثم سجلت عقد البيع في صك وختمته، وأشهدت شهودا، ووزنت الفضة بميزان.","32:11":"وأخذت صك البيع المختوم المتضمن بنود العقد مع نسخة غير مختومة،","32:12":"وأودعت صك البيع عند باروخ بن نيريا بن محسيا بمحضر حنمئيل ابن عمي والشهود الذين وقعوا على صك البيع، وأمام جميع اليهود الجالسين في دار السجن.","32:13":"وأوصيت باروخ أمامهم قائلا:","32:14":"هذا ما يعلنه الرب القدير إله إسرائيل: خذ هذين الصكين: صك البيع المختوم، والصك غير المختوم، واحفظهما في إناء خزفي لمدة طويلة،","32:15":"لأن الرب القدير إله إسرائيل يقول: إن بيوتا وحقولا وكروما ستشترى بعد في هذه الأرض».","32:16":"وبعد أن أودعت الصك باروخ بن نيريا صليت إلى الرب قائلا:","32:17":"آه أيها السيد الرب، إنك أنت الذي صنعت السماوات والأرض بقوتك العظيمة وذراعك الممدودة ولا يتعذر عليك أمر.","32:18":"أنت الذي تبدي إحسانك لألوف، وتعاقب ذنب الآباء في الأبناء من بعدهم. أنت هو الإله العظيم القدير اسمه.","32:19":"عظيم في المشورة وقادر في العمل، وعيناك مفتوحتان تراقبان جميع طرق الإنسان لتجازي كل واحد حسب تصرفاته وثمار أعماله.","32:20":"وقد أجريت آيات ومعجزات في ديار مصر، ومازلت تجريها إلى هذا اليوم في شعب إسرائيل وبين سائر البشر، وجعلت اسمك يطبق الآفاق كما هو جار في هذا اليوم،","32:21":"وأخرجت شعبك إسرائيل من ديار مصر بآيات ومعجزات، وبيد قديرة وذراع ممدودة، وما ألقيته من خوف شديد في قلوب أهلها،","32:22":"ووهبت الشعب هذه الأرض التي أقسمت لآبائهم أن تهبها لهم، أرضا تفيض لبنا وعسلا،","32:23":"فدخلوا وورثوها. ولكنهم لم يطيعوا صوتك ولم يسلكوا وفق شريعتك ولم يفعلوا ما أمرتهم به، لذلك أوقعت بهم هذا الشر كله.","32:24":"انظر، ها المتاريس قد أقيمت حول المدينة لِلاستيلاء عليها، ومن جراء السيف والجوع والوباء أصبحت المدينة في يد الذين يحاربونها من الكلدانيين. فكل ما نطقت به قد تم، وها أنت على ذلك شاهد.","32:25":"وقد قلت لي أيها السيد الرب: اشتر الحقل بفضة، وأشهد شهودا مع أن المدينة قد سقطت في يد الكلدانيين».","32:26":"ثم كلم الرب إرميا:","32:27":"«انظر، أنا الرب إله كل بشر. هل يتعذر علي أمر؟","32:28":"لذلك ها أنا أسلم هذه المدينة إلى يد الكلدانيين وإلى يد نبوخذناصر ملك بابل، فيستولي عليها.","32:29":"ويقتحمها الكلدانيون الذين يحاربون هذه المدينة، ويضرمون فيها النار ويحرقونها هي وبيوتها التي أصعدوا على سطوحها بخورا وسكائب خمر للبعل ولآلهة الأوثان، ليثيروا سخطي.","32:30":"إن أبناء إسرائيل وأبناء يهوذا جدوا في ارتكاب الشر أمامي منذ حداثتهم، فأثاروا سخطي بما جنته أيديهم.","32:31":"قد أججت هذه المدينة، منذ بنائها إلى هذا اليوم، غضبي وغيظي، ودفعتني حتى أمحوها من أمام وجهي،","32:32":"لفرط شر أبناء إسرائيل وأبناء يهوذا الذي ارتكبوه، فأثاروا سخطي هم وملوكهم ورؤساؤهم وكهنتهم وأنبياؤهم الكذبة ورجال يهوذا وأهل أورشليم.","32:33":"وأولوني ظهورهم وليس وجوههم. ومع أني علمتهم منذ البدء مرة تلو الأخرى، إلا أنهم لم يسمعوا ليقبلوا تأديبي.","32:34":"ونصبوا أوثانهم الرجسة في الهيكل الذي دعي اسمي عليه لينجسوه.","32:35":"وبنوا المرتفعات للبعل في وادي ابن هنوم ليجيزوا في النار أبناءهم وبناتهم لمولك، وهو ما لم آمرهم به، ولم يخطر لي ببال أن يرتكبوا هذا الرجس ويجعلوا شعب يهوذا يقترف الإثم.","32:36":"لذلك هذا ما يعلنه الرب إله إسرائيل الآن عن هذه المدينة التي تقولون عنها إنها سلمت إلى يد ملك بابل بالسيف والجوع والوباء.","32:37":"ها أنا أعود فأجمعهم من جميع البلدان التي شتتهم إليها في غضبي وغيظي وسخطي الشديد، وأردهم إلى هذا الموضع وأسكنهم آمنين،","32:38":"فيكونون لي شعبا وأكون لهم إلها.","32:39":"وأعطيهم قلبا واحدا وطريقا واحدا ليتقوني كل الأيام، وذلك لخيرهم وخير أولادهم من بعدهم.","32:40":"وأبرم معهم عهدا أبديا أن لا أكف عن الإحسان إليهم، وأضع تقواي في قلوبهم لئلا يرتدوا عني،","32:41":"وأسر بالإحسان إليهم، وأغرسهم في هذه الأرض بالحق من كل قلبي ونفسي.","32:42":"وكما أوقعت بهذا الشعب كل هذا الشر العظيم، كذلك أمتعهم بجميع الخيرات التي وعدتهم بها.","32:43":"فتشترى الحقول في هذه الأرض التي تدعون أنها خربة هجرها الإنسان والحيوان، وقد استولى عليها الكلدانيون.","32:44":"فتشترى الحقول بفضة، وتسجل بنود العقود في الصكوك وتختم، ويوقع الشهود في أرض بنيامين والقرى المجاورة لأورشليم، وفي مدن يهوذا وفي المناطق الجبلية وفي مدن السهل، ومدن الجنوب لأني أرد سبيهم، يقول الرب».","33:1":"وأوحى الرب ثانية بهذه النبوءة إلى إرميا، وهو ما زال معتقلا في دار السجن قائلا:","33:2":"«هذا ما يعلنه الرب صانع الأرض، الرب الذي صورها وثبتها، يهوه اسمه","33:3":"ادعني فأجيبك وأطلعك على عظائم وغرائب لم تعرفها.","33:4":"لأن هذا ما يعلنه الرب إله إسرائيل عن بيوت هذه المدينة وعن قصور ملوك يهوذا التي تم هدمها، ليقام منها سور دفاع ضد متاريس الحصار والمجانيق.","33:5":"في القتال الناشب مع الكلدانيين الذين سيملأون المدن بجثث القتلى الذين ضربتهم في احتدام غضبي وغيظي، لأني قد حجبت وجهي عن هذه المدينة لشرهم.","33:6":"ولكن لا ألبث أن أرد لها العافية والشفاء. أبرئهم وأبدي لهم وفرة السلام والأمن.","33:7":"وأرد سبي يهوذا وإسرائيل، وأبنيهم كما في العهد السابق.","33:8":"وأطهرهم من كل إثمهم الذي اقترفوه في حقي، وأصفح عن ذنوبهم التي أخطأوا بها إلي، وعن جميع تعدياتهم علي.","33:9":"وتصبح هذه المدينة مبعث سرور لي، وتسبحة وافتخارا لدى جميع أمم الأرض التي يبلغها كل ما أسديته من خير إليها، فتخاف وترتعد بفضل ما أغدقته عليها من إحسان وازدهار.","33:10":"وهذا ما يعلنه الرب: في هذا الموضع الذي تقولون عنه إنه خراب هجره الإنسان والحيوان، وفي مدن يهوذا وشوارع أورشليم الموحشة المقفرة من الناس، والتي لا يقيم فيها حيوان، ستتردد فيها ثانية","33:11":"أصوات الطرب والسرور، وهتاف العريس والعروس، وأصوات المقبلين إلى هيكل الرب بقرابين الشكر القائلين: احمدوا الرب القدير، لأن الرب صالح ورحمته إلى الأبد تدوم، لأني أرد سبي الأرض فتصبح آهلة كالأيام الخوالي.","33:12":"في هذا الموضع الخرب المقفر من الإنسان والحيوان، وفي جميع مدنه، ستكون مساكن للرعاة يربضون فيها قطعانهم.","33:13":"وفي مدن المناطق الجبلية ومدن السفوح القريبة، ومدن النقب، وفي أرض بنيامين وفي القرى المجاورة لأورشليم، وفي مدن يهوذا تمر الغنم أمام المحصي.","33:14":"«ها أيام مقبلة»، يقول الرب، «أتمم فيها الوعد الذي تعهدت به لذرية يهوذا ولذرية إسرائيل.","33:15":"في تلك الأيام أنبت من نسل داود غصن بر يجري عدلا وبرا في الأرض.","33:16":"في تلك الأيام يخلص يهوذا، وتسكن أورشليم آمنة، وهذا هو الاسم الذي تدعى به: الرب برنا.","33:17":"لأن هذا ما يعلنه الرب: لن ينقرض من نسل داود رجل يجلس على عرش بيت إسرائيل.","33:18":"ولن ينقرض من أمامي رجل من الكهنة واللاويين يصعد محرقة، ويقدم تقدمة حنطة، ويقرب ذبيحة مدى الدهر».","33:19":"ثم أوحى الرب إلى إرميا بهذه النبوءة:","33:20":"«هذا ما يقوله الرب: إن استطعتم أن تنقضوا عهدي مع النهار، ومع الليل، بحيث لا يحل النهار والليل في أوانهما،","33:21":"يمكن أن تنقضوا عهدي مع عبدي داود، فلا يكون من ذريته ابن يملك على عرشه، ومع الكهنة واللاويين خدامي.","33:22":"وأكثر ذرية داود عبدي وذر اري اللاويين خدامي، وأجعلها في كثرة نجوم السماء التي لا تحصى، وكرمل البحر الذي لا يعد».","33:23":"ثم أوحى الرب إلى إرميا بهذه النبوءة.","33:24":"«ألم تسمع ما قاله ذلك الشعب: قد نبذ الرب العشيرتين اللتين اختارهما؟ كذلك احتقروا شعبي وكأنهم لم يعودوا أمة.","33:25":"وهذا ما يعلنه الرب: إن كنت لم أعقد ميثاقا مع النهار والليل، ولم أسن أحكاما للسماوات والأرض،","33:26":"فإني أرفض ذرية يعقوب وداود عبدي، فلا أصطفي من ذريته من يحكم على نسل إبراهيم وإسحق ويعقوب. ولكني سأرد سبيهم وأرحمهم».","34:1":"هذه هي النبوءة التي أوحى بها الرب إلى إرميا، عندما كان نبوخذناصر وجميع جيشه وسائر قوات ممالك الأرض الخاضعة له، وكل الشعوب يحاربون أورشليم ومدنها.","34:2":"«هذا ما يعلنه الرب إله إسرائيل: اذهب وخاطب صدقيا ملك يهوذا وقل له: هذا ما يعلنه الرب: ها أنا أسلم هذه المدينة إلى يد ملك بابل فيحرقها بالنار.","34:3":"وأنت لن تفلت من قبضته، بل تؤسر وتسلم إليه، فترى ملك بابل وجها لوجه، وتكلمه فما لفم، وتقاد إلى بابل.","34:4":"فاسمع كلمة الرب ياصدقيا ملك يهوذا، فهذا ما يعلنه الرب عنك: لن تموت قتلا بالسيف،","34:5":"بل تموت بسلام. وكما كانت حرائق الدفن تقام لآبائك السالفين، كذلك يقيمون الحرائق لك ويندبونك نائحين: وا سيداه. لأني أنا قضيت، يقول الرب».","34:6":"فخاطب إرميا النبي صدقيا ملك يهوذا بكل هذا الكلام في أورشليم،","34:7":"بينما كان جيش ملك بابل يحارب أورشليم وما تبقى من مدن يهوذا: لخيش وعزيقة، لأن هاتين المدينتين هما كل ما تبقى من مدن يهوذا الحصينة.","34:8":"وهذه هي النبوءة التي أوحى بها الرب إلى إرميا النبي، بعدما أبرم عهدا مع أهل أورشليم كلهم لإعلان العتق","34:9":"يعتق كل واحد عبده وأمته، العبراني والعبرانية فلا يستعبد أحد يهوديا من إخوته.","34:10":"فاستجاب جميع الرؤساء وسائر الشعب الذين دخلوا في العهد الذي ينص على تحرير كل واحد عبده وأمته، فلا يستعبدهما من بعد. وأطاعوا العهد وأعتقوا.","34:11":"ولكنهم ما لبثوا أن استردوا العبيد والإماء الذين أعتقوهم، واستعبدوهم من جديد.","34:12":"فأوحى الرب بهذه النبوءة إلى إرميا:","34:13":"«هذا ما يعلنه الرب إله إسرائيل: إني عقدت ميثاقا مع آبائكم حين أخرجتهم من ديار مصر من أرض العبودية قائلا:","34:14":"ليطلق كل واحد منكم في ختام سبع سنين أخاه العبراني الذي باع نفسه لك، وخدمك ست سنوات، ليكون حرا. فلم يطعني آباؤكم ولم يسمعوا لي.","34:15":"وها أنتم اليوم تبتم، وصنعتم ما هو قويم في عيني، داعين كل واحد لتحرير قريبه، وقطعتم عهدا أمامي في الهيكل الذي دعي باسمي.","34:16":"ثم ما لبثتم أن عدتم فنجستم اسمي، واسترد كل واحد منكم عبده وأمته الذين أعتقتموهم أحرارا، بمقتضى رغبتهم، ثم استعبدتموهم من جديد».","34:17":"لذلك يقول الرب: «لأنكم لم تطيعوني ولم تنادوا بعتق إخوتكم، لذلك سأنادي أنا بعتقكم فأطلقكم لتسقطوا بحد السيف والوباء والجوع، وأجعلكم عرضة للرعب في جميع ممالك الأرض،","34:18":"وأسلم الناس الذين تعدوا على عهدي ولم ينفذوا بنود ميثاقي الذي قطعوه أمامي (عندما) شقوا العجل إلى شطرين واجتازوا بينهما،","34:19":"من رؤساء يهوذا ومن رؤساء أورشليم والخصيان والكهنة وشعب الأرض جميعه، الذين اجتازوا بين شطري العجل،","34:20":"إلى يد أعدائهم وطالبي نفوسهم، فتصبح جثثهم مأكلا لجوارح السماء ولوحوش الأرض.","34:21":"وأدفع صدقيا ملك يهوذا ورؤساءه إلى يد أعدائهم وطالبي نفوسهم، وإلى يد جيش ملك بابل الذين انسحبوا من محاصرتكم.","34:22":"ها أنا آمرهم، يقول الرب، فيرجعون لمحاربة هذه المدينة ويستولون عليها ويحرقونها بالنار، وأجعل مدن يهوذا أطلالا خاوية».","35:1":"هذه هي النبوءة التي أوحى بها الرب إلى إرميا، في عهد يهوياقيم بن يوشيا ملك يهوذا.","35:2":"«امض إلى بيت الركابيين وخاطبهم، ثم أدخلهم إلى هيكل الرب إلى إحدى الحجرات الداخلية، واسقهم خمرا».","35:3":"فأخذت يازنيا بن إرميا بن حبصينيا وإخوته وجميع أبنائه وكل أفراد بيت الركابيين،","35:4":"ودخلت بهم إلى هيكل الرب إلى مخدع بني حانان بن يجدليا رجل الله القائم إلى جوار مخدع الرؤساء، الذي فوق مخدع معسيا بن شلوم حارس باب الهيكل،","35:5":"ثم وضعت أمام الركابيين جرارا ملآنة بالخمر وكؤوسا، وقلت لهم: «اشربوا خمرا».","35:6":"فأجابوا: «نحن لا نشرب خمرا، لأن يوناداب بن ركاب أبانا أوصانا: لا تشربوا خمرا أنتم ولا أبناؤكم إلى الأبد.","35:7":"ولا تشيدوا بيتا، ولا تزرعوا زرعا، ولا تغرسوا كروما، ولا تمتلكوا واحدا منها، بل أقيموا في خيام طوال حياتكم، فتطول أيامكم على وجه الأرض التي أنتم فيها متغربون.","35:8":"فأطعنا وصية يوناداب أبينا في كل ما أمرنا به، فلم نشر ب خمرا طوال حياتنا نحن ونساؤنا وأبناؤنا وبناتنا،","35:9":"ولم نشيد بيوتا نقيم فيها، ولم نملك كرما أو حقلا أو زرعا،","35:10":"إنما سكنا في خيام. لقد أطعنا وعملنا بكل ما أوصانا به أبونا يوناداب.","35:11":"فلما زحف نبوخذناصر على البلاد قلنا: تعالوا لنلجأ إلى أورشليم هربا من جيش الكلدانيين والأراميين، وهكذا أقمنا في أورشليم».","35:12":"فأوحى الرب بهذه النبوءة إلى إرميا:","35:13":"«هذا ما يعلنه الرب القدير إله إسر ائيل: انطلق وقل لرجال يهوذا ولأهل أورشليم: ألا تقبلون تأديبا فتسمعوا كلامي؟","35:14":"ها وصية يوناداب بن ركاب التي أوصى بها أبناءه قائلا لا تشربوا خمرا، قد نفذوها، فلم يشربوا خمرا إلى هذا اليوم، لأنهم أطاعوا أمر أبيهم. أما أنا فقد أنذرتكم منذ البدء فلم تسمعوا لي،","35:15":"وبعثت إليكم جميع عبيدي الأنبياء، الواحد تلو الآخر قائلا: «ليرجع كل واحد عن طريقه الشرير، وقوموا أعمالكم، ولا تضلوا وراء آلهة أخرى لتعبدوها، فتستوطنوا الأرض التي وهبتها لكم ولآبائكم»، فلم تسمعوا ولم تطيعوني.","35:16":"لقد نفذ أبناء يوناداب بن ركاب وصية أبيهم التي أمرهم بها، أما هذا الشعب فلم يسمع لي.","35:17":"لذلك هكذا يقول الرب القدير إله إسرائيل: سأوقع على شعب يهوذا وعلى جميع أهل أورشليم كل ما قضيت به عليهم من عقاب، لأني أنذرتهم فلم يسمعوا، ودعوتهم فلم يجيبوا».","35:18":"وقال إرميا لبيت الركابيين: «هذا ما يعلنه الرب القدير إله إسرائيل: بما أنكم أطعتم وصية أبيكم يوناداب ونفذتم جميع أوامره وعملتم بها،","35:19":"لذلك هكذا يقول الرب القدير إله إسرائيل: لا ينقرض من ذرية يوناداب بن ركاب رجل يمثل أمامي كل الأيام».","36:1":"وفي السنة الرابعة من حكم يهوياقيم بن يوشيا ملك يهوذا، أوحى الرب بهذه النبوءة إلى إرميا:","36:2":"«خذ لك درج كتاب ودون فيه كل الكلام الذي أمليته عليك عن إسرائيل، ويهوذا وعن جميع الأمم، منذ اليوم الذي أوحيت فيه إليك في عهد يوشيا إلى الآن.","36:3":"لعل شعب يهوذا يسمعون عن جميع الشر الذي عزمت أن أوقعه بهم، فيتوب كل واحد عن غيه، فأعفو عن إثمهم وخطيئتهم».","36:4":"فاستدعى إرميا باروخ بن نيريا، فدون باروخ عن فم إرميا في درج كتاب جميع وحي الرب الذي أوحى إليه به.","36:5":"ثم قال إرميا لباروخ: «إني معتقل لا أستطيع الدخول إلى هيكل الرب،","36:6":"فادخل أنت واتل من الدرج الذي دونته عن فمي إنذار ات الرب على مسامع الشعب في هيكل الرب في يوم الصوم. كذلك اقرأه في مسامع شعب يهوذا القادمين من مدنهم.","36:7":"لعل تضرعهم يرتفع أمام الرب، فيرجع كل واحد منهم عن غوايته لأن غضب الرب وسخطه الذين قضى بهما على هذا الشعب هائلان».","36:8":"ففعل باروخ بن نيريا حسب كل ما أوصاه به إرميا، وقرأ في الكتاب كلام الرب في هيكل الرب.","36:9":"وفي الشهر التاسع من السنة الخامسة لحكم يهوياقيم بن يوشيا ملك يهوذا، تنادى كل أهل أورشليم وكل الشعب القادم من مدن يهوذا إلى أورشليم للصوم أمام الرب.","36:10":"فتلا باروخ في هيكل الرب على مسامع الشعب من الكتاب كلام إرميا، في مخدع جمريا بن شافان الكاتب في الدار العليا عند المدخل الجديد لباب هيكل الرب.","36:11":"فلما سمع ميخايا بن جمريا بن شافان كل كلام الرب المدون في الكتاب،","36:12":"نزل إلى قصر الملك إلى قاعة الاجتماع حيث كان الرؤساء كلهم مجتمعين: أليشاماع الكاتب، ودلايا بن شمعيا، وألناثان بن عكبور، وجمريا بن شافان، وصدقيا بن حننيا، وسائر الرؤساء.","36:13":"فأبلغهم ميخايا بكل الكلام الذي سمعه عندما قرأ باروخ الكتاب في مسامع الشعب.","36:14":"فبعث جميع الرؤساء إلى باروخ يهودي بن نثنيا بن شلميا بن كوشي قائلين: «أحضر الكتاب الذي قرأت منه على مسامع الشعب وتعال». فأخذ باروخ بن نيريا الكتاب بيده وأقبل إليهم.","36:15":"فقالوا له: «اجلس واقرأ ما في الكتاب على مسامعنا.» فقرأه باروخ عليهم.","36:16":"ولما سمعوا هذا الكلام، التفت بعضهم نحو بعض مذعورين، وقالوا لباروخ: «لابد أن ننبيء الملك بكل هذا الكلام».","36:17":"ثم سألوا باروخ: «أخبرنا كيف دونت هذا الكلام عن فمه؟»","36:18":"فأجابهم باروخ: «كان يملي علي جميع هذه الأقوال فأدونها بمداد في هذا الكتاب».","36:19":"فقال الرؤساء لباروخ: «اذهب اختف عن الأنظار أنت وإرميا في مكان لا يعرفه أحد».","36:20":"ومثلوا أمام الملك في القاعة، بعد أن أودعوا الكتاب في مخدع أليشاماع، وسردوا على الملك جميع كلام الوحي.","36:21":"فبعث الملك يهودي ليأتي بالكتاب، فأحضره من مخدع أليشاماع الكاتب، ثم أخذ في تلاوته على مسامع الملك وسائر الرؤساء الماثلين لديه.","36:22":"وكان ذلك في الشهر التاسع، والملك آنذاك جالس في حجر ته الشتوية يستدفيء على نار كانون متأجج أمامه.","36:23":"فبعد أن قرأ يهودي ثلاثة أو أربعة أقسام منه، تناول الملك مبراة الكاتب وشق الكتاب وطرحه إلى نار الكانون فاحترق الكتاب بكامله.","36:24":"ولم يخف الملك ولا أحد من خدامه الذين سمعوا هذا الكلام، ولم يمزقوا ثيابهم.","36:25":"وتضرع ألناثان ودلايا وجمريا إلى الملك كي لا يحرق الكتاب فلم يستجب لهم.","36:26":"ثم أمر الملك يرحمئيل بن الملك، وسرايا بن عزرئيل، وشلميا بن عبدئيل أن يقبضوا على باروخ الكاتب وإرميا النبي، ولكن الرب حجبهما عنهم.","36:27":"وأوحى الرب إلى إرميا بعد أن أحرق الملك الكتاب وما دونه باروخ من كلام عن لسان إرميا قائلا:","36:28":"«خذ كتابا آخر ودون فيه ما ورد من كلام في الكتاب الأول الذي أحرقه يهوياقيم ملك يهوذا.","36:29":"وقل فيه عن يهوياقيم ملك يهوذا: هذا ما يعلنه الرب: إنك قد أحرقت هذا الكتاب قائلا: لماذا دونت فيه أن ملك بابل سيزحف على هذه الأرض ويدمرها ويقضي على ما فيها من إنسان وحيوان؟","36:30":"لذلك هكذا يعلن الرب عن يهوياقيم ملك يهوذا: إنه لن يخلفه من ذريته من يجلس على عرش داود، وتطرح جثته خارجا لتكون عرضة للحر في النهار والبرد في الليل.","36:31":"وأعاقبه وأعاقب ذريته وعبيده لإثمهم، وأوقع بهم وبجميع أهل أورشليم وبرجال يهوذا جميع ما قضيت به من شر عليهم إذ لم يسمعوا».","36:32":"فأخذ إرميا كتابا آخر وناوله لباروخ بن نيريا فدون فيه عن لسان إرميا كل ما ورد في الكتاب الذي أحرقه يهوياقيم ملك يهوذا بالنار من كلام، وأضاف إليه أيضا عبارات كثيرة مماثلة.","37:1":"وحكم الملك صدقيا بن يوشيا مكان كنياهو بن يهوياقيم، لأن نبوخذناصر ملك بابل ولاه على أرض يهوذا.","37:2":"ولم يطع هو ولا عبيده ولا سكان البلاد كلام الرب، الذي نطق به على لسان إرميا النبي.","37:3":"وبعث الملك صدقيا يهوخل بن شلميا، وصفنيا بن معسيا الكاهن إلى إرميا النبي قائلا: «تضرع إلى الرب إلهنا من أجلنا»،","37:4":"وكان إرميا في ذلك الوقت طليقا يتجول بين الشعب، إذ لم يكن قد اعتقل بعد في السجن.","37:5":"وزحف جيش فرعون من مصر، فبلغ خبرهم الكلدانيين الذين يحاصرون أورشليم، ففكوا عنها الحصار.","37:6":"فأوحى الرب بهذه النبوءة إلى إرميا قائلا:","37:7":"«هذا ما يعلنه الرب إله إسرائيل: هذا ما تبلغونه لملك يهوذا الذي بعثكم إلي لتستشيروني: إن جيش فرعون الزاحف لإغاثتكم على وشك العودة إلى أرضه، مصر.","37:8":"فيعود الكلدانيون ويحاربون هذه المدينة ويستولون عليها ويحرقونها بالنار.","37:9":"لذلك يقول الرب لا تخدعوا أنفسكم قائلين: سينسحب عنا الكلدانيون، فإنهم لا ينسحبون.","37:10":"وحتى لو قضيتم على محاربيكم من جيش الكلدانيين بأسره، ولم يبق منهم سوى الجرحى القابعين في خيامهم، فإنهم سيهبون ويحرقون هذه المدينة بالنار».","37:11":"ولما فك جيش الكلدانيين الحصار عن أورشليم لمواجهة زحف جيش فرعون،","37:12":"غادر إرميا أورشليم لينطلق إلى أرض بنيامين ليحصل على نصيبه الذي اشتراه هناك بين الشعب.","37:13":"فلما بلغ بوابة بنيامين قبض عليه رئيس الحراس واسمه يرئيا بن شلميا بن حننيا قائلا لإرميا النبي: «أنت هارب للانضمام إلى الكلدانيين».","37:14":"فأجابه إرميا: «هذا كذب، أنا لست هاربا للانضمام إلى الكلدانيين». فلم يصغ إليه يرئيا بل اعتقله وأتى به إلى الرؤساء.","37:15":"فثار غضب الرؤساء على إرميا وضربوه، وزجوه في بيت يوناثان الكاتب الذي حولوه إلى سجن.","37:16":"فعندما دخل إرميا إلى زنزانات الجب مكث هناك أياما كثيرة.","37:17":"ثم استدعاه الملك صدقيا، وسأله في قصره سرا: «هل عندك كلمة وحي من عند الرب؟» فأجابه إرميا: «نعم». ثم أضاف: «إنك ستسلم إلى يد ملك بابل».","37:18":"ثم قال إرميا للملك صدقيا: «بماذا أسأت إليك وإلى رجالك وإلى هذا الشعب حتى زججتم بي في السجن؟","37:19":"وأين أنبياؤكم الذين تنبأوا لكم قائلين: إن ملك بابل لن يزحف عليكم وعلى هذه الأرض؟","37:20":"والآن اسمع ياسيدي الملك، وليحظ توسلي بقبولك، لا ترجعني إلى بيت يوناثان الكاتب لئلا أموت».","37:21":"فأصدر الملك صدقيا أمره بايداع إرميا دار الحرس وأن يقدم له رغيف من الخبز كل يوم من سوق الخبازين إلى أن ينفد الخبز كله من المدينة. وهكذا مكث إرميا في دار الحرس.","38:1":"وبلغ مسامع شفطيا بن متان، وجدليا بن فشحور، ويوخل بن شلميا، وفشحور بن ملكيا، الكلام الذي كان إرميا يخاطب به كل الشعب قائلا:","38:2":"«هذا ما يعلنه الرب: إن كل من يمكث في هذه المدينة يموت بحد السيف وبالجوع والوباء. أما من يلجأ إلى الكلدانيين فإنه ينجو بنفسه ويفلت بحياته ويحيا.","38:3":"ستسلم هذه المدينة حتما إلى يد جيش ملك بابل فيستولي عليها».","38:4":"فقال رؤساء البلاد للملك: «يجب إعدام هذا الرجل، لأنه يثبط عزيمة المحاربين الباقين في هذه المدينة وعزيمة سائر الشعب، لأنه يخاطبهم بمثل هذا الكلام. فهذا الرجل لا يلتمس لهذا الشعب خيرا بل شرا».","38:5":"فأجاب الملك صدقيا: «ها هو بين أيديكم. افعلوا به ما تشاؤون، لأن الملك لا يستطيع أن يعارضكم».","38:6":"فأخذوا إرميا وطرحوه في جب ملكيا ابن الملك القائم في دار الحرس. ودلوا إرميا بحبال، ولم يكن في الجب ماء بل وحل، فغاص فيه إرميا.","38:7":"فلما سمع عبد ملك الخصي الإثيوبي المقيم في قصر الملك أنهم ألقوا بإرميا في الجب، وكان الملك آنئذ جالسا في بوابة بنيامين،","38:8":"غادر عبد ملك القصر، وقال للملك:","38:9":"«يامولاي الملك، قد أساء هؤلاء الرجال إلى إرميا النبي بما أوقعوه به من شر حين زجوه في الجب. فإنه لابد أن يتعرض للموت من جراء الجوع، إذ لا خبز في المدينة».","38:10":"فأمر الملك عبد ملك الإثيوبي: «اصطحب معك من هنا ثلاثين رجلا، واسحب إرميا من الجب قبل أن يموت».","38:11":"فاصطحب عبد ملك الرجال معه، ومضى إلى قصر الملك إلى قبو المستودع، وأخذ من هناك ثيابا رثة، وخرقا بالية، ودلاها إلى إرميا إلى الجب بحبال،","38:12":"وقال لإرميا: «ضع الثياب الرثة والخرق البالية بين إبطيك والحبال». ففعل إرميا كذلك.","38:13":"فسحبوا إرميا بالحبال وأخرجوه من الجب. ومكث إرميا في دار الحرس.","38:14":"ثم بعث الملك صدقيا واستدعى إليه إرميا النبي، واستقبله في المدخل الثالث لهيكل الرب. وقال الملك لإرميا: «أسألك عن أمر فلا تكتم عني شيئا».","38:15":"فأجاب إرميا صدقيا: «إن أنبأتك، ألا تقتلني حتما؟ وإن أشرت عليك فأنت لا تقبل مشورتي».","38:16":"فحلف الملك صدقيا لإرميا سرا قائلا: «حي هو الرب الذي صنع لنا أنفسنا، أني لا أقتلك ولا أسلمك إلى يد أعدائك طالبي نفسك».","38:17":"عندئذ قال إرميا لصدقيا: «هذا ما يعلنه الرب القدير إله إسرائيل: إن استسلمت إلى قواد ملك بابل تنجو بنفسك من الموت، ولا تحرق هذه المدينة بالنار بل تحيا أنت وأهل بيتك.","38:18":"ولكن إن لم تستسلم لقواد ملك بابل فإن هذه المدينة تقع في قبضة الكلدانيين، فيحرقونها بالنار، وأنت لا تفلت من أيديهم».","38:19":"فأجاب الملك: «أخشى أن أقع في يد اليهود الذين لجأوا إلى الكلدانيين فيسخروا مني».","38:20":"فقال إرميا: «إنك لن تسلم إليهم. اسمع لصوت الرب في كل ما أقوله لك، فتنعم بالخير وتنجو نفسك.","38:21":"لكن إن أبيت الاستسلام، فإليك الرؤيا التي أعلنها لي الرب:","38:22":"ها جميع النساء اللواتي ما برحن في قصر ملك يهوذا يؤسرن ويحملن إلى قواد ملك بابل، وهن قائلات: قد خدعك أصدقاؤك موضع ثقتك وتغلبوا على رأيك. وحالما غرقت رجلاك في الحمأة تخلوا عنك.","38:23":"وتحمل جميع نسائك وأبنائك إلى الكلدانيين، وأنت لا تفلت من أيديهم، بل يأسرك ملك بابل، وتحرق هذه المدينة بالنار».","38:24":"فقال صدقيا لإرميا: «اكتم هذا الحديث فلا يعلم به أحد لئلا تموت.","38:25":"فإذا سمع الرؤساء أني تحدثت إليك وسألوك: بماذا خاطبت الملك، وماذا قال الملك؟ لا تكتم عنا شيئا، ونحن لن نقتلك.","38:26":"فأجبهم: إني توسلت إلى الملك أن لا يردني إلى بيت يوناثان لأموت هناك».","38:27":"فأقبل كل الرؤساء إلى إرميا واستجوبوه، فأخبرهم بمقتضى ما أوصاه به الملك من كلام. فكفوا عنه لأن الحديث الذي دار بينهما لم يشع.","38:28":"فأقام إرميا في دار الحرس إلى اليوم الذي سقطت فيه أورشليم.","39:1":"وفي الشهر العاشر من السنة التاسعة من حكم صدقيا ملك يهوذا، زحف الملك نبوخذناصر وكل جيشه على أورشليم وحاصرها.","39:2":"وفي اليوم التاسع من الشهر الرابع من السنة الحادية عشرة من حكم صدقيا فتحت ثغرة في سور المدينة.","39:3":"وما لبث أن دخل كل رؤساء ملك بابل وجلسوا في الباب الأوسط وهم: نرجل شراصر، وسمجر نبو، وسرسخيم رئيس الخصيان، ونرجل شراصر رئيس المجوس، وسائر قواد ملك بابل.","39:4":"وعندما شاهدهم صدقيا ملك يهوذا وكل المحاربين فروا هاربين من المدينة ليلا عن طريق جنة الملك، من الباب القائم بين السورين، واتجهوا نحو العربة.","39:5":"فتعقبهم جيش الكلدانيين، فأدركوا صدقيا في سهل أريحا، فقبضوا عليه وقادوه إلى نبوخذناصر ملك بابل في ربلة في أرض حماة، فأصدر عليه حكمه.","39:6":"وقتل ملك بابل أبناء صدقيا في ربلة على مرأى منه كما قتل سائر أشراف يهوذا.","39:7":"وفقأ عيني صدقيا وقيده بسلاسل من نحاس ليأخذه أسيرا إلى بابل.","39:8":"وأحرق الكلدانيون قصر الملك وبيوت الشعب ونقضوا أسوار أورشليم.","39:9":"وسبى نبوزرادان رئيس شرطة بابل بقية الشعب الذي بقي في المدينة، وكل من لجأ إليه.","39:10":"أما الفقراء ممن لم يكن لديهم شيء فتركهم نبوزرادان رئيس الشرطة في أرض يهوذا، ووزع عليهم كروما وحقولا في ذلك اليوم.","39:11":"وأوصى نبوخذناصر ملك بابل نبوزرادان رئيس الشرطة بإرميا قائلا:","39:12":"«خذه واعتن به أشد عناية ولا تؤذه، بل استجب لكل ما يطلبه منك».","39:13":"فبعث نبوزرادان رئيس الشرطة ونبوشزبان رئيس الخصيان ونرجل شراصر رئيس المجوس وجميع قواد ملك بابل،","39:14":"وأخرجوا إرميا من دار الحرس، وعهدوا به إلى جدليا بن أخيقام بن شافان ليأخذه إلى بيته. فأقام بين الشعب.","39:15":"وهذه هي النبوءة التي أوحى بها الرب إلى إرميا بينما كان معتقلا في دار الحرس:","39:16":"«اذهب وقل لعبد ملك الإثيوبي: هذا ما يعلنه الرب القدير إله إسرائيل: ها أنا أتمم قضائي على هذه المدينة، فأوقع بها الشر لا الخير، فيتحقق كل شيء على مرأى منك في ذلك اليوم.","39:17":"أما أنت فأنقذك في ذلك اليوم، يقول الرب، فلا تقع في يد الناس الذين تخشاهم.","39:18":"إنما أنجيك فلا تسقط بالسيف، بل تسلم بحياتك، فتكون لك غنيمة، لأنك اتكلت علي، يقول الرب».","40:1":"هذه هي النبوءة التي أوحى بها الرب إلى إرميا بعد أن أطلقه نبوزرادان رئيس الشرطة من الرامة حين قاده مقيدا بالأغلال مع بقية أسرى أورشليم ويهوذا المنفيين إلى بابل،","40:2":"إذ انتحى رئيس الشرطة بإرميا جانبا وقال له: «إن الرب إلهك قد قضى بهذه البلية على هذا الموضع.","40:3":"فقد تمم الرب هذا القضاء، ووفى بما أنذر به. لأنكم أخطأتم في حق الرب ولم تطيعوا صوته، حل بكم هذا الأمر.","40:4":"والآن ها أنا أطلقك اليوم من القيود التي تغل يديك، فإن طاب لك أن تأتي معي إلى بابل فتعال، وأنا أعتني بك أشد عناية. وإن ساء في عينيك أن تأتي معي إلى بابل فابق. ها كل البلاد مشرعة أمامك، فاذهب حيث يحلو لك.","40:5":"وإن عزمت على البقاء فارجع إلى جدليا بن أخيقام الذي نصبه ملك بابل واليا على مدن يهوذا وأقم عنده في وسط الشعب، واذهب حيث يحلو لك». وأعطاه رئيس الشرطة مؤونة وهدية وأطلقه.","40:6":"فذهب إرميا إلى جدليا بن أخيقام وأقام عنده في وسط الشعب الباقي في الأرض.","40:7":"فلما سمع كل رؤساء الجيوش المنتشرة في الصحراء ورجالهم أن ملك بابل قد ولى جدليا بن أخيقام ليكون حاكما في البلاد، وعهد إليه بالرجال والنساء والأطفال وفقراء الأرض الذين لم يسبوا إلى بابل،","40:8":"جاءوا إلى جدليا في المصفاة، وهم إسماعيل بن نثنيا، ويوحانان ويوناثان ابنا قاريح، وسرايا بن تنحومث، وبنوعيفاي النطوفاتي، ويزنيا ابن المعكي مع رجالهم.","40:9":"فحلف جدليا بن أخيقام بن شافان لهم ولرجالهم: «لا تخافوا من خدمة الكلدانيين. أقيموا في البلاد واخضعوا لملك بابل فتنالوا خيرا.","40:10":"أما أنا فسأسكن في المصفاة، وأتولى الأمر عنكم لدى الكلدانيين الذين يفدون إلينا أما أنتم فاجمعوا خمرا وقطاف الصيف والزيت وادخروها في أوعيتكم وأقيموا في مدنكم التي أخذتموها».","40:11":"وكذلك حين سمع كل اليهود المشتتين في أرض موآب وبين بني عمون وفي أدوم وفي البلدان الأخرى أن ملك بابل قد ترك بقية من يهوذا، وولى جدليا بن أخيقام بن شافان حاكما عليهم،","40:12":"رجعوا من كل البقاع التي تشتتوا إليها، وجاءوا إلى أرض يهوذا إلى جدليا في المصفاة، واختزنوا خمرا وغلات كثيرة من قطاف الصيف.","40:13":"ثم اجتمع يوحانان بن قاريح وسائر رؤساء القوات الذين لاذوا بالصحراء إلى جدليا في المصفاة،","40:14":"وقالوا له: «أتدري أن بعليس ملك بني عمون قد بعث إسمعيل بن نثنيا ليغتالك؟» فلم يصدقهم جدليا بن أخيقام.","40:15":"فقال يوحانان بن قاريح لجدليا سرا في المصفاة: «دعني أذهب وأقتل إسمعيل بن نثنيا من غير علم أحد فلماذا يغتالك فيتبدد جميع المجتمعين إليك من شعب اليهود، وتهلك بقية يهوذا؟».","40:16":"فأجاب جدليا بن أخيقام يوحانان بن قاريح: «لا ترتكب هذا الأمر لأنك تتهم إسمعيل كذبا».","41:1":"وفي الشهر السابع أقبل إسمعيل بن نثنيا بن أليشاماع، من النسل الملكي، وأحد قواد الملك، إلى جدليا بن أخيقام إلى المصفاة، برفقة عشرة رجال. وبعد أن تناولوا الطعام معا في المصفاة،","41:2":"اغتال إسمعيل بن نثنيا والعشرة الرجال المرافقون له بسيوفهم جدليا بن أخيقام الذي ولاه ملك بابل حاكما على البلاد.","41:3":"كما قتل إسمعيل كل اليهود الحاضرين مع جدليا في المصفاة والكلدانيين المحاربين الموجودين هناك.","41:4":"وفي اليوم التالي من اغتيال جدليا، ولم يكن أحد قد علم بالأمر بعد،","41:5":"أقبل ثمانون رجلا من شكيم ومن شيلو ومن السامرة بلحى محلوقة وثياب ممزقة وأجساد مجرحة، حاملين معهم تقدمة من الدقيق ولبانا ليحضروها إلى بيت الرب.","41:6":"فخرج إسمعيل بن نثنيا من المصفاة، وكان يسير باكيا، وعندما التقاهم قال لهم: «تعالوا إلى جدليا بن أخيقام».","41:7":"فلما بلغوا وسط المدينة ذبحهم إسمعيل بن نثنيا وطرح جثثهم بمعونة رجاله إلى أعماق الجب.","41:8":"إلا أن عشرة رجال كانوا بينهم قالوا لإسمعيل: «لا تقتلنا لأن لدينا مؤنا من حنطة وشعير وزيت وعسل خبأناها في الصحراء» فلم يقتلهم.","41:9":"وكان الجب الذي طرح فيه إسمعيل جثث قتلاه وجثة جدليا هو الجب الكبير الذي حفره الملك آسا للدفاع ضد بعشا ملك إسرائيل، فملأه إسمعيل بالقتلى.","41:10":"ثم سبى إسمعيل بقية الشعب الذي كان في المصفاة، وبنات الملك، وكل من تخلف في المصفاة، ممن عهد بهم نبوزرادان رئيس الشرطة إلى جدليا بن أخيقام، وانطلق بهم إسمعيل إلى بني عمون.","41:11":"ولكن لما سمع يوحانان بن قاريح وجميع قادة القوات الذين معه ما ارتكبه إسمعيل بن نثنيا من شر،","41:12":"أخذوا جميع رجالهم وتعقبوا إسمعيل بن نثنيا ليقاتلوه، فصادفوه عند البركة الكبيرة التي في جبعون.","41:13":"فلما شاهد جميع أسرى إسمعيل يوحانان بن قاريح وكل قادة القوات المرافقين له فرحوا،","41:14":"فانثنى الأسرى الذين سباهم إسمعيل في المصفاة وقفلوا راجعين إلى يوحانان بن قاريح.","41:15":"أما إسمعيل بن نثنيا فهرب من يوحانان مع ثمانية من رجاله وانطلق إلى العمونيين.","41:16":"فاقتاد يوحانان بن قاريح وسائر قواد القوات الذين معه بقية شعب المصفاة، الذين استردهم من إسمعيل بن نثنيا، الذي كان قد سباهم بعد اغتيال جدليا بن أخيقام، وهم محاربون أشداء ونساء وأطفال وخصيان، وأعادهم من جبعون.","41:17":"فأقاموا في جيروت كمهام المجاورة لبيت لحم، لينطلقوا منها إلى مصر.","41:18":"هاربين من وجه الكلدانيين خوفا منهم، بسبب اغتيال إسمعيل بن نثنيا لجدليا بن أخيقام الذي ولاه ملك بابل على البلاد.","42:1":"ثم اجتمع كل قواد القوات ويوحانان بن قاريح ويزنيا بن هوشعيا وجميع الشعب صغيرهم وكبيرهم،","42:2":"إلى إرميا قائلين: «ليت توسلنا يكون مقبولا لديك، فتصلي إلى الرب إلهك من أجل هذه البقية كلها، فقد كنا كثيرين ولكن صرنا الآن قليلين كما ترى،","42:3":"فينبئنا الرب إلهك بالطريق الذي يتحتم علينا سلوكه وبما يجب علينا عمله».","42:4":"فأجابهم إرميا النبي: «قد استجبت لكم، وها أنا أصلي إلى الرب إلهكم بحسب كلامكم، وكل ما يجيب به الرب أخبركم به. لا أكتم عنكم شيئا».","42:5":"ثم قالوا لإرميا: «ليكن الرب بيننا شاهدا أمينا صادقا، أننا ننفذ كل كلمة يوحي بها الرب إلينا على لسانك،","42:6":"سواء كانت خيرا أو شرا، فنطيع صوت الرب إلهنا الذي نرسلك إليه، فننال خيرا إن أطعناه».","42:7":"وبعد عشرة أيام أوحى الرب إلى إرميا برسالة،","42:8":"فاستدعى إرميا يوحانان بن قاريح وقواد القوات الذين معه وسائر الشعب من صغيرهم إلى كبيرهم،","42:9":"وقال لهم: «هذا ما يعلنه الرب إله إسرائيل الذي أرسلتموني لأرفع توسلكم إليه:","42:10":"إن أقمتم في هذه الأرض فإني أبنيكم ولا أهدمكم، وأغرسكم ولا أستأصلكم، لأني أسفت على الشر الذي ألحقته بكم.","42:11":"لا تخشوا ملك بابل الذي أنتم منه خائفون فإني معكم لأخلصكم وأنجيكم من يده.","42:12":"وأنعم عليكم فيرحمكم ويردكم إلى أرضكم.","42:13":"ولكن إن قلتم: لن نقيم في هذه الأرض، ولم تطيعوا صوت الرب إلهكم.","42:14":"قائلين: لا بل ننطلق إلى ديار مصر حيث لا نشهد قتالا، ولا نسمع نفير بوق، ولا يعوزنا خبز، فنمكث هناك،","42:15":"إذا اسمعوا قضاء الرب يابقية يهوذا: إن وطدتم العزم على الذهاب إلى مصر وارتحلتم لتتغربوا هناك،","42:16":"فالسيف الكلداني الذي تخشونه يدرككم هناك في ديار مصر، والجوع الذي تفزعون منه يلاحقكم إلى مصر فتموتون هناك.","42:17":"وكل من استقر عزمه من الشعب على الانطلاق إلى مصر والتغرب هناك يموت بالسيف والجوع والوباء، ولا يفلت ناج من الشر الذي أجلبه عليهم.","42:18":"لأن هذا ما يعلنه الرب القدير إله إسرائيل. كما انسكب غضبي وسخطي على أهل أورشليم، كذلك ينسكب سخطي عليكم إذا ذهبتم إلى مصر، فتصبحون مثار سبة ودهشة ولعنة وعار، ولا تعودون ترون هذا الموضع».","42:19":"«فيابقية إسرائيل لا تهاجروا إلى مصر. تيقنوا أني قد حذرتكم اليوم.","42:20":"لأنكم قد خدعتم أنفسكم حين بعثتم بي إلى الرب إلهكم قائلين: صل لأجلنا إلى الرب إلهنا وأنبئنا بكل ما يقول فنفعل بمقتضاه.","42:21":"وها أنا قد أنبأتكم اليوم بكلامه فلم تطيعوا صوت الرب إلهكم في أي شيء أرسلني به إليكم.","42:22":"فثقوا الآن أنكم تموتون بالسيف والجوع والوباء في ذات الموضع الذي نويتم الارتحال إليه والتغرب فيه».","43:1":"عندما فرغ إرميا من الإدلاء بكل رسالة الرب إلههم التي أوحى بها إليه ليبلغها للشعب جميعه،","43:2":"قال عزريا بن هوشعيا ويوحانان بن قاريح، وسائر الرجال المتعجرفين لإرميا: «أنت تنطق بالكذب، فالرب إلهنا لم يرسلك لتقول لنا: لا ترحلوا إلى مصر لتتغربوا فيها.","43:3":"إنما يثيرك باروخ بن نيريا علينا لتسلمنا إلى الكلدانيين حتى يقتلونا ويسبونا إلى بابل».","43:4":"وأبى يوحانان بن قاريح وسائر قواد القوات وكل الشعب طاعة صوت الرب للإقامة في أرض يهوذا.","43:5":"بل أخذوا كل بقية يهوذا الذين رجعوا من بين جميع الأمم التي تشتتوا فيها ليقيموا في أرض يهوذا،","43:6":"الرجال والنساء والأطفال وبنات الملك، وكل إنسان تركه نبوزرادان رئيس الشرطة في عهدة جدليا بن أخيقام بن شافان، وإرميا النبي، وباروخ بن نيريا.","43:7":"فأقبلوا إلى مصر إذ لم يطيعوا صوت الرب. ونزلوا في تحفنحيس.","43:8":"ثم أوحى الرب إلى إرميا بهذه النبوءة في تحفنحيس قائلا:","43:9":"«خذ حجارة كبيرة بيدك واطمرها في الملاط المرصوف عند مدخل قصر فرعون في تحفنحيس على مرأى رجال يهوذا.","43:10":"وقل لهم، هذا ما يعلنه الرب القدير إله إسرائيل: ها أنا آتي بعبدي نبوخذناصر وأنصب عرشه فوق هذه الحجارة التي طمرتها، فيبسط أريكته الملكية عليها.","43:11":"سيقبل ويدمر ديار مصر، فيموت من قضي عليه بالموت، ويسبى من قضي عليه بالسبي، ويقتل بالسيف من قضي عليه بالقتل بالسيف.","43:12":"ويضرم معابد آلهة المصريين بالنار ويحرقها ويسبيها، ويلف مصر حول نفسه كما يلف الراعي عباءته، ويخرج من هناك سليما","43:13":"بعد أن يهدم أنصاب معبد الشمس التي في مصر، ويحرق معابد آلهة المصريين بالنار».","44:1":"هذه هي النبوءة التي أوحي بها إلى إرميا عن اليهود المقيمين في مصر، النازلين في مجدل وفي تحفنحيس وممفيس وفي منطقة جنوب مصر.","44:2":"«هذا ما يعلنه الرب القدير إله إسرائيل: قد شهدتم كل ما أوقعته من شر بأورشليم وبكافة مدن يهوذا. ها هي اليوم خربة مهجورة","44:3":"لشر أهلها الذي ارتكبوه ليثيروا سخطي، إذ ذهبوا ليحرقوا بخورا ويعبدوا آلهة أخرى من الأصنام لم يعرفوها هم ولا أنتم ولا اباؤكم.","44:4":"وقد أرسلت إليكم منذرا منذ البدء جميع عبيدي الأنبياء قائلا: لا تقترفوا رجسا مثل هذا لأني أمقته،","44:5":"فلم يرتدعوا ولا سمعوا ليتوبوا ويكفوا عن إحراق البخور لتلك الأصنام،","44:6":"فانصب غيظي وحنقي، وأشعلا مدن يهوذا وشوارع أورشليم حتى أصبحت جميعا أطلالا وخرابا كما هي في هذا اليوم.","44:7":"والآن هذا ما يعلنه الرب القدير إله إسرائيل: لماذا ترتكبون هذا الشر العظيم في حق أنفسكم، لينقرض منكم الرجل والمرأة والطفل والرضيع من بين شعب يهوذا ولا تبقى منكم بقية؟","44:8":"لماذا تغيظونني باقتراف الإثم إذ تحرقون بخورا لآلهة أصنام مصر التي هاجرتم إليها لتتغربوا فيها، فتنقرضون وتصبحون لعنة وعارا بين كل أمم الأرض؟","44:9":"هل نسيتم شرور آبائكم وشرور ملوك يهوذا وشرور نسائهم، وشروركم وشرور نسائكم التي ارتكبت في أرض يهوذا وفي شوارع أورشليم؟","44:10":"إنهم لم يتذللوا إلى هذا اليوم ولا اتقوا ولا سلكوا في شريعتي وفرائضي التي سننتها لكم ولآبائكم.","44:11":"لذلك هذا ما يعلنه الرب القدير إله إسرائيل: ها أنا أترصدكم لأجازيكم شرا لا خيرا، لأستأصلكم من يهوذا.","44:12":"وآخذ بقية يهوذا الذين وطدوا العزم على الرحيل إلى مصر ليتغربوا فيها، وأفنيهم كلهم هناك، فيهلكون بالسيف والجوع من صغيرهم إلى كبيرهم، فيموتون ويصبحون سبة ودهشة ولعنة وعارا.","44:13":"وأعاقب المقيمين في مصر كما عاقبت أهل أورشليم بالسيف والجوع والوباء،","44:14":"فلا يفلت منهم ناج، ولا يسلم أحد من بقية يهوذا المرتحلين ليتغربوا هناك في مصر، ليرجع إلى أرض يهوذا التي يتوق للعودة إليها والإقامة فيها، لأنه لن يرجع إليها إلا قلة من الطريدين».","44:15":"غير أن جميع الرجال الذين يعرفون أن نساءهم يحرقن بخورا لآلهة الأصنام، وكذلك النساء الحاضرات، وسائر المقيمين في المنطقة الجنوبية في مصر، وهم عدد كبير قالوا لإرميا:","44:16":"«لن نطيعك في ما خاطبتنا به من كلام باسم الرب،","44:17":"بل نعمل بمقتضى ما تعهدنا به، فنحرق بخورا لملكة السماء ونقرب لها السكائب كما سبق أن فعلنا نحن وآباؤنا وملوكنا ورؤساؤنا في مدن يهوذا وفي شوارع أورشليم، فكانت لنا وفرة من الطعام وتمتعنا بالخير ولم يصبنا شر.","44:18":"ولكن منذ أن أهملنا إحراق البخور لملكة السماء وتقريب السكائب لها، افتقرنا إلى كل شيء، وفنينا بالسيف والجوع».","44:19":"وقالت النساء: «عندما أحرقنا البخور لملكة السماء وقربنا لها السكائب وعملنا أقراصا مماثلة لصورتها، وقربنا السكائب لها هل فعلنا ذلك بغير علم أزواجنا؟»","44:20":"فقال إرميا للقوم من رجال ونساء وسائر الشعب الذين أجابوه بهذا الكلام:","44:21":"«أليس ما أحرقتموه من بخور في مدن يهوذا وفي شوارع أورشليم أنتم وآباؤكم وملوككم ورؤساؤكم وسكان الأرض، هو الذي ذكره الرب وخطر على باله؟","44:22":"فلم يطق الرب بعد تحمل ما ارتكبتم من شر وما اقترفتم من أرجاس، فصارت أرضكم أطلالا ومثار دهشة ولعنة ومهجورة كالعهد بها في هذا اليوم.","44:23":"إن البلاء الذي حل بكم كما في هذا اليوم هو عقاب لكم على إحراقكم البخور وتعديكم على الرب وعصيانكم لصوته، وعدم سلوككم في شريعته وفرائضه وشهاداته.","44:24":"والآن اسمعوا قضاء الرب ياجميع أهل يهوذا المقيمين في مصر:","44:25":"هذا ما يعلنه الرب القدير إله إسرائيل: قد نطقتم بأفواهكم أنتم ونساؤكم، ونفذتم بأيديكم ما نطقتم به قائلين: إننا نفي بنذورنا التي نذرناها بأن نحرق البخور لملكة السماء، ونقرب لها السكائب، فهيا إذا أوفوا نذوركم وأنجزوها.","44:26":"لذلك اسمعوا كلمة الرب ياجميع شعب يهوذا المقيمين في مصر: ها أنا قد أقسمت باسمي العظيم يقول الرب، أن لا يتردد اسمي من بعد على فم أحد من شعب يهوذا في كافة ديار مصر قائلا: «حي هو السيد الرب».","44:27":"ها أنا أترصدهم لأوقع بهم شرا لا خيرا، فيهلك كل رجال يهوذا الذين في أرض مصر بالسيف والجوع حتى يتم استئصالهم.","44:28":"وترجع القلة الناجية من السيف من مصر إلى أرض يهوذا، فتعلم كل بقية يهوذا الذين هاجروا إلى مصر ليتغربوا فيها أي كلام يتحقق: كلامي أم كلامهم؟»","44:29":"ويقول الرب: «وهذه لكم علامة أنني أعاقبكم في هذا الموضع بالذات، لتدركوا أن قضائي عليكم بالشر حتما يتم.","44:30":"ها أنا أسلم فرعون حفرع ملك مصر إلى يد أعدائه وطالبي نفسه كما أسلمت صدقيا ملك يهوذا إلى يد نبوخذناصر ملك بابل عدوه وطالب نفسه».","45:1":"هذا هو الكلام الذي خاطب به إرميا النبي باروخ بن نيريا حين دون هذه العبارات في كتاب عن لسان إرميا، في السنة الرابعة لحكم يهوياقيم بن يوشيا ملك يهوذا.","45:2":"«هذا ما يعلنه الرب إله إسرائيل لك ياباروخ:","45:3":"قد قلت: ويل لي لأن الرب قد أضاف حزنا إلى ألمي، وأعييت في أنيني، ولم أجد راحة.","45:4":"لذلك هذا ما تقوله له: هكذا يعلن الرب، ها أنا أهدم ما بنيته وأستأصل ما غرسته في كل هذه الأرض.","45:5":"وأنت، هل تلتمس لنفسك عظائم الأمور؟ لا تلتمس، فها أنا جالب بلاء على كل بشر يقول الرب. أما أنت فأهب لك النجاة، فتكون لك نفسك غنيمة في جميع الأماكن التي تذهب إليها».","46:1":"هذه هي النبوءة التي أوحى بها الرب إلى إرميا عن الأمم.","46:2":"نبوءة عن مصر، عن جيش فرعون نخو ملك مصر الذي كان معسكرا على نهر الفرات في كركميش، حيث قضى عليه نبوخذناصر ملك بابل في السنة الرابعة ليهوياقيم بن يوشيا ملك يهوذا.","46:3":"«أعدوا المجن والترس وازحفوا للقتال.","46:4":"أسرجوا الخيل وامتطوها أيها الفرسان، وانتصبوا بالخوذ. اصقلوا الرماح والبسوا الدروع.","46:5":"ولكن مالي أراهم يولون الأدبار مرتعبين؟ قد دحر محاربوهم وفروا مسرعين. لم يلتفتوا إلى الوراء، قد حاصرهم الهول من كل جانب»، يقول الرب.","46:6":"«عجز الخفيف عن الجري للفرار، وليس في وسع المحارب الهرب. في الشمال عثروا وسقطوا إلى جوار نهر الفرات.","46:7":"من هذا الطاغي كالنيل، كالأنهار المتلاطمة الأمواج؟","46:8":"تتعالى مصر كفيضان النيل، كالأنهار المتلاطمة الأمواج. تقول: أفيض وأغمر الأرض، أهدم المدن وأهلك سكانها.","46:9":"اقتحمي أيتها الخيل، وثوري يامركبات، وليبرز المحاربون من رجال كوش وفوط، الحاملين التروس، ومن رجال لوديم رماة السهام بالقسي.","46:10":"فهذا اليوم هو يوم قضاء السيد الرب القدير، يوم الانتقام. فيه يثأر لنفسه من أعدائه، فيلتهم السيف ويشبع، ويرتوي من دمائهم، لأن للسيد الرب القدير ذبيحة في أرض الشمال إلى جوار نهر الفرات.","46:11":"اصعدي إلى جلعاد وخذي بلسانا ياعذراء ابنة مصر. ولكن باطلا تكثرين من العقاقير، إذ لا شفاء لك.","46:12":"ستسمع الأمم بما لحق بك من عار، ويملأ صراخك الأرض، لأن بطلا محاربا يصطدم ببطل محارب فيسقطان كلاهما معا».","46:13":"النبوءة التي أوحى بها الرب إلى إرميا النبي عن زحف نبوخذناصر ملك بابل لمهاجمة مصر:","46:14":"«أذيعوا في مصر وأعلنوا في مجدل. خبروا في ممفيس وفي تحفنحيس، قولوا: قف متأهبا وتهيأ لأن السيف يلتهم من حولك.","46:15":"لماذا فر إلهك الثور أبيس ولم يصمد في القتال؟ لأن الرب طرحه.","46:16":"كثر العاثرين، فسقط كل واحد على صاحبه. فتقول بقية اليهود آنئذ: قوموا لنرجع إلى قومنا وإلى أرض موطننا، هربا من سيف الطاغي.","46:17":"ويهتفون هناك: إن فرعون ملك مصر ليس سوى طبل أجوف أضاع فرصته.","46:18":"حي أنا يقول الملك الذي اسمه الرب القدير، سيقبل نبوخذناصر كجبل تابور بين الجبال وكالكرمل عند البحر.","46:19":"تأهبوا للجلاء ياأهل مصر، لأن ممفيس ستضحى أطلالا وخربا مهجورة.","46:20":"مصر عجلة فاتنة هاجمها الهلاك من الشمال.","46:21":"حتى مرتزقتها في وسطها كعجول مسمنة قد نكصوا على أعقابهم هاربين معا ولم يصمدوا، لأن يوم بلائهم قد حل بهم في وقت عقابهم.","46:22":"صوتها كحفيف الحية المتلوية، لأن أعداءها زاحفون إليها بفؤوس كحطابي الأشجار.","46:23":"سيقطعون غابها، يقول الرب، وإن كان يتعذر اختراقه، لأن عددهم يفوق الجراد في الكثرة.","46:24":"لحق الخزي بابنة مصر، ووقعت في أسر أهل الشمال».","46:25":"ويقول الرب القدير إله إسرائيل: «ها أنا أعاقب آمون طيبة وفرعون، ومصر وآلهتها، وملوكها، وكل من يتكل على فرعون.","46:26":"وأسلمهم إلى يد طالبي حياتهم: إلى يد نبوخذناصر ملك بابل ويد رجاله، ثم تعود بعد ذلك وتصبح آهلة بالسكان كالعهد بها في الحقب السالفة، يقول الرب.","46:27":"ولكن لا تخافوا ياذرية عبدي يعقوب، ولا تفزع ياإسرائيل، لأني سأنقذكم من الغربة وأخلص نسلكم من أرض السبي، فترجع ذرية يعقوب وتتمتع بالدعة والطمأنينة من غير أن يرعبها أحد.","46:28":"لا تخافوا ياذرية عبدي يعقوب، يقول الرب، لأني معكم وأفني جميع الأمم التي شتتكم إليها. أما أنتم فلا أفنيكم بل أؤدبكم بالحق، إنما لا أبرئكم جميعا».","47:1":"هذه هي النبوءة التي أوحى بها الرب إلى إرميا عن الفلسطينيين قبل أن يهاجم فرعون غزة.","47:2":"هذا ما يعلنه الرب: «ها هي مياه تطغى من الشمال، فتصبح سيلا جارفا، فتغمر الأرض ومن عليها، المدينة والساكنين فيها. فيستغيث الناس ويولول كل أهل البلاد،","47:3":"من صوت وقع حوافر خيله، ومن جلبة مركباته، ومن صرير عجلاتها، فلا يلتفت الآباء إلى الأبناء من فرط ما يعتريهم من وهن.","47:4":"رعبا من اليوم المقبل لإبادة الفلسطينيين، ولاستئصال صور وصيدون وكل معين باق، لأن الرب يدمر الفلسطينيين بقية جزيرة كفتور.","47:5":"قد أصبحت غزة جرداء، وساد أشقلون صمت الموت. يابقية العناقيين، إلى متى تظلون تجرحون أنفسكم حزنا؟","47:6":"ياسيف الرب، متى تستكين؟ استقر في غمدك واهدأ واسترح.","47:7":"كيف يمكن له أن يستكين، وقد أصدر الرب له أمره ليضرب أشقلون ومدن ساحل البحر، هناك واعده الرب على اللقاء».","48:1":"نبوءة عن الموآبيين: هذا ما يعلنه الرب القدير إله إسرائيل: «ويل لنبو لأنها أصبحت أطلالا. لحق العار بقريتايم وتم الاستيلاء عليها. خزي الحصن وارتعب.","48:2":"زال فخر موآب وتآمروا في حشبون عليها شرا قائلين: هيا نهدمها فلا تكون أمة بعد. وأنت أيضا يامدمين، يهيمن عليك صمت الموت ويلاحقك السيف.","48:3":"اسمعوا صوت صراخ من حورونايم: قد حل بنا هلاك ودمار عظيمان.","48:4":"قد تحطمت موآب، وبلغ صراخها صوغر.","48:5":"إذ على مرتفع لوحيت يصعدون باكين بمرارة، وعلى منحدر حورونايم يتردد صراخ الانكسار.","48:6":"اهربوا وانجوا بأنفسكم. كونوا كعرعر في البرية.","48:7":"لأنكم اتكلتم على أعمالكم وكنوزكم، ستسبون أيضا ويقع الصنم كموش أيضا أسيرا ويؤخذ إلى المنفى مع كهنته ورؤسائه.","48:8":"ويزحف المدمر إلى كل مدينة، فلا تفلت منه إحداها، فيبيد الوادي، ويتلف السهل، لأن الرب قد قضى.","48:9":"أعطوا موآب أجنحة، فيحلق طائرا. قد أصبحت مدنه أطلالا مهجورة من الناس.","48:10":"ملعون من يقوم بعمل الرب متهاونا، وملعون من حظر على سيفه الدم.","48:11":"قد قضى موآب حياة مترفة منذ حداثته، كالخمر المستقر على عكره. لم يفرغ من إناء إلى إناء، ولم يذهب إلى السبي قط لذلك ظل محتفظا بطعمه ولم تتغير رائحته.","48:12":"ها هي أيام مقبلة، يقول الرب، أرسل فيها إليه عابري السبيل ساكبي الجرار، فيسكبونه ويفرغون جراره ويحطمون دنانه.","48:13":"فيعتري الموآبيين الخجل من كموش، كما اعترى الخجل الإسرائيليين من بيت إيل، متكلهم.","48:14":"كيف تقولون: إننا أبطال وجبابرة حرب؟","48:15":"إن موآب سيدمر، وتغزى مدنه، وتنزل نخبة شبانه للذبح، يقول الملك الذي اسمه الرب القدير.","48:16":"قد أزفت بلية موآب ومحنته أقبلت مسرعة.","48:17":"فارثوه ياجميع المحيطين به وسائر العارفين اسمه. قولوا انكسر صولجان العز وقضيب المجد.","48:18":"اهبطي من المجد واجلسي على الأرض الظمأى أيتها الساكنة في ديبون، لأن مدمر موآب قد زحف عليك وهدم حصونك.","48:19":"قفي على قارعة الطريق وراقبي ياساكنة عروعير. اسألي الهارب والناجية بنفسها: ماذا جرى؟","48:20":"فيأتي الجواب: قد لحق الخزي بموآب، لأنه صار أطلالا فولولوا وأعولوا. أذيعوا في أرنون أن موآب قد أصبح خرابا.","48:21":"قد وقع القضاء على أرض السهل، وعلى حولون، وعلى يهصة، وعلى ميفعة،","48:22":"وعلى ديبون، وعلى نبو، وعلى بيت دبلتايم،","48:23":"وعلى قريتايم، وعلى بيت جامول، وعلى بيت معون،","48:24":"وعلى قريوت، وعلى بصرة، وعلى كافة مدن بلاد موآب البعيدة والقريبة.","48:25":"قد كسر قرن موآب، وتحطمت ذراعه، يقول الرب.","48:26":"أسكروه حتى يتمرغ في قيئه، ويصبح مهزأة، لأنه تغطرس على الرب.","48:27":"ألم يصبح إسرائيل مهزأة لديك؟ أكان بين اللصوص حتى كنت تهز رأسك باحتقار كلما جاء ذكره على لسانك؟","48:28":"اهجروا المدن وأقيموا بين الصخور ياأهل موآب، وكونوا كالحمامة التي تعشش عند حافة فوهة الكهف.","48:29":"قد سمعنا عن عجرفة موآب المفرطة. إنه شديد الكبرياء. سمعنا عن غطرسته وتشامخه وغروره، وعن ارتفاع قلبه.","48:30":"قد عرفت كبرياءه يقول الرب، إنما زهوه باطل، وتفاخره عديم الجدوى.","48:31":"لذلك أنوح على موآب وأعول على كل أهله، وأئن على رجال قير حارس.","48:32":"أبكي عليك أكثر من البكاء على يعزير ياجفنة سبمة التي امتدت فروعها حتى البحر، بل بلغت بحر يعزير، فإن المدمر قد انقض على حصادك الناضج وقطافك.","48:33":"قد تلاشى الفرح والغبطة من بساتين موآب ومن حقوله، وأوقف تدفق الخمر من المعاصر فلا يدوسها دائس بهتاف، بل تعلو صرخات لا هتاف فيها.","48:34":"يرتفع الصراخ من حشبون إلى ألعالة فياهص. أطلقوا أصواتهم من صوغر إلى حورونايم حتى العجلة الثالثة، لأن مياه نمريم أيضا قد نضبت.","48:35":"وأبيد من موآب، يقول الرب، من يقرب ذبيحة على مرتفعة، ومن يحرق بخورا لآلهة الوثن.","48:36":"لذلك يئن قلبي على موآب كأنين مزمار، وينوح فؤادي على رجال قير حارس كنوح الناي، فإن ثروتهم التي اكتسبوها قد تبددت.","48:37":"قد أصبح كل رأس أقرع، وكل لحية محلوقة، تجرحت الأيدي وتمنطقت الأحقاء بالمسوح.","48:38":"شاع النوح على سطوح موآب وفي شوارعها كلها، لأني حطمت موآب كإناء ليس لأحد رغبة فيه، يقول الرب.","48:39":"لشد ما تحطمت! لشد ما يولولون: كيف أدبر موآب مجللا بالخزي؟ قد صار مثار هزء ورعب لكل من حوله».","48:40":"لأن هذا ما يعلنه الرب: «انظروا، ها واحد يطير مسرعا كالنسر باسطا جناحيه ضد موآب.","48:41":"فيستولي على المدن، وتسقط الحصون، وتصبح في ذلك اليوم قلوب محاربي موآب كقلب امرأة في مخاضها.","48:42":"يهلك موآب ولا يبقى أمة، لأنه قد تغطرس على الرب.","48:43":"يترصدكم الرعب والحفرة والفخ ياأهل موآب، يقول الرب.","48:44":"من يهرب من الخوف يقع في الحفرة، ومن يصعد من الحفرة يعلق بالفخ، لأني أجلب على موآب هذه المحن في سنة عقابهم، يقول الرب.","48:45":"في ظل حشبون وقف الهاربون خائري القوى، لأن نارا اندلعت من حشبون، وشعلة من سيحون، فالتهمت ركن موآب وهامة المتبجحين الغوغائيين.","48:46":"ويل لك ياموآب! قد باد شعب كموش، لأن بنيك وبناتك أخذوا إلى السبي.","48:47":"ولكني أرد سبي موآب في الأيام الآتية»، يقول الرب. إلى هنا ختام القضاء على موآب.","49:1":"نبوءة عن بني عمون، هذا ما يعلنه الرب: «أليس لإسرائيل أبناء؟ أليس له وارث؟ فما بال ملك العمونيين قد استولى على ميراث سبط جاد وسكن شعبه في مدنه؟","49:2":"لذلك ها أيام مقبلة، يقول الرب، أجعل فيها هتاف القتال يتردد في ربة العمونيين، فتصير تلة أطلال، وتحرق قراها بالنار فيجلي الإسرائيليون الذين أجلوهم، يقول الرب.","49:3":"أعولي ياحشبون لأن عاي قد خربت. ابكين يابنات ربة وتمنطقن بالمسوح. اندبن واذرعن الأرض بين السياجات فإن ملككن سيذهب إلى السبي مع كهنته ورؤسائه جميعا.","49:4":"ما بالك تباهين بالأودية أيتها الابنة المخادعة التي اتكلت على نفائسها قائلة: من يهاجمني؟","49:5":"ها أنا أوقع بك الرعب من جميع المحيطين بك، فيتشرد كل واحد منكم مطرودا، وليس من يجمع شتات الهاربين.","49:6":"ثم أعود فأرد سبي العمونيين، يقول الرب».","49:7":"نبوءة عن الأدوميين: «هذا ما يعلنه الرب القدير: ألم تبق في تيمان حكمة بعد؟ هل بادت المشورة من ذوي الفهم؟ هل تلاشت حكمتهم؟","49:8":"اهربوا: أدبروا، اختبئوا في الأعماق ياسكان ددان، لأني سأوقع البلية بذرية عيسو في أوان عقابها.","49:9":"لو أقبل قاطفو العنب إليك، ألا يبقون خصاصة؟ ولو انسل اللصوص ليلا، ألا يقنعون بسلب ما يكفيهم؟","49:10":"أما أنا فقد جردت ذرية عيسو، وكشفت عن مخابئها السرية، وليس في وسعها الاختفاء. هلك أبناء عيسو وإخوته وجيرانه ولم يبق له أثر بعد.","49:11":"اترك أيتامك فإني أحييهم، ولتتكل أراملك علي.","49:12":"لأن هذا ما يعلنه الرب: إن كان الذين لا يستحقون تجرع كأس العقاب قد تجرعوه، أتفلت أنت من العقاب؟ إنك لن تفلت من العقاب، بل عليك أن تجرعه حتما.","49:13":"ها أنا قد أقسمت بنفسي، يقول الرب، أن تصبح بصرة عرضة للرعب والعار والخراب واللعنة، وتغدو مدنها خرائب دائمة.","49:14":"تبلغت رسالة من لدن الرب، أن سفيرا قد بعث إلى الأمم قائلا: «احشدوا أنفسكم لمهاجمتها. هبوا للقتال.","49:15":"قد جعلتك صغيرا في الأمم، حقيرا بين الناس.","49:16":"قد خدعك ما تثيره من رعب، وأغوتك كبرياء قلبك، يامن تقيم في شقوق الصخر وتعتصم بقمة التل. ولكنني سأطرحك من هناك ولو بنيت عشك عاليا كعش النسر، يقول الرب.","49:17":"ستصبح أدوم مثار رعب، وكل من يمر بها تعتريه رعدة، ويصفر من جراء كل نكباتها،","49:18":"ويصيبها ما أصاب سدوم وعمورة وما جاورهما، من انقلاب، يقول الرب، فلا يسكن هناك إنسان ولا يتغرب فيها أحد.","49:19":"ها هو ينقض على الأدوميين في مواطن صخورهم كما ينقض فجأة أسد من أجمات نهر الأردن؛ وفي لحظة أطردهم منها وأقيم عليها من أختاره، لأنه من هو مثلي؟ ومن يحاكمني؟ وأي راع يقوى على مواجهتي؟","49:20":"لذلك اسمعوا ما خططه الرب ضد أدوم، وما دبره ضد ساكني تيمان: ها صغار القوم يجرون، وتنهدم مساكنهم عليهم.","49:21":"من صوت سقوطهم ترجف الأرض، وأصداء صراخهم تبلغ البحر الأحمر.","49:22":"ها هو يحلق كالنسر، وينشر جناحيه على بصرة، فتصبح قلوب جبابرة أدوم كقلب امرأة ماخض».","49:23":"نبوءة عن دمشق: «قد لحق الخزي بحماة وأرفاد إذ بلغتهما الأنباء المزعجة، ذابتا خوفا واضطربتا كالبحر الهائج.","49:24":"خارت قوى دمشق وأدبرت لتهرب، واستولى عليها الرعب، وأدركها الكرب والألم كامرأة ماخض.","49:25":"كيف لم يبق على المدينة الشهيرة، مدينة مسرتي؟","49:26":"لذلك سيتساقط شبابها في ساحاتها، ويبيد جميع جنودها في ذلك اليوم، يقول الرب القدير.","49:27":"سأضرم النار في سور دمشق فتلتهم قصور بنهدد».","49:28":"نبوءة عن قيدار وممالك حاصور التي هاجمها نبوخذناصر: «هذا ما يعلنه الرب: هبوا وازحفوا على قيدار. دمروا أمم المشرق.","49:29":"فإن خيامهم وقطعان أغنامهم يستولى عليها، وتؤخذ أستارهم وأمتعتهم، وتنهب جمالهم منهم، ويهتف بهم الرجال: الرعب يحدق من كل جانب.","49:30":"اهربوا سريعا. تفرقوا. تواروا في الأعماق ياأهل حاصور، يقول الرب، لأن نبوخذناصر ملك بابل تآمر عليكم ودبر خطته ضدكم.","49:31":"هبوا، وازحفوا على أمة مترفة تسكن في دعة، يقول الرب. لا بوابات لها ولا مزاليج بل تسكن منفردة.","49:32":"ستصبح إبلهم غنيمة وماشيتهم سلبا، وأذري لكل ريح كل مقصوصي زوايا الشعر، وأوقع بهم البلية من كل جوانبهم، يقول الرب.","49:33":"فتصبح حاصور مأوى لبنات آوى، وخرابا إلى الأبد. لا يقيم هناك أحد، ولا يتغرب فيها إنسان».","49:34":"النبوءة التي أوحى بها الرب إلى إرميا عن عيلام في مستهل حكم صدقيا ملك يهوذا:","49:35":"هذا ما يعلنه الرب القدير: «ها أنا أحطم قوس عيلام، عماد قوتهم.","49:36":"وأرسل على عيلام الرياح الأربع من أطراف السماء الأربعة، وأذريهم لكل تلك الرياح، فلا تبقى أمة لا يسبى إليها العيلاميون.","49:37":"وأفزع عيلام أمام أعدائهم وأمام طالبي نفوسهم، وأعاقبهم بالشر وبغضبي اللاهب، وأجعل السيف يتعقبهم حتى أفنيهم.","49:38":"وأنصب عرشي في عيلام، وأقضي على ملكهم وعلى عظمائهم.","49:39":"ولكن أرد سبي عيلام في الأيام الآتية يقول الرب».","50:1":"النبوءة التي قضى بها الرب على بابل وعلى بلاد الكلدانيين على لسان إرميا النبي:","50:2":"«أذيعوا بين الأمم، وأعلنوا. انصبوا الراية وخبروا. لا تكتموا. قولوا: قد تم الاستيلاء على بابل ولحق ببيل العار وتحطم مرودخ. خربت أصنامها وانسحقت أوثانها.","50:3":"لأن أمة من الشمال قد زحفت عليها لتجعل أرضها مهجورة. شرد منها الناس والبهائم جميعا.","50:4":"وفي تلك الأيام، يقول الرب، يتوافد أبناء إسرائيل وأبناء يهوذا معا. يبكون في سيرهم ويلتمسون الرب إلههم.","50:5":"يسألون عن الطريق إلى صهيون، ويتوجهون إليها قائلين: هلم ننضم إلى الرب بعهد أبدي لا ينسى.","50:6":"إن شعبي كغنم ضالة، أضلهم رعاتهم، وشردوهم على الجبال، فتاهوا ما بين الجبل والتل ونسوا مربضهم.","50:7":"كل من وجدهم افترسهم، وقال أعداؤهم: لا ذنب علينا لأنهم هم الذين أخطأوا في حق الرب الذي هو ملاذهم الحق، ورجاء آبائهم.","50:8":"اهربوا من وسط بابل واخرجوا من ديار الكلدانيين وكونوا كالتيوس أمام قطيع الغنم.","50:9":"فها أنا أثير وأجلب على بابل حشود أمم عظيمة من أرض الشمال فيتألبون عليها، ويستولون عليها من الشمال، وتكون سهامهم كجبار متمرس لا يرجع فارغا،","50:10":"فتصبح أرض الكلدانيين غنيمة، وكل من يسلبها يتخم، يقول الرب.","50:11":"لأنكم تبتهجون وتطفرون غبطة يا ناهبي شعبي، وتمرحون كعجلة فوق العشب وتصهلون كالخيل.","50:12":"فإن أمكم قد لحقها الخزي الشديد وانتابها الخجل. ها هي تضحي أقل الشعوب، وأرضها تصير قفرا جافا وصحراء.","50:13":"وتظل بأسرها مهجورة وخربة، كل من يمر ببابل يصيبه الذعر ويصفر دهشة لما ابتليت به من نكبات، لأنها أثارت غضب الرب.","50:14":"اصطفوا على بابل من كل ناحية ياجميع موتري الأقواس. ارموا السهام ولا تبقوا منها سهما واحدا، لأنها قد أخطأت في حق الرب.","50:15":"أطلقوا هتاف الحرب عليها من كل جانب، فقد استسلمت وانهارت أسسها، وتقوضت أسوارها، لأن هذا هو انتقام الرب، فاثأروا منها، وعاملوها بمثل ما عاملتكم.","50:16":"استأصلوا الزارع من بابل والحاصد بالمنجل في موسم الحصاد إذ يرجع كل واحد إلى قومه، ويهرب إلى أرضه فرارا من سيف العاتي.","50:17":"إسرائيل قطيع غنم متشتت، طردته الأسود. كان ملك أشور أول من افترسه، ونبوخذناصر آخر من هشم عظامه.","50:18":"لذلك هذا ما يعلنه الرب القدير إله إسرائيل: ها أنا أعاقب ملك بابل وأرضه. كما عاقبت ملك أشور من قبل.","50:19":"وأرد إسرائيل إلى مرتعه، فيرعى في الكرمل وفي باشان، وتشبع نفسه في جبل أفرايم وجلعاد.","50:20":"وفي ذلك الزمان والأوان، يقول الرب، يلتمس إثم إسرائيل فلا يوجد، وخطيئة يهوذا فلا تكون، لأني أعفو عمن أبقيته منهما.","50:21":"ازحف على أرض ميراثايم (ومعناه: المفرط في التمرد)، وعلى المقيمين في فقود (ومعناه: العقاب). خرب، ودمر وراءهم، يقول الرب وافعل كل ما آمرك به.","50:22":"قد علت جلبة القتال في الأرض. صوت تحطيم عظيم.","50:23":"كيف تكسرت وتحطمت بابل، مطرقة الأرض كلها؟ كيف أصبحت بابل مثار دهشة عند الأمم؟","50:24":"قد نصبت الشرك فوقعت فيه، يابابل، من غير أن تشعري به. قد وجدت وقبض عليك، لأنك خاصمت الرب.","50:25":"قد فتح الرب مخزن سلاحه، وأخرج آلات سخطه، لأنه ما برح للسيد الرب القدير عمل ينجزه في ديار الكلدانيين.","50:26":"ازحفوا عليها من أقاصي الأرض، وافتحوا أهراءها، وكوموها أعراما واقضوا عليها قاطبة ولا تتركوا منها بقية.","50:27":"اذبحوا جميع ثيرانها، أحضروها للذبح. ويل لهم لأن يوم موعد عقابهم قد حان.","50:28":"اسمعوا! ها جلبة الفارين الناجين من ديار بابل لكي يذيعوا في صهيون أنباء انتقام الرب إلهنا والثأر لهيكله.","50:29":"استدعوا إلى بابل رماة السهام، جميع موتري القسي. عسكروا حولها فلا يفلت منها أحد. جازوها بمقتضى أعمالها، واصنعوا بها كما صنعت بكم، لأنها بغت على الرب قدوس إسرائيل.","50:30":"لذلك يصرع شبانها في ساحاتها، ويبيد في ذلك اليوم جميع جنودها، يقول الرب.","50:31":"ها أنا أقاومك أيتها المتغطرسة، يقول الرب القدير، لأن يوم إدانتك وتنفيذ العقاب فيك قد حان،","50:32":"فيتعثر المتغطرس ويكبو ولا يوجد من ينهضه، وأضرم نارا في مدنه فتلتهم ما حوله».","50:33":"وهذا ما يعلنه الرب القدير: «قد وقع الظلم على شعب إسرائيل وعلى شعب يهوذا، وجميع الذين سبوهم تشبثوا بهم وأبوا أن يطلقوهم.","50:34":"غير أن فاديهم قوي، الرب القدير اسمه، وهو حتما يدافع عن قضيتهم لكي يشيع راحة في الأرض ويقلق أهل بابل.","50:35":"ها سيف على الكلدانيين، يقول الرب، وعلى أهل بابل، وعلى أشرافها، وعلى حكمائها.","50:36":"ها سيف على عرافيها، فيصبحون حمقى. وها سيف على محاربيها، فيمتلئون رعبا.","50:37":"ها سيف على خيلها، وعلى مركباتها، وعلى فرق مرتزقتها، فيصيرون كالنساء. ها سيف على كنوزها فتنهب.","50:38":"ها الحر على مياهها فيصيبها الجفاف لأنها أرض أصنام، وقد أولع أهلها بالأوثان.","50:39":"لذلك يسكنها وحش القفر مع بنات آوى، وتأوي إليها رعال النعام، وتظل مهجورة إلى الأبد، غير آهلة بالسكان إلى مدى الدهر.","50:40":"وكما قلب الله سدوم وعمورة وما جاورهما، هكذا لن يسكن فيها أحد أو يقيم فيها إنسان.","50:41":"ها شعب مقبل من الشمال، أمة عظيمة ولفيف من الملوك قد هبوا من أقاصي الأرض.","50:42":"يمسكون بالقسي ويتقلدون بالرماح. قساة لا يعرفون الرحمة، جلبتهم كهدير البحر، يمتطون الخيل وقد اصطفوا كرجل واحد لمحاربتك يابنت بابل.","50:43":"قد بلغ خبرهم ملك بابل فاسترخت يده وانتابته الضيقة ووجع امرأة في مخاضها.","50:44":"انظر، ها هو كما ينقض عليها كما ينقض أسد من أجمات نهر الأردن، هكذا وفي لحظة أطردهم منها، وأولي عليها من أختاره لأنه من هو نظيري؟ ومن يحاكمني؟ وأي راع يقوى على مواجهتي؟","50:45":"لذلك اسمعوا ما خططه الرب ضد بابل، وما دبره ضد ديار الكلدانيين. ها صغارهم يجرون جرا، ويخرب مساكنهم عليهم.","50:46":"من دوي أصداء سقوط بابل ترجف الأرض، ويتردد صراخها بين الأمم.","51:1":"وهذا ما يعلنه الرب: ها أنا أثير على بابل وعلى المقيمين في ديار الكلدانيين ريحا مهلكة.","51:2":"وأبعث إلى بابل مذرين يذرونها، ويجعلون أرضها قفرا، ويهاجمونها من كل جانب في يوم بليتها.","51:3":"ليوتر الرامي قوسه وليتدجج بسلاحه. لا تعفوا عن شبانها، بل أبيدوا كل جيشها إبادة.","51:4":"يتساقط القتلى في أرض الكلدانيين، والجرحى في شوارعها،","51:5":"لأن إسرائيل ويهوذا لم يهملهما الرب القدير وإن تكن أرضهما تفيض بالإثم ضد قدوس إسرائيل.","51:6":"اهربوا من وسط بابل، ولينج كل واحد بحياته. لا تبيدوا من جراء إثمها، لأن هذا هو وقت انتقام الرب، وموعد مجازاتها.","51:7":"كانت بابل كأس ذهب في يد الله، فسكر ت الأرض قاطبة. تجرعت الأمم من خمرها، لذلك جنت الشعوب.","51:8":"فجأة سقطت بابل وتحطمت، فولولوا عليها، خذوا بلسانا لجرحها لعلها تبرأ.","51:9":"قمنا بمداواة بابل، ولكن لم ينجع فيها علاج. اهجروها وليمض كل واحد منا إلى أرضه، لأن قضاءها قد بلغ عنان السماء، وتصاعد حتى ارتفع إلى الغيوم.","51:10":"قد أظهر الرب برنا، فتعالوا لنذيع في صهيون ما صنعه الرب إلهنا.","51:11":"سنوا السهام، وتقلدوا الأتراس، لأن الرب قد أثار روح ملوك الماديين، إذ وطد العزم على إهلاك بابل، لأن هذا هو انتقام الرب، والثأر لهيكله.","51:12":"انصبوا راية على أسوار بابل. شددوا الحراسة. أقيموا الأرصاد. أعدوا الكمائن، لأن الرب قد خطط وأنجز ما قضى به على أهل بابل.","51:13":"أيتها الساكنة إلى جوار المياه الغزيرة، ذات الكنوز الوفيرة، إن نهايتك قد أزفت، وحان موعد اقتلاعك.","51:14":"قد أقسم الرب القدير بذاته قائلا: لأملأنك أناسا كالغوغاء فتعلو جلبتهم عليك.","51:15":"هو الذي صنع الأرض بقدرته، وأسس الدنيا بحكمته، ومد السماوات بفطنته.","51:16":"ما إن ينطق بصوته حتى تتجمع غمار المياه في السماوات، وتصعد السحب من أقاصي الأرض، ويجعل للمطر بروقا، ويطلق الريح من خزائنه.","51:17":"كل امريء خامل وعديم المعرفة، وكل صائغ خزي من تمثاله، لأن صنمه المسبوك كاذب ولا حياة فيه.","51:18":"جميع الأصنام باطلة وصنعة ضلال، وفي زمن عقابها تبيد.","51:19":"أما نصيب يعقوب فليس مثل هذه الأوثان، بل هو جابل كل الأشياء. وشعب إسرائيل هو سبط ميراثه، واسمه الرب القدير.","51:20":"أنت فأس معركتي وآلة حربي. بك أمزق الأمم إربا وأحطم ممالك.","51:21":"بك أجعل الفرس وفارسها أشلاء، وأهشم المركبة وراكبها.","51:22":"بك أحطم الرجل والمرأة، والشيخ والفتى، والشاب والعذراء.","51:23":"بك أسحق الراعي وقطيعه، والحارث وفدانه، والحكام والولاة.","51:24":"سأجازي بابل وسائر الكلدانيين على كل شرهم الذي ارتكبوه في حق صهيون، على مرأى منكم، يقول الرب.","51:25":"ها أنا أنقلب عليك أيها الجبل المخرب، يقول الرب. أنت تفسد كل الأرض، لذلك أمد يدي عليك وأدحرجك من بين الصخور، وأجعلك جبلا محترقا.","51:26":"فلا يقطع منك حجر لزاوية، ولا حجر يوضع كأساس، بل تكون خرابا أبديا، يقول الرب.","51:27":"انصبوا راية في الأرض. انفخوا في البوق بين الأمم. أثيروا عليها الأمم لقتالها، وألبوا عليها ممالك أراراط ومني وأشكناز. أقيموا عليها قائدا. اجعلوا الخيل تزحف عليها كجحافل الجنادب الشرسة.","51:28":"أثيروا عليها الأمم وملوك الماديين وكل حكامهم وولاتهم وسائر الديار التي يحكمونها.","51:29":"الأرض ترجف وتقشعر، لأن قضاء الرب على بابل يتم، ليجعل أرض بابل خرابا وقفرا.","51:30":"قد أحجم محاربو بابل الجبابرة عن القتال، واعتصموا في معاقلهم. خارت شجاعتهم، وصاروا كالنساء. احترقت مساكن بابل وتحطمت مزاليجها.","51:31":"يركض عداء لملاقاة عداء آخر. ويسرع مخبر للقاء مخبر ليبلغ ملك بابل أن مدينته قد تم الاستيلاء عليها من كل جانب.","51:32":"قد سقطت المعابر وأحرقت أجمات القصب بالنار واعترى الذعر المحاربين،","51:33":"لأن هذا ما يعلنه الرب القدير إله إسرائيل: إن أهل بابل كالبيدر، وقد حان أوان درس حنطته. وبعد قليل يأزف موعد حصادهم.","51:34":"«يقول المسبيون: قد افترسنا نبوخذناصر ملك بابل وسحقنا وجعلنا إناء فارغا. ابتلعنا كتنين، وملأ جوفه من أطايبنا، ثم لفظنا من فمه.","51:35":"يقول أهل أورشليم: ليحل ببابل ما أصابنا وأصاب لحومنا من ظلم. وتقول أورشليم: دمي على أهل أرض الكلدانيين.","51:36":"لذلك هذا ما يعلنه الرب: ها أنا أدافع عن دعواك وأنتقم لك، فأجفف بحر بابل وينابيعها،","51:37":"فتصير بابل ركاما ومأوى لبنات آوى، ومثار دهشة وصفير وأرضا موحشة.","51:38":"إنهم يزأرون كالأسود ويزمجرون كالأشبال.","51:39":"عند شبعهم أعد لهم مأدبة وأسكرهم حتى تأخذهم النشوة فينامون نوما أبديا لا يقظة منه، يقول الرب.","51:40":"وأحضرهم كالحملان للذبح وكالكباش والتيوس.","51:41":"كيف استولي على بابل! كيف سقطت فخر كل الأرض! كيف صارت بابل مثار دهشة بين الأمم!","51:42":"قد طغى البحر على بابل فغمرها بأمواجه الهائجة،","51:43":"وأصبحت مدنها موحشة وأرض قفر وصحراء، أرضا لا يأوي إليها أحد ولا يجتاز بها إنسان.","51:44":"وأعاقب الصنم: بيل في بابل، وأستخرج من فمه ما ابتلعه، فتكف الأمم عن التوافد إليه، وينهدم أيضا سور بابل.","51:45":"اخرجوا من وسطها ياشعبي ولينج كل واحد بحياته هربا من احتدام غضب الرب.","51:46":"لا يخر قلبكم ولا تفزعوا مما يشيع في الديار من أنباء، إذ تروج شائعة في هذه السنة وأخرى في السنة التالية، ويسود العنف الأرض، ويقوم متسلط على متسلط.","51:47":"لذلك ها أيام مقبلة أعاقب فيها أصنام بابل ويلحق العار بأرضها كلها، ويتساقط قتلاها في وسطها.","51:48":"عندئذ تتغنى بسقوط بابل السماوات والأرض وكل ما فيها، لأن المدمرين يتقاطرون عليها من الشمال، يقول الرب.","51:49":"كما صرعت بابل قتلى إسرائيل، هكذا يصرع قتلى بابل في كل الأرض.","51:50":"ياأيها الناجون من السيف، اهربوا ولا تقفوا، اذكروا الرب في مكانكم البعيد، ولا تبرح أورشليم من خواطركم.","51:51":"قد لحقنا الخزي لأننا استمعنا للإهانة، فكسا الخجل وجوهنا، إذ انتهك الغرباء مقادس هيكل الرب.","51:52":"لذلك ها أيام مقبلة، يقول الرب، أنفذ فيها قضائي على أصنام بابل، ويئن جرحاها في كل ديارها.","51:53":"وحتى لو ارتفعت بابل فبلغت السماء، وحتى لو حصنت معاقلها الشامخة، فإن المدمرين ينقضون عليها من عندي، يقول الرب.","51:54":"ها صوت صراخ يتردد في بابل، صوت جلبة دمار عظيم من أرض الكلدانيين،","51:55":"لأن الرب قد خرب بابل، وأخرس جلبتها العظيمة، إذ طغت عليها جحافل أعدائها كمياه عجاجة، وعلا ضجيج أصواتهم.","51:56":"لأن المدمر قد انقض على بابل وأسر محاربيها، وتكسرت كل قسيها، لأن الرب إله مجازاة، وهو حتما يحاسبها.","51:57":"إني أسكر رؤساءها وحكماءها ومحاربيها، فينامون نوما أبديا لا يقظة منه، يقول الملك، الرب القدير اسمه.","51:58":"وهذا ما يعلنه الرب القدير: إن سور بابل العريض يقوض ويسوى بالأرض، وبواباتها العالية تحترق بالنار، ويذهب تعب الشعوب باطلا، ويكون مصير جهد الأمم للنار».","51:59":"هذه هي النبوءة التي أودعها إرميا النبي سرايا بن نيريا بن محسيا، عندما رافق صدقيا ملك يهوذا إلى بابل في السنة الرابعة لحكمه. وكان سرايا آنئذ رئيس المعسكر.","51:60":"وكان إرميا قد دون في كتاب واحد جميع الكوارث التي ستبتلى بها بابل، أي جميع النبوءات المدونة عن بابل.","51:61":"وقال إرميا لسرايا: «حالما تصل إلى بابل، اعمل على تلاوة جميع هذه النبوءات.","51:62":"وقل: أيها الرب قد قضيت على هذا الموضع بالانقراض، فلا يسكن فيه أحد من الناس والبهائم، بل يصبح خرابا أبديا.","51:63":"ومتى فرغت من تلاوة هذا الكتاب، اربط به حجرا واطرحه في وسط الفرات.","51:64":"وقل: كذلك تغرق بابل ولا تطفو بعد لما أوقعه عليها من عقاب فيعيا كل أهلها».إلى هنا تنتهي نبوءات إرميا.","52:1":"كان صدقيا في الحادية والعشرين من عمره حين ملك، وتولى الحكم في أورشليم إحدى عشرة سنة، واسم أمه حميطل بنت إرميا من لبنة.","52:2":"وارتكب الشر في عيني الرب على غرار ما عمل يهوياقيم.","52:3":"ولم يكن ما أصاب أورشليم ويهوذا إلا نتيجة لغضب الرب، حتى إنه نبذهم من حضرته. وتمرد صدقيا على ملك بابل.","52:4":"وفي اليوم العاشر من الشهر العاشر من السنة التاسعة لحكمه، زحف نبوخذناصر ملك بابل بجيشه على أورشليم وحاصرها وبنى حولها المتاريس.","52:5":"وظلت المدينة تحت الحصار حتى السنة الحادية عشرة من حكم صدقيا.","52:6":"وفي اليوم التاسع من الشهر الرابع استفحل الجوع في المدينة حتى لم يبق طعام لشعب الأرض.","52:7":"ففتح الشعب ثغرة في المدينة وهرب جميع المحاربين وغادروا المدينة ليلا من طريق البوابة الواقعة بين السورين القريبين من بستان الملك، والكلدانيون ما برحوا محاصرين المدينة من كل جهة، وانطلقوا في طريق البرية.","52:8":"لكن جيش الكلدانيين تعقب الملك، وأدرك صدقيا في سهول أريحا وقد تفرق عنه جميع جيشه،","52:9":"فقبضوا عليه وأخذوه إلى ملك بابل في ربلة، في منطقة حماة، فأصدر عليه قضاءه.","52:10":"وذبح ملك بابل أبناء صدقيا على مرأى منه وقتل أيضا جميع أشراف يهوذا في ربلة.","52:11":"وفقأ عيني صدقيا وأوثقه بسلسلتين من نحاس، ثم ساقه إلى بابل حيث زجه في السجن إلى يوم وفاته.","52:12":"وفي اليوم العاشر من الشهر الخامس من السنة التاسعة عشرة من حكم نبوخذناصر ملك بابل، جاء نبوزرادان رئيس الشرطة الذي كان يقف دائما في حضرة ملك بابل، إلى أورشليم،","52:13":"وأحرق هيكل الرب وقصر الملك وجميع بيوت أورشليم، وأضرم النار في كل بيت من بيوت العظماء،","52:14":"وهدم كل جيش الكلدانيين المرافق لرئيس الشرطة كل أسوار أورشليم المحيطة بها.","52:15":"وأجلى نبوزرادان رئيس الشرطة بعضا من فقراء البلد، ومن بقي من الشعب في المدينة، والهاربين الذين لجأوا إلى ملك بابل مع سائر الحرفيين.","52:16":"ولكنه أبقى على بعض المساكين ليكونوا كرامين وفلاحين.","52:17":"وحطم الكلدانيون أعمدة النحاس في هيكل الرب، والقواعد والبركة النحاسية القائمة فيه، ونقلوا كل نحاسها إلى بابل.","52:18":"واستولوا أيضا على القدور والرفوش والمجارف والمناضح والصحون وكل آنية النحاس التي كانت تستخدم في الهيكل.","52:19":"كما أخذ رئيس الشرطة الطسوس والمجامر والمناضح والقدور والمنائر والصحون والأقداح الذهبية والفضية.","52:20":"كذلك استولى على العمودين والبركة والاثني عشر ثورا من نحاس القائمة تحت القواعد التي صنعها الملك سليمان لهيكل الرب، فكان النحاس لكثرته يفوق كل وزن.","52:21":"وكان طول كل عمود ثماني عشرة ذراعا (نحو تسعة أمتار)، ومحيطه اثنتي عشرة ذراعا (نحو ستة أمتار)، وسمكه أربع أصابع، وكان أجوف،","52:22":"وعليه تاج من نحاس ارتفاعه خمس أذرع (نحو مترين ونصف المتر) ويحيط بالتاج شبكة ورمانات وكلها مصنوعة من نحاس. وكان العمود الثاني مماثلا له بما في ذلك الرمانات.","52:23":"وكان عدد الرمانات على محيطه ستا وتسعين رمانة، وجملة الرمان على محيط الشبكة مئة رمانة.","52:24":"وأخذ رئيس الشرطة سرايا رئيس الكهنة ونائبه صفنيا الكاهن وحراس الباب الثلاثة.","52:25":"واعتقل من المدينة الخصي القائد الذي كان يتولى قيادة المحاربين، كما اعتقل سبعة رجال من حاشية الملك ممن عثر عليهم في المدينة، وكذلك أمين سر قائد الجيش الذي كان يجند شعب البلد، وستين رجلا من أهل الأرض الذين كانوا قد اختبأوا داخل المدينة.","52:26":"فأخذهم نبوزرادان رئيس الشرطة وساقهم إلى ملك بابل في ربلة،","52:27":"فضربهم ملك بابل وقتلهم في ربلة في منطقة حماة. وهكذا سبي شعب يهوذا من أرضه.","52:28":"وهذا هو إحصاء الشعب الذين سباهم نبوخذناصر في السنة السابعة: ثلاثة آلاف وثلاثة وعشرون من اليهود.","52:29":"وسبى نبوخذناصر من أورشليم في السنة الثامنة عشرة لحكمه ثماني مئة واثنين وثلاثين شخصا.","52:30":"وفي السنة الثالثة والعشرين لحكم نبوخذناصر سبى نبوزرادان رئيس الشرطة من اليهود سبع مئة وخمسة وأربعين شخصا، فكانت جملة المسبيين أربعة آلاف وست مئة شخص.","52:31":"وفي اليوم الخامس والعشرين من الشهر الثاني عشر(أي شباط فبراير) من السنة السابعة والثلاثين لسبي يهوياكين ملك يهوذا، أكرم أويل مرودخ، ملك بابل، في سنة اعتلائه العرش، يهوياكين ملك يهوذا وأخرجه من السجن.","52:32":"وخاطبه بطيب الكلام، ورفع مقامه فوق مقام سائر الملوك الذين معه في بابل.","52:33":"فخلع يهوياكين عن نفسه ثياب سجنه، وظل يتناول الطعام في حضرة ملك بابل طوال أيام حياته.","52:34":"وعينت له نفقة دائمة يقبضها من خزانة مال الملك كل يوم بيومه مدى أيام حياته، وإلى يوم وفاته."};
